def _update_ssl_context():
    """Paketlenmiş (.app) sürümde bazen sistemin kök sertifikaları bulunamayabiliyor;
    certifi varsa onu kullan, yoksa doğrulamasız bağlan (yalnızca GitHub'dan okuma için)."""
    import ssl
    try:
        import certifi
        return ssl.create_default_context(cafile=certifi.where())
    except Exception:
        try:
            return ssl._create_unverified_context()
        except Exception:
            return None


def _verified_ssl_context():
    """API anahtarı gönderilen bağlantılar için: certifi varsa onunla, yoksa sistemin varsayılanıyla DOĞRULAYARAK bağlan."""
    try:
        import ssl
        import certifi
        return ssl.create_default_context(cafile=certifi.where())
    except Exception:
        return None


