def turkish_title(text: str) -> str:
    """Türkçe karakter duyarlı basit title-case (i/İ - ı/I sorununu çözer)."""
    def cap_word(w):
        if not w:
            return w
        first = w[0]
        rest = w[1:]
        tr_upper_map = {"i": "İ", "ı": "I"}
        first_upper = tr_upper_map.get(first, first.upper())
        return first_upper + turkish_lower(rest)
    return " ".join(cap_word(w) for w in text.split(" ") if w)


def turkish_lower(text: str) -> str:
    """Türkçe karakter duyarlı .lower() (İ -> i; birleşik nokta U+0307 oluşmaz. I -> i kalır: yabancı isimler için)."""
    return text.replace("İ", "i").lower()


def turkish_upper(text: str) -> str:
    """Türkçe karakter duyarlı .upper() (i -> İ, ı -> I)."""
    return text.replace("i", "İ").replace("ı", "I").upper()


def strip_accents_upper(text: str) -> str:
    """Türkçe özel karakterleri sadeleştirip büyük harfe çevirir (karşılaştırma için)."""
    repl = {"Ğ": "G", "Ü": "U", "Ş": "S", "İ": "I", "Ö": "O", "Ç": "C"}
    text = turkish_upper(text)
    for a, b in repl.items():
        text = text.replace(a, b)
    return text


def clean_reference_name(filename_stem: str) -> str:
    """
    Referans dosya adlarını temizleyip ortak oyuncu ismine indirger.
    Örn:  can_1 -> Can | can 2 -> Can | serdar_2 -> Serdar | Can-3 -> Can
    """
    name = filename_stem.strip()
    name = re.sub(r"[_\-]+", " ", name)                 # alt tire/tire -> boşluk
    name = re.sub(r"\s*\d+\s*$", "", name)               # sondaki sayıyı temizle
    name = re.sub(r"\s+", " ", name).strip()
    return turkish_title(name)


def get_desktop_path() -> str:
    home = os.path.expanduser("~")
    desktop = os.path.join(home, "Desktop")
    return desktop if os.path.isdir(desktop) else home


def get_today_output_folder(base_dir: str = "") -> str:
    now = datetime.now()
    folder_name = f"{now.day} {TURKISH_MONTHS[now.month]}"
    root = base_dir if (base_dir and os.path.isdir(base_dir)) else get_desktop_path()
    return os.path.join(root, folder_name)


def unique_destination_path(dest_dir: str, filename: str) -> str:
    base, ext = os.path.splitext(filename)
    candidate = os.path.join(dest_dir, filename)
    counter = 1
    while os.path.exists(candidate):
        candidate = os.path.join(dest_dir, f"{base}_{counter}{ext}")
        counter += 1
    return candidate


def list_image_files(root_folder: str):
    result = []
    for dirpath, _, filenames in os.walk(root_folder):
        for fn in filenames:
            if os.path.splitext(fn)[1].lower() in IMAGE_EXTENSIONS:
                result.append(os.path.join(dirpath, fn))
    return result


def imread_unicode(path: str):
    """Türkçe karakterli / unicode dosya yollarında da güvenli okuma yapar."""
    try:
        with open(path, "rb") as f:
            data = np.frombuffer(f.read(), dtype=np.uint8)
        return cv2.imdecode(data, cv2.IMREAD_COLOR)
    except Exception:
        return None


def face_focus_metrics(face, img):
    """Bir yüzün 'odak' ölçüleri: (netlik, kısa kenar px, normalize merkez uzaklığı).
    Netlik = yüz kırpımı 96x96'ya indirilip Laplacian varyansı alınır (yüz boyutundan bağımsız kıyas için).
    Uzaklık: 0 = kare merkezi, ~1 = kenar (yatay/dikey yarım genişliğe göre normalize)."""
    x1, y1, x2, y2 = [float(v) for v in face.bbox]
    h_img, w_img = img.shape[:2]
    xa, ya = max(0, int(x1)), max(0, int(y1))
    xb, yb = min(w_img, int(x2)), min(h_img, int(y2))
    crop = img[ya:yb, xa:xb]
    if crop.size == 0:
        sharp = 0.0
    else:
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
        gray = cv2.resize(gray, (96, 96), interpolation=cv2.INTER_AREA)
        sharp = float(cv2.Laplacian(gray, cv2.CV_64F).var())
    min_side = max(0.0, min(x2 - x1, y2 - y1))
    dx = ((x1 + x2) / 2.0 - w_img / 2.0) / (w_img / 2.0)
    dy = ((y1 + y2) / 2.0 - h_img / 2.0) / (h_img / 2.0)
    return sharp, min_side, float(np.hypot(dx, dy))


def face_quality_score(face, img, match_score: float = 0.0) -> float:
    """0–100 arası 'paylaşmaya değer mi' puanı: netlik, yüz boyutu, kadraj merkezi, tespit güveni, eşleşme skoru.
    'En iyi fotoğraflar' seçimi bu puanı kullanır (ör. oyuncu başına ilk 5)."""
    try:
        sharp, side, dist = face_focus_metrics(face, img)
        s = min(1.0, math.log1p(max(sharp, 0.0)) / math.log1p(600.0))
        z = min(1.0, side / 260.0)
        c = max(0.0, 1.0 - min(dist, 1.0) * 0.5)
        d = float(getattr(face, "det_score", 0.8) or 0.8)
        m = min(1.0, max(0.0, (float(match_score) - 0.3) / 0.4))
        return round(100.0 * (0.35 * s + 0.30 * z + 0.10 * c + 0.10 * min(1.0, d) + 0.15 * m), 1)
    except Exception:
        return 0.0


def find_background_faces(faces, img) -> set:
    """
    ODAK DIŞI / ARKA PLAN YÜZLERİ: Karede birden fazla yüz varken, fotoğrafın asıl öznesi olmayan
    yüzlerin indekslerini döndürür. Yüz, AYNI karedeki en net yüze göre:
      - çok bulanıksa (odak başka birinde), ya da
      - kare merkezinden uzaklaştıkça daha da yüksek netlik isteyerek (kenardaki bulanık kişi), ya da
      - en büyük yüze göre çok küçükse
    arka plan sayılır. En belirgin ("odak") yüz hiçbir zaman elenmez; tek yüzlü karede hiçbir şey elenmez.
    """
    if len(faces) < 2:
        return set()
    metrics = [face_focus_metrics(f, img) for f in faces]
    max_sharp = max(m[0] for m in metrics) or 1.0
    max_side = max(m[1] for m in metrics) or 1.0
    anchor = max(range(len(faces)), key=lambda i: metrics[i][0] * metrics[i][1] ** 2)
    skipped = set()
    for i, (sharp, side, dist) in enumerate(metrics):
        if i == anchor:
            continue
        need = BG_MIN_SHARP_REL + BG_EDGE_SHARP_BONUS * min(1.0, dist / BG_EDGE_DIST)
        if sharp / max_sharp < need or side / max_side < BG_MIN_SIZE_REL:
            skipped.add(i)
    return skipped


def identify_all_faces(faces, img, ref_db: dict, threshold: float, margin: float, quality_filter: bool,
                       info: dict | None = None):
    """
    ÇOKLU YÜZ ALGORİTMASI: Karedeki fotoğrafın ASIL öznesi olan her yüz ayrı ayrı kalite süzgecinden
    ve eşleştirmeden geçer; tanınan her oyuncu fotoğrafı kendi klasörüne alır (gol sevinci, ikili
    mücadele, toplu çekim). Arka plandaki / odak dışı yüzler (bkz. find_background_faces) ve tanınmayan
    yüzler (rakip, seyirci, belirsiz) göz ardı edilir — fotoğraf yalnızca HİÇBİR yüz eşleşmezse KARIŞIK'a gider.
    Arka plan ayrımı "Kalite filtresi" ayarına bağlıdır (kapalıysa karedeki bütün yüzler değerlendirilir).

    Döner: (eşleşmeler: {isim: en_iyi_skor}, ret_sebebi: str | None, ret_skoru: float, atlanan_arka_plan: int)
    Ret sebebi yalnızca hiç eşleşme yoksa doludur ve en BÜYÜK (en belirgin) yüzün sebebidir.
    """
    faces = list(faces or [])
    skipped = find_background_faces(faces, img) if quality_filter else set()
    matches = {}
    rejected = []  # (yüz_alanı, skor, sebep, adaylar)
    quality = {}
    for i, face in enumerate(faces):
        if i in skipped:
            continue
        x1, y1, x2, y2 = face.bbox
        area = max(0.0, float(x2 - x1)) * max(0.0, float(y2 - y1))
        if quality_filter:
            ok, q_reason = face_quality_check(face, img)
            if not ok:
                rejected.append((area, 0.0, q_reason, []))
                continue
        detail = {}
        name, score, reason = match_embedding_with_margin(face.normed_embedding, ref_db, threshold, margin, detail)
        if name is None:
            rejected.append((area, score, reason, detail.get("top", [])))
            continue
        if score > matches.get(name, -1.0):  # aynı oyuncu iki yüzle eşleşirse en iyi skor kalır
            matches[name] = score
        if info is not None:
            q = face_quality_score(face, img, score)
            if q > quality.get(name, -1.0):
                quality[name] = q
    if info is not None:
        info["quality"] = quality
    if matches:
        return matches, None, 0.0, len(skipped)
    if not rejected:
        return {}, "yüz bulunamadı", 0.0, len(skipped)
    _, score, reason, cands = max(rejected, key=lambda r: r[0])
    if info is not None:
        info["candidates"] = cands
    return {}, reason, score, len(skipped)


def face_quality_check(face, img):
    """
    Bir yüzün eşleştirmeye sokulacak kadar güvenilir olup olmadığını denetler.
    BİLEREK sadece objektif olarak kullanılamaz kareleri eler (çok küçük / aşırı bulanık).
    Açı (profil, yan, 3/4) burada ELENMEZ — ArcFace tabanlı embedding'ler poza karşı
    dayanıklıdır ve referans havuzunda birden fazla açı olduğunda yan çekimler de doğru
    eşleşir; açıyı elemek doğru fotoğrafları gereksiz yere KARIŞIK'a düşürmekten başka
    bir işe yaramaz.
    Döner: (uygun_mu: bool, sebep: str)
    """
    x1, y1, x2, y2 = face.bbox
    w, h = x2 - x1, y2 - y1
    if min(w, h) < MIN_FACE_SIZE_PX:
        return False, f"çok küçük yüz ({int(min(w, h))}px)"

    x1c, y1c = max(0, int(x1)), max(0, int(y1))
    x2c, y2c = min(img.shape[1], int(x2)), min(img.shape[0], int(y2))
    crop = img[y1c:y2c, x1c:x2c]
    if crop.size == 0:
        return False, "geçersiz kırpma alanı"

    gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
    blur_score = cv2.Laplacian(gray, cv2.CV_64F).var()
    if blur_score < BLUR_VARIANCE_THRESHOLD:
        return False, f"aşırı bulanık (skor={blur_score:.1f})"

    return True, ""


def enhance_image_for_detection(img):
    """
    CLAHE (Contrast Limited Adaptive Histogram Equalization) ile LAB renk uzayının
    L (parlaklık) kanalında yerel kontrastı artırır. Bu, özellikle:
      - Zor/dengesiz stadyum ışığı (gölge/güneş karışımı, projektör),
      - Ters ışık / arkadan aydınlatma,
      - Koyu ten tonlarında standart kamera pozlamasının genelde yetersiz kaldığı,
        yüzdeki yerel kontrastı düşüren durumlar
    gibi senaryolarda hem tespit hem tanıma başarısını belirgin şekilde artırır.
    Renk bilgisini (a/b kanalları) bozmadan sadece parlaklık kontrastını dengeler.
    Hem tespit hem tanıma aynı geliştirilmiş görüntü üzerinden yapılır ki landmark
    hizalaması ile embedding çıkarımı tutarlı kalsın.
    """
    try:
        lab = cv2.cvtColor(img, cv2.COLOR_BGR2LAB)
        l_channel, a_channel, b_channel = cv2.split(lab)
        clahe = cv2.createCLAHE(clipLimit=2.5, tileGridSize=(8, 8))
        l_enhanced = clahe.apply(l_channel)
        enhanced = cv2.merge((l_enhanced, a_channel, b_channel))
        return cv2.cvtColor(enhanced, cv2.COLOR_LAB2BGR)
    except Exception:
        return img


def match_embedding_with_margin(embedding: np.ndarray, ref_db: dict,
                                 threshold: float, margin: float, detail: dict | None = None):
    """
    Yüz embedding'ini referans veritabanıyla kıyaslar. İki katmanlı karar verir:
      1) En yüksek skor eşik değerinin altındaysa -> eşleşme yok.
      2) En yüksek skor ile ikinci en yüksek skor arasındaki fark 'margin' değerinden
         küçükse -> sonuç belirsiz kabul edilir (iki oyuncu birbirine çok yakın skorlanmış),
         güvenilmez eşleşmeyi engellemek için "eşleşme yok" döndürülür.
    Döner: (isim ya da None, en_iyi_skor, sebep)
    """
    if embedding is None or not ref_db:
        return None, 0.0, "referans veritabanı boş"

    norm = np.linalg.norm(embedding)
    if norm == 0:
        return None, 0.0, "geçersiz embedding"
    emb_normalized = embedding / norm

    per_name_best = {}
    for name, emb_list in ref_db.items():
        best_for_name = max(float(np.dot(emb_normalized, ref_emb)) for ref_emb in emb_list)
        per_name_best[name] = best_for_name

    ranked = sorted(per_name_best.items(), key=lambda kv: kv[1], reverse=True)
    best_name, best_score = ranked[0]
    second_score = ranked[1][1] if len(ranked) > 1 else -1.0
    if detail is not None:
        detail["top"] = [(n, float(sc)) for n, sc in ranked[:3]]  # inceleme ekranı için ilk 3 aday

    if best_score < threshold:
        return None, best_score, "eşik altı"
    if (best_score - second_score) < margin:
        return None, best_score, "belirsiz eşleşme (iki oyuncu skoru birbirine çok yakın)"

    return best_name, best_score, ""


def make_thumbnail_bytes(img_bgr, max_w: int = 280) -> bytes:
    """Bir görüntüyü küçültüp JPEG bayt dizisine çevirir (arayüzde canlı önizleme için)."""
    try:
        h, w = img_bgr.shape[:2]
        if w > max_w:
            scale = max_w / float(w)
            img_bgr = cv2.resize(img_bgr, (max_w, max(1, int(h * scale))), interpolation=cv2.INTER_AREA)
        ok, buf = cv2.imencode(".jpg", img_bgr, [int(cv2.IMWRITE_JPEG_QUALITY), 82])
        return buf.tobytes() if ok else b""
    except Exception:
        return b""


# ==========================================================================================
# YÜZ TANIMA MOTORU (InsightFace + Apple Silicon donanım ivmesi)
# ==========================================================================================

# InsightFace'in kendi kendine indiremediği, model dosyaları elle konulması gereken paketler
MANUAL_ONLY_MODEL_PACKS = {"antelopev2"}


def model_pack_dir(pack: str) -> str:
    return os.path.join(os.path.expanduser("~"), ".insightface", "models", pack)


def model_pack_files_exist(pack: str) -> bool:
    """Paket klasöründe en az bir .onnx model dosyası var mı?"""
    folder = model_pack_dir(pack)
    return os.path.isdir(folder) and any(f.lower().endswith(".onnx") for f in os.listdir(folder))


def build_face_analyzer(log_callback=None):
    """
    InsightFace FaceAnalysis nesnesini oluşturur.

    ÖNEMLİ DONANIM NOTU: CoreMLExecutionProvider, yüz TESPİT modelleriyle (SCRFD/RetinaFace)
    sıklıkla uyumsuzdur — bu modellerin çıktı boyutu görüntüden görüntüye değiştiği
    (dinamik shape) için CoreML'in sabit-şekil beklentisiyle çakışır ve
    "static output shape ... and inferred shape ... have different ranks" hatasıyla
    HER fotoğrafta başarısız olabilir. Bu yüzden:
      - Tespit modeli HER ZAMAN CPUExecutionProvider ile çalıştırılır (Apple Silicon'da
        zaten Accelerate/vecLib sayesinde hızlıdır ve tamamen güvenilirdir).
      - Tanıma (embedding) modeli sabit 112x112 girdi / 512 boyut çıktısına sahip olduğu
        için CoreML ile tam uyumludur; bu yüzden mevcutsa CoreMLExecutionProvider ile
        (Neural Engine hızlandırmalı) ayrıca kurulur. Başarısız olursa sessizce CPU'ya döner.
      - Model paketleri MODEL_PACK_PRIORITY sırasıyla denenir; antelopev2 indirilemezse
        (ağ/lisans kısıtı vb.) otomatik olarak buffalo_l'ye, o da olmazsa buffalo_s'e düşülür.

    Döner: (face_app, (detection_providers, recognition_providers), kullanılan_model_paketi)
    """
    log = log_callback or (lambda *a, **k: None)
    from insightface.app import FaceAnalysis
    from insightface.model_zoo import model_zoo

    try:
        import onnxruntime as ort
        available = ort.get_available_providers()
    except Exception:
        available = []

    detection_providers = ["CPUExecutionProvider"]
    accel_order = ["CoreMLExecutionProvider", "CUDAExecutionProvider"]
    recognition_providers = [p for p in accel_order if p in available] + ["CPUExecutionProvider"]

    last_error = None
    for pack in MODEL_PACK_PRIORITY:
        # Bazı paketler (antelopev2) InsightFace tarafından otomatik indirilemez; model
        # dosyaları elle yerleştirilmediyse boşuna denemeyip doğrudan sıradakine geçiyoruz.
        if pack in MANUAL_ONLY_MODEL_PACKS and not model_pack_files_exist(pack):
            log(f"{pack} yerel olarak bulunamadı (otomatik indirilemez), atlanıyor. "
                f"İstersen model dosyalarını {model_pack_dir(pack)} klasörüne koyabilirsin.", "info")
            continue
        try:
            log(f"Model paketi deneniyor: {pack} ...", "info")
            # 1) Tüm alt modeller önce CPU ile kurulur (tespit modeli için zorunlu, güvenilir taban).
            app = FaceAnalysis(name=pack, providers=detection_providers)
            app.prepare(ctx_id=0, det_size=DETECTION_SIZE)
            try:
                # Tespit duyarlılığını artır: yan açı / zor ışık / uzak çekimlerde daha
                # fazla aday yüz yakalanır (yanlış-pozitifler zaten kalite filtresi ve
                # eşleştirme eşiği/margin katmanlarında elenir, bu yüzden recall'ı
                # yükseltmek güvenlidir).
                if hasattr(app, "det_model") and hasattr(app.det_model, "det_thresh"):
                    app.det_model.det_thresh = DETECTION_CONFIDENCE_THRESHOLD
            except Exception:
                pass
            log(f"Tespit modeli CPU üzerinde hazır (kararlı mod, eşik={DETECTION_CONFIDENCE_THRESHOLD}).", "success")

            # 2) Sadece tanıma (recognition) modelini, sabit şekilli olduğu için CoreML/hızlandırılmış
            #    sağlayıcıyla yeniden kurup mevcut analiz nesnesine enjekte ediyoruz.
            if recognition_providers[0] != "CPUExecutionProvider" and "recognition" in getattr(app, "models", {}):
                try:
                    rec_model_old = app.models["recognition"]
                    rec_model_file = rec_model_old.model_file
                    rec_model_new = model_zoo.get_model(rec_model_file, providers=recognition_providers)
                    rec_model_new.prepare(ctx_id=0)
                    app.models["recognition"] = rec_model_new
                    log(f"Tanıma modeli hızlandırıldı: {recognition_providers[0]} (Neural Engine)", "success")
                except Exception as e:
                    recognition_providers = ["CPUExecutionProvider"]
                    log(f"Tanıma modeli hızlandırılamadı, CPU'da devam ediliyor: {e}", "warn")
            else:
                recognition_providers = ["CPUExecutionProvider"]

            log(f"Model paketi başarıyla yüklendi: {pack}", "success")
            return app, (detection_providers, recognition_providers), pack
        except Exception as e:
            last_error = e
            reason = str(e).strip() or type(e).__name__
            log(f"{pack} yüklenemedi ({reason}); sıradaki pakete geçiliyor...", "warn")

    raise RuntimeError(f"Hiçbir InsightFace model paketi yüklenemedi. Son hata: {last_error}")


def detect_faces_adaptive(face_app, img):
    """
    Yüz tespitini önce kontrast-geliştirilmiş (CLAHE) görüntü üzerinde dener — bu, zor ışık
    koşullarında (gölge/güneş, arkadan aydınlatma, koyu ten tonlarında düşük yerel kontrast)
    tespit başarısını belirgin şekilde artırır. Yine de yüz bulunamazsa, görüntü sırayla
    ADAPTIVE_UPSCALE_STEPS oranlarında büyütülüp yeniden denenir (küçük/uzak yüzler için).
    Landmark/bbox koordinatları her adımda orijinal görüntü ölçeğine geri çevrilir.
    Döner: (faces, kullanılan_görüntü) — kullanılan_görüntü, embedding çıkarımı için de
    aynı (hizalı) görüntünün kullanılmasını sağlar.
    """
    h0, w0 = img.shape[:2]
    if max(h0, w0) > MAX_DETECT_SIDE:
        k = MAX_DETECT_SIDE / float(max(h0, w0))
        img = cv2.resize(img, (max(1, int(w0 * k)), max(1, int(h0 * k))), interpolation=cv2.INTER_AREA)
    enhanced = enhance_image_for_detection(img)

    faces = face_app.get(enhanced)
    if faces:
        return faces, enhanced

    h, w = enhanced.shape[:2]
    for scale in ADAPTIVE_UPSCALE_STEPS:
        if max(h, w) * scale > MAX_UPSCALE_SIDE:
            continue
        upscaled = cv2.resize(enhanced, (int(w * scale), int(h * scale)), interpolation=cv2.INTER_CUBIC)
        faces = face_app.get(upscaled)
        if faces:
            for f in faces:
                f.bbox = f.bbox / scale
                if getattr(f, "kps", None) is not None:
                    f.kps = f.kps / scale
            return faces, enhanced

    return [], enhanced


# ==========================================================================================
# REFERANS HAFIZA YÖNETİCİSİ (Embedding Caching)
# ==========================================================================================

class ReferenceManager:
    """
    Referans klasöründeki oyuncu fotoğraflarını tarar, yüz embedding'lerini çıkarır,
    regex ile isim normalizasyonu yapar ve sonucu ref_memory.pkl içine önbelleğe alır.
    """

    def __init__(self, face_app, model_pack: str, quality_filter: bool, log_callback=None):
        self.face_app = face_app
        self.model_pack = model_pack
        self.quality_filter = quality_filter
        self.log = log_callback or (lambda *a, **k: None)

    def _cache_path(self, ref_folder: str) -> str:
        return os.path.join(ref_folder, REF_CACHE_FILENAME)

    def _fingerprint(self, ref_folder: str) -> str:
        """Referans klasörünün parmak izi (dosya yolu + boyut + değişme zamanı + kalite filtresi).
        Referans fotoğraf eklenir/silinir/değişirse parmak izi değişir ve önbellek otomatik yenilenir."""
        import hashlib as _hashlib
        h = _hashlib.sha1()
        h.update(f"qf={int(bool(self.quality_filter))}".encode())
        for p in sorted(list_image_files(ref_folder)):
            try:
                st = os.stat(p)
            except OSError:
                continue
            rel = os.path.relpath(p, ref_folder)
            h.update(f"|{rel}:{st.st_size}:{int(st.st_mtime)}".encode("utf-8", "replace"))
        return h.hexdigest()

    def load_or_build(self, ref_folder: str, force_rebuild: bool = False) -> dict:
        cache_path = self._cache_path(ref_folder)

        if not force_rebuild and os.path.exists(cache_path):
            try:
                with open(cache_path, "rb") as f:
                    cache_data = pickle.load(f)
                # Farklı model paketiyle üretilmiş bir önbellek uyumsuz olabileceği için kontrol ediyoruz.
                if cache_data.get("model_pack") != self.model_pack:
                    self.log("Önbellek farklı bir model paketiyle oluşturulmuş, yeniden hesaplanıyor...", "warn")
                    return self._build_from_scratch(ref_folder, cache_path)
                # Referans klasörü önbellek oluşturulduktan sonra değiştiyse (foto eklendi/silindi/değişti).
                if cache_data.get("fingerprint") != self._fingerprint(ref_folder):
                    self.log("Referans klasörü değişmiş (ya da önbellek eski sürüm), yeniden hesaplanıyor...",
                             "info")
                    return self._build_from_scratch(ref_folder, cache_path)
                ref_db = cache_data["ref_db"]
                if not ref_db:
                    self.log("Önbellek boş (önceki hatalı çalıştırmadan kalmış olabilir), yeniden hesaplanıyor...",
                              "warn")
                    return self._build_from_scratch(ref_folder, cache_path)
                total_faces = sum(len(v) for v in ref_db.values())
                self.log(f"Referans hafızası diskten yüklendi: {len(ref_db)} oyuncu, "
                          f"{total_faces} yüz vektörü. (ref_memory.pkl)", "info")
                return ref_db
            except Exception as e:
                self.log(f"ref_memory.pkl okunamadı, yeniden oluşturulacak: {e}", "warn")

        return self._build_from_scratch(ref_folder, cache_path)

    def _build_from_scratch(self, ref_folder: str, cache_path: str) -> dict:
        self.log("Referans klasörü taranıyor, yüz vektörleri çıkarılıyor...", "info")
        image_paths = list_image_files(ref_folder)
        ref_db = {}

        for path in image_paths:
            stem = Path(path).stem
            clean_name = clean_reference_name(stem)
            if not clean_name:
                continue

            img = imread_unicode(path)
            if img is None:
                self.log(f"  ⚠ Okunamadı: {os.path.basename(path)}", "warn")
                continue

            try:
                faces, proc_img = detect_faces_adaptive(self.face_app, img)
            except Exception as e:
                self.log(f"  ⚠ Yüz analizi hatası ({os.path.basename(path)}): {e}", "warn")
                continue

            if not faces:
                self.log(f"  ⚠ Yüz bulunamadı: {os.path.basename(path)}", "warn")
                continue

            # Referans fotoğrafında birden fazla yüz varsa en büyük (baskın) yüzü al.
            face = max(faces, key=lambda f: (f.bbox[2] - f.bbox[0]) * (f.bbox[3] - f.bbox[1]))

            if self.quality_filter:
                ok, reason = face_quality_check(face, proc_img)
                if not ok:
                    self.log(f"  ⚠ Kalite filtresi reddetti ({reason}): {os.path.basename(path)}", "warn")
                    continue

            emb = face.normed_embedding
            if emb is None:
                continue

            ref_db.setdefault(clean_name, []).append(emb.astype(np.float32))
            self.log(f"  ✓ {clean_name}  <—  {os.path.basename(path)}", "success")

        self._log_reference_consistency(ref_db)

        try:
            with open(cache_path, "wb") as f:
                pickle.dump({"model_pack": self.model_pack, "ref_db": ref_db,
                             "fingerprint": self._fingerprint(ref_folder)}, f)
            self.log(f"Referans hafızası kaydedildi: {cache_path}", "info")
        except Exception as e:
            self.log(f"ref_memory.pkl kaydedilemedi: {e}", "warn")

        total_faces = sum(len(v) for v in ref_db.values())
        self.log(f"Toplam {len(ref_db)} oyuncu, {total_faces} referans yüz vektörü hazır.", "info")
        return ref_db

    def _log_reference_consistency(self, ref_db: dict):
        """
        Aynı oyuncu adı altında toplanan birden fazla referans fotoğrafının (ör. onur.jpg,
        onur_2.jpg) gerçekten birbiriyle tutarlı (aynı kişi) olup olmadığını denetler.
        Yanlış etiketlenmiş/karışmış bir fotoğraf varsa uyarı verir; herkes için kaç farklı
        açı toplandığını özetler — çoklu açı ekledikçe bunu takip edebilesin diye.
        """
        for name, embs in ref_db.items():
            if len(embs) == 1:
                self.log(f"  ℹ {name}: 1 referans (tek açı) — ikinci bir açı eklemek "
                          f"(ör. {name.lower()}_2.jpg) doğruluğu artırır.", "info")
                continue

            per_photo_avg = []
            for i in range(len(embs)):
                others = [embs[j] for j in range(len(embs)) if j != i]
                avg_sim = float(np.mean([np.dot(embs[i], o) for o in others]))
                per_photo_avg.append(avg_sim)
                if avg_sim < 0.15:
                    self.log(
                        f"  ⚠ '{name}' için {i + 1}. referans fotoğraf diğerlerinden belirgin "
                        f"farklı (ort. benzerlik={avg_sim:.2f}) — yanlış etiketlenmiş ya da "
                        f"başka bir kişi olabilir, kontrol etmeni öneririm.", "warn")

            overall = float(np.mean(per_photo_avg))
            self.log(f"  ℹ {name}: {len(embs)} farklı açı kaydedildi "
                      f"(iç-tutarlılık={overall:.2f})", "info")


# ==========================================================================================
# İŞÇİ (WORKER) THREAD — Ağır işlemler GUI'yi dondurmasın diye ayrı iş parçacığında çalışır
# ==========================================================================================

class ExtractionWorker(QThread):
    log_signal = pyqtSignal(str, str)                   # (mesaj, seviye)
    progress_signal = pyqtSignal(int, int, int, int)     # (islenen, toplam, basarili, basarisiz)
    thumbnail_signal = pyqtSignal(bytes, str, str)       # (jpg_bayt, dosya_adi, sonuc_etiketi)
    finished_signal = pyqtSignal(dict)                   # özet istatistik

    def __init__(self, ref_folder: str, media_folder: str, threshold: float, margin: float,
                 quality_filter: bool, force_rebuild_cache: bool,
                 goalkeeper_names=None, output_base_dir: str = "", parent=None):
        super().__init__(parent)
        self.ref_folder = ref_folder
        self.media_folder = media_folder
        self.threshold = threshold
        self.margin = margin
        self.quality_filter = quality_filter
        self.force_rebuild_cache = force_rebuild_cache
        self.goalkeeper_names = goalkeeper_names
        self.output_base_dir = output_base_dir
        self._is_cancelled = False

    def cancel(self):
        self._is_cancelled = True

    def run(self):
        stats = {
            "toplam": 0, "islenen": 0, "basarili": 0, "basarisiz": 0,
            "kaleci": 0, "karisik": 0, "output_folder": "", "per_player": {}, "csv_path": "",
        }
        csv_rows = []  # REPORT_HEADER sırasıyla: dosya, sonuç, oyuncu, skor, not, kalite, adaylar, konum
        try:
            self.log_signal.emit("Yüz tanıma motoru başlatılıyor (antelopev2 → buffalo_l otomatik düşüş)...", "info")
            face_app, (det_providers, rec_providers), model_pack = build_face_analyzer(
                log_callback=lambda m, lvl="info": self.log_signal.emit(m, lvl))
            self.log_signal.emit(
                f"Motor hazır. Model paketi: {model_pack} | Tespit: {det_providers[0]} | "
                f"Tanıma: {rec_providers[0]}", "info")

            ref_manager = ReferenceManager(
                face_app, model_pack, self.quality_filter,
                log_callback=lambda m, lvl="info": self.log_signal.emit(m, lvl))
            ref_db = ref_manager.load_or_build(self.ref_folder, force_rebuild=self.force_rebuild_cache)

            if not ref_db:
                self.log_signal.emit("Referans veritabanı boş! İşlem durduruldu.", "error")
                self.finished_signal.emit(stats)
                return

            output_root = get_today_output_folder(self.output_base_dir)
            os.makedirs(output_root, exist_ok=True)
            mixed_dir = os.path.join(output_root, MIXED_FOLDER_NAME)
            goalkeeper_dir = os.path.join(output_root, GOALKEEPER_FOLDER_NAME)
            os.makedirs(mixed_dir, exist_ok=True)
            os.makedirs(goalkeeper_dir, exist_ok=True)
            stats["output_folder"] = output_root

            self.log_signal.emit(f"Çıktı klasörü: {output_root}", "info")

            media_paths = list_image_files(self.media_folder)
            stats["toplam"] = len(media_paths)
            self.log_signal.emit(f"Ayıklanacak medya klasöründe {len(media_paths)} fotoğraf bulundu.", "info")

            goalkeeper_pool_clean = {strip_accents_upper(g) for g in (self.goalkeeper_names or GOALKEEPER_POOL)}

            for i, path in enumerate(media_paths, start=1):
                if self._is_cancelled:
                    self.log_signal.emit("İşlem kullanıcı tarafından durduruldu.", "warn")
                    break

                filename = os.path.basename(path)
                _remember_photo(path, i, stats["toplam"])
                if i % 25 == 0:
                    gc.collect()  # uzun koşularda bellek birikimini temizle
                try:
                    img = imread_unicode(path)
                    if img is None:
                        raise ValueError("Görüntü okunamadı / bozuk dosya")

                    faces, proc_img = detect_faces_adaptive(face_app, img)
                    finfo = {}
                    matches, reject_reason, reject_score, bg_skipped = identify_all_faces(
                        faces, proc_img, ref_db, self.threshold, self.margin, self.quality_filter, finfo)
                    bg_note = f"arka plan/odak dışı {bg_skipped} yüz atlandı" if bg_skipped else "-"

                    if not matches:
                        dest = self._copy_to(path, mixed_dir, filename)
                        stats["karisik"] += 1
                        stats["basarisiz"] += 1
                        stats["per_player"][MIXED_FOLDER_NAME] = stats["per_player"].get(MIXED_FOLDER_NAME, 0) + 1
                        cand_text = "|".join(f"{n}:{sc:.3f}" for n, sc in finfo.get("candidates", []))
                        csv_rows.append((filename, "Karışık", "-", f"{reject_score:.3f}",
                                         reject_reason if not bg_skipped else f"{reject_reason}; {bg_note}",
                                         "", cand_text, os.path.relpath(dest, output_root)))
                        self.log_signal.emit(f"[KARIŞIK] {reject_reason}: {filename}", "warn")
                        self.thumbnail_signal.emit(
                            make_thumbnail_bytes(img), filename, f"KARIŞIK — {reject_reason}")
                    else:
                        # Karedeki tanınan HER oyuncu fotoğrafı kendi klasörüne alır (skora göre sıralı).
                        keeper_copied = False
                        labels = []
                        for matched_name, score in sorted(matches.items(), key=lambda kv: kv[1], reverse=True):
                            if strip_accents_upper(matched_name) in goalkeeper_pool_clean:
                                if not keeper_copied:  # iki kaleci aynı karedeyse KALECILER'e tek kopya
                                    keeper_dest = self._copy_to(path, goalkeeper_dir, filename)
                                    keeper_copied = True
                                    stats["kaleci"] += 1
                                    stats["per_player"][GOALKEEPER_FOLDER_NAME] = \
                                        stats["per_player"].get(GOALKEEPER_FOLDER_NAME, 0) + 1
                                csv_rows.append((filename, "Kaleci Havuzu", matched_name, f"{score:.3f}", bg_note,
                                                 f"{finfo.get('quality', {}).get(matched_name, 0):.1f}", "",
                                                 os.path.relpath(keeper_dest, output_root)))
                                self.log_signal.emit(
                                    f"[KALECİLER] {matched_name} (skor={score:.2f}): {filename}", "success")
                                labels.append(f"KALECİLER — {matched_name} ({score:.2f})")
                            else:
                                player_dir = os.path.join(output_root, matched_name)
                                os.makedirs(player_dir, exist_ok=True)
                                dest = self._copy_to(path, player_dir, filename)
                                stats["per_player"][matched_name] = stats["per_player"].get(matched_name, 0) + 1
                                csv_rows.append((filename, "Eşleşti", matched_name, f"{score:.3f}", bg_note,
                                                 f"{finfo.get('quality', {}).get(matched_name, 0):.1f}", "",
                                                 os.path.relpath(dest, output_root)))
                                self.log_signal.emit(
                                    f"[{matched_name}] eşleşti (skor={score:.2f}): {filename}", "success")
                                labels.append(f"{matched_name} ({score:.2f})")
                        stats["basarili"] += 1  # fotoğraf sayısı; oyuncu başına kopya sayısı per_player'da
                        self.thumbnail_signal.emit(make_thumbnail_bytes(img), filename, " · ".join(labels))

                except Exception as e:
                    try:
                        self._copy_to(path, mixed_dir, filename)
                    except Exception:
                        pass
                    stats["karisik"] += 1
                    stats["basarisiz"] += 1
                    stats["per_player"][MIXED_FOLDER_NAME] = stats["per_player"].get(MIXED_FOLDER_NAME, 0) + 1
                    csv_rows.append((filename, "Karışık", "-", "0.000", f"hata: {e}", "", "", ""))
                    self.log_signal.emit(f"[HATA→KARIŞIK] {filename}: {e}", "error")

                stats["islenen"] = i
                self.progress_signal.emit(i, stats["toplam"], stats["basarili"], stats["basarisiz"])

            self.log_signal.emit("İşlem tamamlandı.", "info")

            if csv_rows:
                try:
                    csv_path = os.path.join(output_root, "Rapor.csv")
                    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
                        writer = csv.writer(f, delimiter=";")
                        writer.writerow(REPORT_HEADER)
                        writer.writerows(csv_rows)
                    stats["csv_path"] = csv_path
                    self.log_signal.emit(f"Denetim raporu kaydedildi: {csv_path}", "info")
                except Exception as e:
                    self.log_signal.emit(f"CSV raporu kaydedilemedi: {e}", "warn")

        except Exception as e:
            tb = traceback.format_exc()
            self.log_signal.emit(f"Beklenmeyen kritik hata: {e}\n{tb}", "error")

        self.finished_signal.emit(stats)

    @staticmethod
    def _copy_to(src_path: str, dest_dir: str, filename: str) -> str:
        dest_path = unique_destination_path(dest_dir, filename)
        shutil.copy2(src_path, dest_path)  # metadata korunarak kopyalama
        return dest_path



