def get_upcoming_fixtures() -> list:
    """MANUAL_FIXTURES içinden bugünden itibaren gelecek maçları, tarihe göre sıralı döndürür.
    Her öğe: {"date", "time", "opponent", "home"} — 'home' Kocaelispor'un iç sahada olup olmadığı."""
    today = date.today()
    upcoming = [f for f in MANUAL_FIXTURES if f["date"] >= today]
    upcoming.sort(key=lambda f: f["date"])

    result = []
    for f in upcoming:
        is_home = (f["home"] == KULUP_ADI)
        opponent = f["away"] if is_home else f["home"]
        result.append({"date": f["date"], "time": f["time"], "opponent": opponent, "home": is_home,
                        "stadium": f.get("stadium", "")})
    return result


def get_next_fixture():
    upcoming = get_upcoming_fixtures()
    return upcoming[0] if upcoming else None


def get_birthday_list() -> list:
    """MANUAL_BIRTHDAYS içinden herkesin bir sonraki doğum gününe kalan süreyi hesaplar,
    en yakından en uzağa sıralı döndürür. Her öğe: {"name", "date", "days_left"}."""
    today = date.today()
    result = []
    for b in MANUAL_BIRTHDAYS:
        dob = b["date"]
        try:
            next_bday = dob.replace(year=today.year)
        except ValueError:
            next_bday = dob.replace(year=today.year, day=28)  # 29 Şubat düzeltmesi
        if next_bday < today:
            try:
                next_bday = next_bday.replace(year=today.year + 1)
            except ValueError:
                next_bday = next_bday.replace(year=today.year + 1, day=28)
        days_left = (next_bday - today).days
        result.append({"name": b["name"], "date": dob, "days_left": days_left})
    result.sort(key=lambda x: x["days_left"])
    return result


