def make_pixmap(name: str, color: str, size: int = 20, stroke: float = 1.75):
    """SVG ikonu yüksek çözünürlüklü (2x) bir QPixmap'e çizer. QtSvg yoksa None döner."""
    if QSvgRenderer is None or name not in ICON_SVG:
        return None
    body, filled = ICON_SVG[name]
    if filled:
        attrs = f'fill="{color}" stroke="none"'
    else:
        attrs = (f'fill="none" stroke="{color}" stroke-width="{stroke}" '
                 f'stroke-linecap="round" stroke-linejoin="round"')
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
           f'viewBox="0 0 24 24" {attrs}>{body}</svg>')
    renderer = QSvgRenderer(QByteArray(svg.encode("utf-8")))
    scale = 2
    pixmap = QPixmap(size * scale, size * scale)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    renderer.render(painter, QRectF(0, 0, size * scale, size * scale))
    painter.end()
    pixmap.setDevicePixelRatio(scale)
    return pixmap


def make_icon(name: str, color: str, size: int = 20) -> QIcon:
    pixmap = make_pixmap(name, color, size)
    return QIcon(pixmap) if pixmap is not None else QIcon()


def make_state_icon(name: str, off_color: str, on_color: str, size: int = 22) -> QIcon:
    """Seçili değilken bir renk, seçiliyken başka renk gösteren ikon (menü butonları için)."""
    icon = QIcon()
    off = make_pixmap(name, off_color, size)
    on = make_pixmap(name, on_color, size)
    if off is None or on is None:
        return icon
    icon.addPixmap(off, QIcon.Mode.Normal, QIcon.State.Off)
    icon.addPixmap(on, QIcon.Mode.Normal, QIcon.State.On)
    return icon


# ==========================================================================================
# OTOMATİK GÜNCELLEME
# ==========================================================================================
# GitHub'daki main dalından (main.py'deki APP_VERSION) en son sürümü kontrol eder. Yeni sürüm varsa
# main.py + ks_data.py'yi indirir: .app'te veri klasöründeki "kod" katmanına (launcher.py oradan
# yükler, paket yeniden derlenmez); python3 main.py'de dosyaların üzerine yazar. Sonra yeniden başlatır.

def _version_tuple(v: str) -> tuple:
    v = v.strip().lstrip("vV")
    parts = []
    for p in v.split("."):
        digits = "".join(ch for ch in p if ch.isdigit())
        parts.append(int(digits) if digits else 0)
    return tuple(parts)


def is_frozen() -> bool:
    return ks_data.is_frozen()


def current_app_bundle_path():
    """Paketlenmiş (.app) sürümde çalışırken .app klasörünün tam yolunu döndürür."""
    if not is_frozen():
        return None
    p = Path(sys.executable).resolve()
    for parent in [p] + list(p.parents):
        if parent.suffix == ".app":
            return parent
    return None


def _update_meta(text: str):
    """main.py metninden (sürüm, gereken paket sürümü, notlar) okur."""
    ver = re.search(r'^APP_VERSION\s*=\s*"([^"]+)"', text, re.M)
    req = re.search(r'^REQUIRES_BUNDLE\s*=\s*(\d+)', text, re.M)
    notes = ""
    m = re.search(r'^UPDATE_NOTES\s*=\s*(.+)$', text, re.M)
    if m:
        try:
            notes = str(ast.literal_eval(m.group(1).strip()))
        except Exception:
            notes = ""
    return (ver.group(1) if ver else ""), (int(req.group(1)) if req else 1), notes


def overlay_dir() -> Path:
    """Paketlenmiş uygulamada güncellenen kodun indirildiği klasör (launcher.py buradan yükler)."""
    return ks_data.user_data_dir() / "kod"


RUNNING_BUNDLE_API = int(os.environ.get("MEDIASTAFF_BUNDLE_API", "0") or 0)   # launcher.py ayarlar


def _fetch_repo_file(name: str, timeout: int, head_bytes=None) -> bytes:
    """Depodaki dosyayı GitHub API'sinden (önbelleksiz, anında güncel) okur; olmazsa raw adresine düşer.
    head_bytes verilirse yalnızca baştan o kadar bayt okunur."""
    attempts = [
        (f"https://api.github.com/repos/{UPDATE_REPO}/contents/{name}?ref=main",
         {"Accept": "application/vnd.github.raw"}),
        (UPDATE_RAW_BASE + name + "?t=" + str(int(time.time())), {}),
    ]
    last = None
    for url, extra in attempts:
        try:
            request = urllib.request.Request(url, headers={"User-Agent": "MediaStaffKS-Updater", **extra})
            with urllib.request.urlopen(request, timeout=timeout, context=_update_ssl_context()) as response:
                return response.read(head_bytes) if head_bytes else response.read()
        except Exception as e:  # noqa: BLE001
            last = e
    raise last


class UpdateCheckWorker(QThread):
    found = pyqtSignal(dict)
    none_found = pyqtSignal()
    failed = pyqtSignal(str)

    def run(self):
        _log_update_event(f"kontrol başladı (yerel sürüm {APP_VERSION}, frozen={is_frozen()})")
        try:
            # Sürüm bilgisi dosyanın başında; tamamını indirmeye gerek yok
            head = _fetch_repo_file("main.py", 15, head_bytes=24576).decode("utf-8", "replace")
        except Exception as e:
            _log_update_event(f"kontrol HATASI: {e!r}")
            self.failed.emit(str(e))
            return

        remote_ver, req_bundle, notes = _update_meta(head)
        _log_update_event(f"kontrol bitti, uzak sürüm: {remote_ver!r}")
        if not remote_ver or _version_tuple(remote_ver) <= _version_tuple(APP_VERSION):
            self.none_found.emit()
            return
        self.found.emit({"version": remote_ver, "notes": notes, "requires_bundle": req_bundle})


class UpdateDownloadWorker(QThread):
    progress = pyqtSignal(str)
    done = pyqtSignal(str)       # indirilen dosyaların geçici klasörü
    failed = pyqtSignal(str)

    def run(self):
        try:
            tmp_dir = Path(tempfile.mkdtemp(prefix="mediastaffks_update_"))
            for name in UPDATE_FILES:
                self.progress.emit(f"İndiriliyor: {name}")
                payload = _fetch_repo_file(name, 60)
                text = payload.decode("utf-8")
                compile(text, name, "exec")          # bozuk/yarım indirmeyi uygulamadan yakala
                if name == "main.py" and not _update_meta(text)[0]:
                    raise RuntimeError("main.py sürüm bilgisi okunamadı")
                (tmp_dir / name).write_bytes(payload)
            self.done.emit(str(tmp_dir))
        except Exception as e:
            self.failed.emit(str(e))


def _restart_app(parent_window):
    """Güncelleme sonrası uygulamayı yeniden başlatır."""
    app_bundle = current_app_bundle_path()
    if app_bundle is not None:
        script_path = Path(tempfile.gettempdir()) / "mediastaffks_restart.sh"
        script_path.write_text(f"""#!/bin/bash
sleep 1
open -n "{app_bundle}"
""")
        os.chmod(script_path, 0o755)
        subprocess.Popen(["/bin/bash", str(script_path)], start_new_session=True,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        QApplication.quit()
        os._exit(0)
    python = sys.executable
    os.execv(python, [python] + ([str(Path(__file__).resolve())] if not is_frozen() else []))


def _install_update(tmp_dir: str, parent_window) -> bool:
    """İndirilen dosyaları yerine koyup yeniden başlatır.
    .app'te: veri klasöründeki 'kod' katmanına (paket değişmez); python3 main.py'de: dosyaların üzerine."""
    try:
        dest = overlay_dir() if is_frozen() else Path(__file__).resolve().parent
        dest.mkdir(parents=True, exist_ok=True)
        staged = []
        for name in UPDATE_FILES:
            target = dest / name
            if not is_frozen() and target.is_file():
                shutil.copyfile(target, target.with_suffix(".py.bak"))
            new_path = target.with_suffix(".py.new")
            shutil.copyfile(Path(tmp_dir) / name, new_path)
            staged.append((new_path, target))
        for new_path, target in staged:
            os.replace(new_path, target)
    except Exception as e:
        QMessageBox.warning(parent_window, "Güncelleme", f"Dosyalar güncellenemedi:\n{e}")
        return False
    _log_update_event("güncelleme uygulandı, yeniden başlatılıyor")
    QMessageBox.information(parent_window, "Güncellendi", "Güncelleme indirildi. Uygulama yeniden başlatılıyor…")
    _restart_app(parent_window)
    return True


def start_update_check(parent_window, manual: bool = False):
    """Arka planda GitHub'daki en son sürümü kontrol eder; bulursa kullanıcıya sorar.
    manual=True: kullanıcı kendisi istediyse 'güncel' / hata durumlarını da bildirir."""
    worker = UpdateCheckWorker(parent_window)
    parent_window._update_worker = worker  # GC'ye karşı referans

    def on_found(info: dict):
        ver = info["version"]
        if is_frozen() and info["requires_bundle"] > RUNNING_BUNDLE_API:
            QMessageBox.information(
                parent_window, "Yeni sürüm var",
                f"MediaStaffKS {ver} çıktı, ama bu sürüm uygulamanın yeniden kurulmasını gerektiriyor.\n"
                "Proje klasöründe şunu çalıştır:  bash build_mac.sh")
            return
        notes = info["notes"].strip()
        extra = f"\n\n{notes}" if notes else ""
        box = QMessageBox(parent_window)
        box.setIcon(QMessageBox.Icon.Information)
        box.setWindowTitle("Yeni sürüm var")
        box.setText(f"MediaStaffKS {ver} kullanılabilir (şu an {APP_VERSION}).\n"
                    f"Şimdi güncellensin mi?{extra}")
        box.setStandardButtons(QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        box.setDefaultButton(QMessageBox.StandardButton.Yes)
        if box.exec() != QMessageBox.StandardButton.Yes:
            return

        dl = UpdateDownloadWorker(parent_window)
        parent_window._update_download_worker = dl
        dl.done.connect(lambda path: _install_update(path, parent_window))
        dl.failed.connect(lambda err: QMessageBox.warning(parent_window, "Güncelleme", f"İndirme başarısız:\n{err}"))
        dl.start()

    def on_none():
        if manual:
            QMessageBox.information(parent_window, "Güncelleme", f"MediaStaffKS güncel (sürüm {APP_VERSION}).")

    def on_failed(err: str):
        print(f"[güncelleme kontrolü] atlanıyor: {err}", file=sys.stderr)
        if manual:
            QMessageBox.warning(parent_window, "Güncelleme", f"Güncelleme kontrol edilemedi:\n{err}")

    worker.found.connect(on_found)
    worker.none_found.connect(on_none)
    worker.failed.connect(on_failed)
    worker.start()


def repolish(widget: QWidget):
    """Dinamik özellik (property) değişince QSS'in yeniden uygulanmasını sağlar."""
    widget.style().unpolish(widget)
    widget.style().polish(widget)
    widget.update()


def clear_layout(layout):
    while layout.count():
        item = layout.takeAt(0)
        child = item.widget()
        if child is not None:
            child.deleteLater()
        elif item.layout() is not None:
            clear_layout(item.layout())


def load_local_fonts():
    """main.py'nin yanındaki 'fonts' klasöründeki yazı tiplerini (varsa) yükler."""
    for base in ks_data.asset_dirs():
        fonts_dir = base / "fonts"
        if not fonts_dir.is_dir():
            continue
        for pattern in ("*.ttf", "*.otf"):
            for font_file in fonts_dir.glob(pattern):
                QFontDatabase.addApplicationFont(str(font_file))


# Kocaelispor kulüp amblemi: önce main.py'nin yanındaki dosya (varsa, kolay değiştirmek
# için), yoksa aşağıya gömülü PNG verisi kullanılır — ayrı dosya kaybolsa/taşınsa bile
# amblem her zaman görünür.
CLUB_LOGO_FILENAMES = ("kocaelispor_logo.png", "logo.png")
CLUB_LOGO_BASE64 = (
    ""
)
_club_logo_pixmap_cache: dict = {}


def club_logo_source_path():
    return ks_data.find_asset(*CLUB_LOGO_FILENAMES)


def _scaled_hidpi(raw: "QPixmap", size: int) -> "QPixmap":
    """Logoyu ekranın gerçek piksel yoğunluğunda (Retina'da 2x) ölçekler; mantıksal boyut `size` kalır."""
    try:
        dpr = max(1.0, float(QApplication.primaryScreen().devicePixelRatio()))
    except Exception:
        dpr = 2.0
    px = max(size, int(round(size * dpr)))
    scaled = raw.scaled(px, px, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
    scaled.setDevicePixelRatio(px / size)
    return scaled


def get_club_logo_pixmap(size: int):
    """Kulüp amblemini verilen piksel boyuta sığacak şekilde (en-boy korunarak) döndürür."""
    if size in _club_logo_pixmap_cache:
        return _club_logo_pixmap_cache[size]
    raw = QPixmap()
    path = club_logo_source_path()
    loaded = False
    if path is not None:
        loaded = raw.load(str(path))
    if not loaded:
        try:
            raw.loadFromData(base64.b64decode(CLUB_LOGO_BASE64))
            loaded = not raw.isNull()
        except Exception:
            loaded = False
    if not loaded or raw.isNull():
        _club_logo_pixmap_cache[size] = None
        return None
    scaled = _scaled_hidpi(raw, size)
    _club_logo_pixmap_cache[size] = scaled
    return scaled


# --- Rakip takım görselleri (PNG) ---------------------------------------------------------
# main.py ile TAM OLARAK AYNI klasörde "takim_logolari" (ya da "logolar"/"logos") adında bir
# klasör oluşturup, her takım için düz bir PNG (tercihen şeffaf arka planlı) koyarsan o takımın
# amblemi otomatik kullanılır. Dosya adı, takım adının küçük harfe çevrilip Türkçe karakterleri
# sadeleştirilmiş hâlidir, örn:
#   "Fenerbahçe" -> fenerbahce.png
#   "Çorum FK"   -> corum_fk.png
# Bir takım için dosya yoksa, mevcut üç harfli rozet (TEAM_ABBR) otomatik olarak kullanılmaya
# devam eder — hiçbir şey kırılmaz.
TEAM_LOGOS_DIRNAMES = ("takim_logolari", "logolar", "logos")
_team_logo_pixmap_cache: dict = {}

_TR_SLUG_MAP = str.maketrans({
    "ı": "i", "İ": "i", "ş": "s", "Ş": "s", "ğ": "g", "Ğ": "g",
    "ü": "u", "Ü": "u", "ö": "o", "Ö": "o", "ç": "c", "Ç": "c",
})


def team_logo_slug(name: str) -> str:
    slug = name.strip().lower().translate(_TR_SLUG_MAP)
    slug = "".join(ch if ch.isalnum() else "_" for ch in slug)
    while "__" in slug:
        slug = slug.replace("__", "_")
    return slug.strip("_")


def team_logo_source_path(name: str):
    app_dirs = ks_data.asset_dirs()      # kullanıcı klasörü önce, sonra paketin içi
    slug = team_logo_slug(name)

    # 1) Tam eşleşme: "<slug>.png" / "<slug>.PNG"
    for app_dir in app_dirs:
        for dirname in TEAM_LOGOS_DIRNAMES:
            for ext in ("png", "PNG"):
                candidate = app_dir / dirname / f"{slug}.{ext}"
                if candidate.is_file():
                    return candidate

    # 2) Esnek eşleşme: klasördeki her PNG'nin adını da aynı şekilde sadeleştirip
    #    takım slug'ıyla birbirini içerip içermediğine bakar. Böylece "corum.png"
    #    "Çorum FK" (corum_fk) ile, "fenerbahçe.png" "Fenerbahçe" (fenerbahce) ile eşleşir.
    best = None
    best_len = -1
    for folder in [d / dn for d in app_dirs for dn in TEAM_LOGOS_DIRNAMES]:
        if not folder.is_dir():
            continue
        try:
            entries = list(folder.iterdir())
        except OSError:
            continue
        for entry in entries:
            if not entry.is_file() or entry.suffix.lower() != ".png":
                continue
            file_slug = team_logo_slug(entry.stem)
            if not file_slug:
                continue
            if file_slug == slug or file_slug in slug or slug in file_slug:
                if len(file_slug) > best_len:
                    best = entry
                    best_len = len(file_slug)
    return best


def get_team_logo_pixmap(name: str, size: int):
    """Varsa takim_logolari/<takim>.png dosyasını, yoksa (Kocaelispor için) kulüp amblemini,
    o da yoksa None döndürür — çağıran taraf None durumunda mevcut harf rozetine düşer."""
    if name == KULUP_ADI:
        return get_club_logo_pixmap(size)
    cache_key = (name, size)
    if cache_key in _team_logo_pixmap_cache:
        return _team_logo_pixmap_cache[cache_key]
    path = team_logo_source_path(name)
    pixmap = None
    if path is not None:
        raw = QPixmap()
        if raw.load(str(path)) and not raw.isNull():
            pixmap = _scaled_hidpi(raw, size)
    _team_logo_pixmap_cache[cache_key] = pixmap
    return pixmap


# Not: logo EKLEME/KALDIRMA artık burada değil — ayrı "Admin Paneli" (admin.py) uygulamasında.
# main.py yalnızca yukarıdaki team_logo_source_path / get_team_logo_pixmap ile OKUR.


TEAM_ABBR = {
    "Kocaelispor": "KOC", "Beşiktaş": "BJK", "Göztepe": "GÖZ", "Alanyaspor": "ALA",
    "Rizespor": "RİZ", "Eyüpspor": "EYÜ", "Fenerbahçe": "FB", "Çorum FK": "ÇOR",
    "Erzurumspor": "ERZ", "Trabzonspor": "TS", "Gençlerbirliği": "GB", "Galatasaray": "GS",
}


def team_abbr(name: str) -> str:
    if name in TEAM_ABBR:
        return TEAM_ABBR[name]
    return turkish_upper(name.replace(" ", ""))[:3]


def initials(name: str) -> str:
    parts = [p for p in name.split() if p]
    if not parts:
        return "?"
    if len(parts) == 1:
        return turkish_upper(parts[0][:2])
    return turkish_upper(parts[0][0] + parts[-1][0])


# ==========================================================================================
#  OYUNCU FOTOĞRAFLARI
# ==========================================================================================
# main.py ile AYNI klasöre bu adlardan biriyle bir klasör açıp (ör. "oyuncu_fotograflari")
# içine her oyuncu için bir fotoğraf (png/jpg) koyarsan, kadro ve sağlık dosyası ekranlarında
# harf rozeti yerine otomatik olarak bu fotoğraf kullanılır. Dosya adı tam oyuncu adı olabilir
# ("Serhat Öztaşdelen.png") ya da sadece ad/soyad olabilir ("serhat.jpg") — eşleştirme esnektir.
# Bir oyuncunun fotoğrafı yoksa o oyuncu eskisi gibi harf rozetiyle gösterilir.
PLAYER_PHOTOS_DIRNAMES = (
    "oyuncu_fotograflari", "oyuncularimiz", "oyuncular", "oyuncu_resimleri",
    "player_photos", "fotograflar",
)
_PLAYER_PHOTO_EXTS = ("png", "PNG", "jpg", "JPG", "jpeg", "JPEG", "webp", "WEBP")
_player_photo_cache: dict = {}


def _name_slug(text: str) -> str:
    return team_logo_slug(text)


def pick_photo_entry(full_slug: str, entries: list):
    """entries: [(dosya_slug, öğe)]. Yalnız TAM kelime eşleşmesi: "onur" dosyası "Onurcan Piri"ye düşmez.
    Öncelik: tam ad > aynı kelime kümesi > dosya adı ismin kelimelerinden biri/birkaçı > dosyada fazladan kelime var."""
    nset = {t for t in full_slug.split("_") if t}
    best, best_score = None, 0
    for slug, item in entries:
        if not slug:
            continue
        if slug == full_slug:
            score = 1000
        else:
            fset = {t for t in slug.split("_") if t}
            if not fset:
                continue
            if fset == nset:
                score = 900
            elif fset <= nset:
                score = 500 + len(fset)
            elif nset and nset <= fset:
                score = 600 - len(fset)
            else:
                continue
        if score > best_score:
            best, best_score = item, score
    return best


def player_photo_source_path(name: str):
    full_slug = _name_slug(name)

    candidate_dirs = []
    for app_dir in ks_data.asset_dirs():     # kullanıcı klasörü önce, sonra paketin içi
        for dirname in PLAYER_PHOTOS_DIRNAMES:
            d = app_dir / dirname
            if d.is_dir() and d not in candidate_dirs:
                candidate_dirs.append(d)
        # Klasör adı yukarıdaki listede yoksa bile, içinde "oyuncu"/"player" geçen
        # herhangi bir alt klasörü de dene (ör. "Oyuncularımız 26-27").
        try:
            for entry in app_dir.iterdir():
                if entry.is_dir() and entry not in candidate_dirs:
                    if "oyuncu" in _name_slug(entry.name) or "player" in _name_slug(entry.name):
                        candidate_dirs.append(entry)
        except OSError:
            pass

    # 1) Tam eşleşme
    for folder in candidate_dirs:
        for ext in _PLAYER_PHOTO_EXTS:
            candidate = folder / f"{full_slug}.{ext}"
            if candidate.is_file():
                return candidate

    # 2) Esnek eşleşme (yalnız tam kelime): "onur.png" Onur Öztonga'ya gider, Onurcan Piri'ye değil
    entries = []
    for folder in candidate_dirs:
        try:
            files = list(folder.iterdir())
        except OSError:
            continue
        for entry in files:
            if entry.is_file() and entry.suffix.lower().lstrip(".") in ("png", "jpg", "jpeg", "webp"):
                entries.append((_name_slug(entry.stem), entry))
    return pick_photo_entry(full_slug, entries)


def _circular_pixmap(raw: QPixmap, size: int) -> "QPixmap | None":
    """Yuvarlak avatar: Retina'da keskin (cihaz piksel oranına göre çizer), portre fotoğrafta yüzü üstten kırpar."""
    if raw.isNull():
        return None
    try:
        dpr = max(1.0, float(QApplication.primaryScreen().devicePixelRatio()))
    except Exception:
        dpr = 2.0
    px = max(size, int(round(size * dpr)))
    w, h = raw.width(), raw.height()
    side = min(w, h)
    if h > w:                      # portre/boy fotoğrafı: baş üstte — genişliğin %86'sı kadar kare, üstten
        side = int(w * 0.86)
        x, y = (w - side) // 2, int(h * 0.01)
    else:
        x, y = (w - side) // 2, (h - side) // 2
    cropped = raw.copy(x, y, side, side).scaled(
        px, px, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
    result = QPixmap(px, px)
    result.fill(Qt.GlobalColor.transparent)
    painter = QPainter(result)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
    path = QPainterPath()
    path.addEllipse(QRectF(0, 0, px, px))
    painter.setClipPath(path)
    painter.drawPixmap(0, 0, cropped)
    painter.end()
    result.setDevicePixelRatio(px / size)
    return result


def get_player_photo_pixmap(name: str, size: int):
    """Varsa oyuncunun fotoğrafını daire şeklinde kırpıp döndürür; yoksa None
    (çağıran taraf None durumunda mevcut harf rozetine düşer)."""
    cache_key = (name, size)
    if cache_key in _player_photo_cache:
        return _player_photo_cache[cache_key]
    pixmap = None
    path = player_photo_source_path(name)
    if path is not None:
        raw = QPixmap()
        if raw.load(str(path)) and not raw.isNull():
            pixmap = _circular_pixmap(raw, size)
    _player_photo_cache[cache_key] = pixmap
    return pixmap


# Not: fotoğraf EKLEME/KALDIRMA artık burada değil — ayrı "Admin Paneli" (admin.py) uygulamasında.
# main.py yalnızca yukarıdaki player_photo_source_path / get_player_photo_pixmap ile OKUR.


def make_avatar_label(name: str, size: int, object_name: str) -> QLabel:
    """Oyuncu fotoğrafı varsa daire şeklinde onu, yoksa harf rozetini gösteren QLabel."""
    label = QLabel()
    label.setObjectName(object_name)
    label.setFixedSize(size, size)
    label.setAlignment(Qt.AlignmentFlag.AlignCenter)
    pixmap = get_player_photo_pixmap(name, size)
    if pixmap is not None:
        label.setPixmap(pixmap)
    else:
        label.setText(initials(name))
    return label


DAYS_TR = ["Pazartesi", "Salı", "Çarşamba", "Perşembe", "Cuma", "Cumartesi", "Pazar"]


def format_int(value: int) -> str:
    return f"{value:,}".replace(",", ".")


def format_dt(ts: str) -> str:
    try:
        d = datetime.fromisoformat(ts)
    except Exception:
        return ts
    return f"{d.day} {TURKISH_MONTHS[d.month]} {d.year} · {d:%H:%M}"


def countdown_text(days_left: int) -> str:
    if days_left <= 0:
        return "Bugün"
    if days_left == 1:
        return "Yarın"
    return f"{days_left} gün"


def fixture_key(fx: dict) -> str:
    return f"{fx['date'].isoformat()}|{fx['opponent']}"


def chip_qss(fg: str, bg: str, border: str = "", radius: int = 12, size: int = 12) -> str:
    border_part = f"border: 1px solid {border};" if border else "border: none;"
    return (f"color: {fg}; background-color: {bg}; {border_part} border-radius: {radius}px; "
            f"padding: 0px 11px; font-size: {size}px; font-weight: 600;")


def make_chip(text: str, fg: str, bg: str, border: str = "") -> QLabel:
    """Küçük hap biçimli etiket: sabit 24px yükseklik, satırı dikeyde doldurmaz."""
    chip = QLabel(text)
    chip.setFixedHeight(24)
    chip.setAlignment(Qt.AlignmentFlag.AlignCenter)
    chip.setStyleSheet(chip_qss(fg, bg, border))
    return chip


