# ==========================================================================================
# ÖZEL WIDGET'LAR
# ==========================================================================================

class ClickableFrame(QFrame):
    """Tıklanabilir çerçeve (kart / satır)."""
    clicked = pyqtSignal()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit()
        super().mousePressEvent(event)

    def keyPressEvent(self, event):
        # Odaklanabilen kartlarda Enter / Boşluk tıklama sayılır (klavyeyle gezinme).
        if self.focusPolicy() != Qt.FocusPolicy.NoFocus and event.key() in (
                Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space):
            self.clicked.emit()
            return
        super().keyPressEvent(event)


class ElidedLabel(QLabel):
    """Sığmayan metni sonda '…' ile kısaltan etiket (tam metin ipucu olarak gösterilir)."""

    def __init__(self, text: str = "", parent=None):
        super().__init__(parent)
        self._full_text = ""
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.set_full_text(text)

    def set_full_text(self, text: str):
        self._full_text = text
        self._apply_elide()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._apply_elide()

    def _apply_elide(self):
        width = max(self.width(), 10)
        elided = self.fontMetrics().elidedText(self._full_text, Qt.TextElideMode.ElideRight, width)
        super().setText(elided)
        self.setToolTip(self._full_text if elided != self._full_text else "")


class ToggleSwitch(QAbstractButton):
    """Hap biçimli açma/kapama anahtarı."""

    def __init__(self, checked: bool = False, parent=None):
        super().__init__(parent)
        self.setCheckable(True)
        self.setChecked(checked)
        self.setFixedSize(42, 24)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(K_GREEN if self.isChecked() else "#2A3831"))
        painter.drawRoundedRect(QRectF(0, 0, 42, 24), 12, 12)
        painter.setBrush(QColor(K_TEXT))
        painter.drawEllipse(QRectF(21 if self.isChecked() else 3, 3, 18, 18))


class ProgressRing(QWidget):
    """Ortasında yüzde ve durum metni olan dairesel ilerleme göstergesi."""

    def __init__(self, size: int = 184, parent=None):
        super().__init__(parent)
        self.setFixedSize(size, size)
        self._pct = 0.0
        self._active = False

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        layout.addStretch(1)
        self.pct_label = QLabel("0%")
        self.pct_label.setObjectName("ringPct")
        self.pct_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.state_label = QLabel("Hazır")
        self.state_label.setObjectName("ringState")
        self.state_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(self.pct_label)
        layout.addWidget(self.state_label)
        layout.addStretch(1)

    def set_progress(self, pct: float, active: bool):
        self._pct = max(0.0, min(100.0, pct))
        self._active = active
        self.pct_label.setText(f"{int(self._pct)}%")
        self.update()

    def set_state_text(self, text: str):
        self.state_label.setText(text)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        side = min(self.width(), self.height())
        rect = QRectF(15, 15, side - 30, side - 30)
        pen = QPen(QColor(K_LINE), 14)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawEllipse(rect)
        if self._active and self._pct > 0:
            pen.setColor(QColor(K_GREEN))
            painter.setPen(pen)
            painter.drawArc(rect, 90 * 16, int(-self._pct / 100.0 * 360 * 16))


class BrandMark(QWidget):
    """Kocaelispor amblemi; dosya bulunamazsa yeşil/siyah çapraz şeritli yedek işarete düşer."""

    def __init__(self, color: str = None, parent=None, size: int = 44):
        super().__init__(parent)
        self._color = color or K_GREEN
        self._size = size
        self.setFixedSize(size, size)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        rect = QRectF(0.5, 0.5, 43, 43)

        logo = get_club_logo_pixmap(self._size)
        if logo is not None:
            ratio = logo.devicePixelRatio() or 1.0
            lw, lh = logo.width() / ratio, logo.height() / ratio
            painter.drawPixmap(QPointF((self.width() - lw) / 2, (self.height() - lh) / 2), logo)
            return

        path = QPainterPath()
        path.addRoundedRect(rect, 12, 12)
        painter.setClipPath(path)
        painter.fillRect(self.rect(), QColor("#06110C"))
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(self._color))
        period, width = 19.8, 9.9
        x = -50.0
        while x < 50.0:
            stripe = QPolygonF([QPointF(x, 44), QPointF(x + width, 44),
                                QPointF(x + width + 44, 0), QPointF(x + 44, 0)])
            painter.drawPolygon(stripe)
            x += period
        painter.setClipping(False)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.setPen(QPen(QColor(K_LINE), 1))
        painter.drawRoundedRect(rect, 12, 12)


class DropZone(QFrame):
    """Klasör sürükle-bırak kabul eden kesik çizgili alan."""

    def __init__(self, on_folder_dropped, parent=None):
        super().__init__(parent)
        self.setObjectName("dropZone")
        self.setAcceptDrops(True)
        self._on_folder_dropped = on_folder_dropped

    def _set_active(self, active: bool):
        self.setProperty("active", active)
        repolish(self)

    def dragEnterEvent(self, event: QDragEnterEvent):
        if event.mimeData().hasUrls():
            for url in event.mimeData().urls():
                if url.isLocalFile() and os.path.isdir(url.toLocalFile()):
                    self._set_active(True)
                    event.acceptProposedAction()
                    return
        event.ignore()

    def dragLeaveEvent(self, event):
        self._set_active(False)

    def dropEvent(self, event: QDropEvent):
        self._set_active(False)
        for url in event.mimeData().urls():
            if url.isLocalFile() and os.path.isdir(url.toLocalFile()):
                self._on_folder_dropped(url.toLocalFile())
                event.acceptProposedAction()
                return
        event.ignore()


class LogDialog(QDialog):
    """Tam işlem günlüğü (ana ekrandaki liste son satırları gösterir)."""

    def __init__(self, log_html: str, parent=None):
        super().__init__(parent)
        self.setWindowTitle("İşlem Günlüğü")
        self.resize(760, 520)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(18, 18, 18, 18)
        text = QTextEdit()
        text.setReadOnly(True)
        text.setHtml(log_html)
        layout.addWidget(text)


