# YAPAY ZEKÂ YORUMU (Anthropic Messages API — arka plan thread'i)
# ==========================================================================================

class AiCommentWorker(QThread):
    """Maç için kısa bir yorum üretir. Ağ/anahtar hatasında uygulamayı çökertmez; hata metni döner."""
    result_signal = pyqtSignal(str, str, str)  # (önbellek_anahtarı, metin, hata)

    API_URL = "https://api.anthropic.com/v1/messages"

    def __init__(self, cache_key: str, api_key: str, model: str, system_prompt: str, user_prompt: str, parent=None):
        super().__init__(parent)
        self.cache_key = cache_key
        self.api_key = api_key
        self.model = model
        self.system_prompt = system_prompt
        self.user_prompt = user_prompt

    def run(self):
        try:
            payload = json.dumps({
                "model": self.model,
                "max_tokens": 800,
                "system": self.system_prompt,
                "messages": [{"role": "user", "content": self.user_prompt}],
            }).encode("utf-8")
            request = urllib.request.Request(
                self.API_URL, data=payload, method="POST",
                headers={
                    "content-type": "application/json",
                    "x-api-key": self.api_key,
                    "anthropic-version": "2023-06-01",
                })
            with urllib.request.urlopen(request, timeout=60, context=_verified_ssl_context()) as response:
                data = json.loads(response.read().decode("utf-8"))
            text = "".join(block.get("text", "") for block in data.get("content", [])
                           if block.get("type") == "text").strip()
            if not text:
                raise ValueError("Yapay zekâdan boş yanıt geldi.")
            self.result_signal.emit(self.cache_key, text, "")
        except urllib.error.HTTPError as e:
            detail = ""
            try:
                detail = json.loads(e.read().decode("utf-8")).get("error", {}).get("message", "")
            except Exception:
                pass
            known = {
                401: "API anahtarı geçersiz.",
                403: "Bu anahtarın erişim izni yok.",
                404: "Seçili model bulunamadı (Ayarlar'dan başka model seç).",
                429: "Kullanım sınırı aşıldı, biraz sonra tekrar dene.",
            }
            message = known.get(e.code, f"Sunucu hatası (HTTP {e.code}).")
            self.result_signal.emit(self.cache_key, "", f"{message} {detail}".strip())
        except urllib.error.URLError as e:
            self.result_signal.emit(self.cache_key, "", f"Bağlantı kurulamadı: {e.reason}")
        except Exception as e:
            self.result_signal.emit(self.cache_key, "", str(e) or type(e).__name__)


