# --- Günlük satırlarını etiketleyen düzenli ifadeler --------------------------------------------
RE_LOG_GK = re.compile(r"^\[KALECİLER\] (.+?) \(skor=([\d.]+)\): (.+)$")
RE_LOG_MIX = re.compile(r"^\[KARIŞIK\] (.+?): (.+)$")
RE_LOG_MATCH = re.compile(r"^\[(.+?)\] eşleşti \(skor=([\d.]+)\): (.+)$")

LOG_TAG_STYLES = {
    "match": (K_GREEN_HI, K_GREEN_BG),
    "gk": (K_BLUE, K_BLUE_BG),
    "mixed": (K_AMBER, K_AMBER_BG),
    "info": (K_MUTED, "#1B2A22"),
    "ok": (K_GREEN_HI, K_GREEN_BG),
    "warn": (K_AMBER, K_AMBER_BG),
    "err": (K_RED_HI, K_RED_BG),
}


def classify_log(message: str, level: str):
    """Motor mesajını (etiket, tür, kısa metin) üçlüsüne çevirir."""
    text = message.strip()
    first_line = text.splitlines()[0] if text else ""

    m = RE_LOG_GK.match(first_line)
    if m:
        return "KALECİLER", "gk", f"{m.group(1)} · skor {m.group(2)} · {m.group(3)}"
    if first_line.startswith("[HATA→KARIŞIK]"):
        return "HATA", "err", first_line.replace("[HATA→KARIŞIK]", "", 1).strip()
    m = RE_LOG_MIX.match(first_line)
    if m:
        return "KARIŞIK", "mixed", f"{m.group(1)} · {m.group(2)}"
    m = RE_LOG_MATCH.match(first_line)
    if m:
        return "EŞLEŞTİ", "match", f"{m.group(1)} · skor {m.group(2)} · {m.group(3)}"

    if level == "success":
        return "TAMAM", "ok", first_line
    if level == "warn":
        return "UYARI", "warn", first_line
    if level == "error":
        return "HATA", "err", first_line
    return "BİLGİ", "info", first_line


