def load_medya_extra() -> dict:
    base = {
        "share_links": {}, "share_message": DEFAULT_SHARE_MESSAGE, "best_count": DEFAULT_BEST_COUNT,
        "matchday": {}, "instagram_handle": "kocaelispor",
        "social": {"formats": ["Story", "Gonderi"], "mode": "Kırp", "logo": True,
                   "logo_pos": "Sağ alt", "logo_size": 12, "logo_kind": "KSmedya", "source": "Tüm oyuncu klasörleri"},
    }
    data = read_json(MEDYA_EXTRA_PATH, {})
    if isinstance(data, dict):
        for k, v in data.items():
            if k == "social" and isinstance(v, dict):
                base["social"].update(v)
            elif k in base:
                base[k] = v
    return base


def save_medya_extra(extra: dict, keys=None):
    """keys verilirse diskteki güncel dosyaya yalnız bu anahtarlar yazılır (eski kopyanın başka ayarları ezmesini önler)."""
    if keys:
        current = read_json(MEDYA_EXTRA_PATH, {})
        if not isinstance(current, dict):
            current = {}
        for k in keys:
            if k in extra:
                current[k] = extra[k]
        write_json(MEDYA_EXTRA_PATH, current)
    else:
        write_json(MEDYA_EXTRA_PATH, extra)


