SHARE_LOG_PATH = os.path.join(APP_DIR, "paylasim_gunlugu.json")


def load_share_log() -> list:
    """[{"date": "YYYY-MM-DD", "players": [...]}, ...] — en yeni tarih başta."""
    data = read_json(SHARE_LOG_PATH, [])
    out = []
    if isinstance(data, list):
        for e in data:
            if isinstance(e, dict) and isinstance(e.get("players"), list) and isinstance(e.get("date"), str):
                out.append({"date": e["date"], "players": [str(p) for p in e["players"]]})
    out.sort(key=lambda e: e["date"], reverse=True)
    return out


def add_share_entry(day, players: list):
    log = load_share_log()
    iso = day.isoformat()
    for e in log:                      # aynı gün tekrar kaydedilirse birleştir
        if e["date"] == iso:
            e["players"] = sorted(set(e["players"]) | set(players), key=turkish_lower)
            break
    else:
        log.append({"date": iso, "players": sorted(set(players), key=turkish_lower)})
    log.sort(key=lambda e: e["date"], reverse=True)
    write_json(SHARE_LOG_PATH, log[:200])


def remove_last_share_entry():
    log = load_share_log()
    if log:
        write_json(SHARE_LOG_PATH, log[1:])


def replace_share_entry(old_iso: str, new_day, players: list):
    """Var olan kaydı yeni tarih/oyuncu listesiyle değiştirir (tarih başka bir kayıtla çakışırsa birleşir)."""
    write_json(SHARE_LOG_PATH, [e for e in load_share_log() if e["date"] != old_iso])
    if players:
        add_share_entry(new_day, players)


def remove_share_entry(iso_date: str):
    write_json(SHARE_LOG_PATH, [e for e in load_share_log() if e["date"] != iso_date])


def share_stats(log: list, universe: list, today, days=None) -> dict:
    """Oyuncu başına paylaşım sayısı. days verilirse yalnız son N günün kayıtları sayılır.
    Dönüş: rows [(ad, sayı, son_tarih|None)] (çok→az, sıfırlar en sonda), entries, distinct, never."""
    entries = []
    for e in log:
        try:
            d = date.fromisoformat(e["date"])
        except ValueError:
            continue
        if days is None or (today - d).days <= days:
            entries.append((d, e["players"]))
    counts: dict = {}
    last: dict = {}
    for d, players in entries:
        for p in players:
            counts[p] = counts.get(p, 0) + 1
            if p not in last or d > last[p]:
                last[p] = d
    for n in universe:
        counts.setdefault(n, 0)
    rows = [(n, c, last.get(n)) for n, c in counts.items()]
    rows.sort(key=lambda r: (-r[1], -(r[2].toordinal() if r[2] else 0), turkish_lower(r[0])))
    distinct = sum(1 for r in rows if r[1] > 0)
    return {"rows": rows, "entries": len(entries), "distinct": distinct, "never": len(rows) - distinct}


def share_overview(log: list, universe: list, today, limit: int = 5) -> dict:
    """Son paylaşılan set + en uzun süredir paylaşılmayan oyuncular ([(ad, gün|None)], None = hiç)."""
    last_seen: dict = {}
    for e in log:                      # log yeni→eski; ilk görülen en yeni tarihtir
        try:
            d = date.fromisoformat(e["date"])
        except ValueError:
            continue
        for p in e["players"]:
            last_seen.setdefault(p, d)
    waiting = []
    for n in universe:
        d = last_seen.get(n)
        waiting.append((n, None if d is None else (today - d).days))
    waiting.sort(key=lambda t: (0, turkish_lower(t[0])) if t[1] is None else (1, -t[1], turkish_lower(t[0])))
    return {"last": log[0] if log else None, "waiting": waiting[:limit]}


def count_images(folder: str) -> int:
    try:
        return sum(1 for f in os.listdir(folder) if os.path.splitext(f)[1].lower() in IMAGE_EXTENSIONS)
    except OSError:
        return 0


def read_report(csv_path: str) -> list:
    """Rapor.csv → satır sözlükleri. Eski sürümlerin (5 sütunlu) raporlarını da okur."""
    rows = []
    try:
        with open(csv_path, newline="", encoding="utf-8-sig") as f:
            for r in csv.DictReader(f, delimiter=";"):
                rows.append({k: (r.get(k) or "") for k in REPORT_HEADER})
    except Exception:
        return []
    return rows


def write_report(csv_path: str, rows: list):
    tmp = csv_path + ".tmp"
    with open(tmp, "w", newline="", encoding="utf-8-sig") as f:
        writer = csv.writer(f, delimiter=";")
        writer.writerow(REPORT_HEADER)
        for r in rows:
            writer.writerow([r.get(k, "") for k in REPORT_HEADER])
    os.replace(tmp, csv_path)


def report_row_path(root: str, row: dict) -> str:
    """Bir rapor satırının fotoğrafının diskteki yolu (bulunamazsa boş metin)."""
    rel = row.get("Konum", "")
    if rel:
        p = os.path.join(root, rel)
        if os.path.isfile(p):
            return p
    name = row.get("Dosya", "")
    res = row.get("Sonuç", "")
    if res.startswith("Karışık"):
        cands = [os.path.join(root, MIXED_FOLDER_NAME, name)]
    elif res.startswith("Kaleci"):
        cands = [os.path.join(root, GOALKEEPER_FOLDER_NAME, name)]
    else:
        cands = [os.path.join(root, row.get("Oyuncu", ""), name)]
    for c in cands:
        if os.path.isfile(c):
            return c
    return ""


def parse_candidates(text: str) -> list:
    out = []
    for part in (text or "").split("|"):
        if ":" in part:
            n, _, sc = part.rpartition(":")
            try:
                out.append((n.strip(), float(sc)))
            except ValueError:
                pass
    return out


def load_reference_counts(ref_folder: str) -> dict:
    """ref_memory.pkl'den {oyuncu: referans sayısı} (klasör seçili değilse / önbellek yoksa boş)."""
    if not ref_folder:
        return {}
    try:
        with open(os.path.join(ref_folder, REF_CACHE_FILENAME), "rb") as f:
            data = pickle.load(f)
        return {n: len(v) for n, v in (data.get("ref_db") or {}).items()}
    except Exception:
        return {}


def build_share_entries(root: str) -> list:
    """Paylaşılacak klasörler: [{name, path, count, best, best_path, keeper}] — oyuncu adına göre sıralı."""
    entries = []
    if not root or not os.path.isdir(root):
        return entries
    rows = read_report(os.path.join(root, "Rapor.csv"))
    keeper_names: dict = {}
    for r in rows:
        if r["Sonuç"].startswith("Kaleci") and r["Oyuncu"].strip() not in ("", "-"):
            keeper_names[r["Oyuncu"].strip()] = keeper_names.get(r["Oyuncu"].strip(), 0) + 1
    has_keeper_rows = bool(keeper_names)
    for name in os.listdir(root):
        p = os.path.join(root, name)
        if not os.path.isdir(p) or name in SPECIAL_FOLDERS:
            continue
        if name == GOALKEEPER_FOLDER_NAME and has_keeper_rows:
            continue  # kaleciler aşağıda tek tek eklenir
        best_path = os.path.join(root, SELECTION_FOLDER_NAME, name)
        entries.append({"name": name, "path": p, "count": count_images(p),
                        "best": count_images(best_path), "best_path": best_path, "keeper": False})
    for name, cnt in keeper_names.items():
        best_path = os.path.join(root, SELECTION_FOLDER_NAME, name)
        entries.append({"name": name, "path": best_path if os.path.isdir(best_path)
                        else os.path.join(root, GOALKEEPER_FOLDER_NAME),
                        "count": cnt, "best": count_images(best_path), "best_path": best_path, "keeper": True})
    entries.sort(key=lambda e: turkish_lower(e["name"]))
    return entries


