# ==========================================================================================
# DEPARTMAN ALTYAPISI — şifreli depolama, paylaşılan veri, kadro
# ==========================================================================================
# Bu bölüm Sağlık / İdari / Teknik kadro / Futbolcu ekranlarının ortak temelidir.
#
#  * Her korumalı departmanın verisi ayrı bir şifreli dosyada tutulur (~/.kocaelispor_foto_ayiklama/).
#  * Dosya, rastgele bir "ana anahtar" ile şifrelenir (Fernet / AES). Ana anahtar iki kopya halinde
#    saklanır: biri PIN'den, biri "kurtarma kodu"ndan türetilen anahtarla sarılır. PIN unutulursa
#    kurtarma koduyla açılır; ikisi de kaybedilirse veri geri getirilemez (tasarım gereği).
#  * Departmanlar arası paylaşım YALNIZCA en az bilgiyle yapılır ("paylaşılan alan"): oyuncunun durum
#    etiketi + tahmini dönüş tarihi + sağlık biriminin oyuncuya yazdığı kısa not. Tanı, tedavi, test
#    sonucu gibi ayrıntılar yalnızca Sağlık departmanının şifreli dosyasında kalır.

import base64
import hashlib
import hmac
import secrets
import unicodedata

try:
    from cryptography.fernet import Fernet, InvalidToken
    CRYPTO_OK = True
except ImportError:  # paket yoksa korumalı departmanlar açılmaz, Medya çalışmaya devam eder
    Fernet = None
    CRYPTO_OK = False

    class InvalidToken(Exception):
        pass

DEPARTMENTS = ["medya", "saglik", "idari", "teknik", "diyetisyen", "futbolcu"]
# Giriş ekranında görünen departmanlar. Futbolcu bölümü şimdilik gizli; kodu yerinde duruyor,
# tekrar açmak için "futbolcu"yu bu listeye geri eklemek yeterli.
VISIBLE_DEPARTMENTS = ["medya", "saglik", "idari", "teknik", "diyetisyen"]
STORE_FILES = {"saglik": "saglik.enc", "idari": "idari.enc", "teknik": "teknik.enc", "diyetisyen": "diyetisyen.enc"}
SHARED_PATH = os.path.join(APP_DIR, "paylasim.enc")
APP_KEY_PATH = os.path.join(APP_DIR, "uygulama.key")
PLAYER_PIN_PATH = os.path.join(APP_DIR, "futbolcu_pin.json")

SCRYPT_N = 2 ** 15
MIN_PIN_LEN = 6          # departman PIN'i / parolası en az bu kadar karakter
MIN_PLAYER_PIN_LEN = 4   # futbolcunun kişisel PIN'i


def _derive_key(secret: str, salt: bytes) -> bytes:
    raw = hashlib.scrypt(secret.encode("utf-8"), salt=salt, n=SCRYPT_N, r=8, p=1,
                         maxmem=128 * 1024 * 1024, dklen=32)
    return base64.urlsafe_b64encode(raw)


def normalize_recovery(code: str) -> str:
    return "".join(ch for ch in code.upper() if ch.isalnum())


def generate_recovery_code() -> str:
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"  # karışan karakterler (0/O, 1/I) yok
    raw = "".join(secrets.choice(alphabet) for _ in range(20))
    return "-".join(raw[i:i + 4] for i in range(0, 20, 4))


def _atomic_write(path: str, data: bytes):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    if os.path.isfile(path):
        try:
            shutil.copy2(path, path + ".bak")  # bozulmaya karşı bir önceki sürüm
        except Exception:
            pass
    os.replace(tmp, path)
    try:
        os.chmod(path, 0o600)
    except Exception:
        pass


