class SecureStore:
    """PIN ile korunan, şifreli tek dosyalık veri deposu."""

    VERSION = 2

    def __init__(self, path: str, factory):
        self.path = path
        self.factory = factory
        self.data = None
        self._master = None
        self._wraps = {}
        self.error = ""

    def exists(self) -> bool:
        return os.path.isfile(self.path)

    @property
    def unlocked(self) -> bool:
        return self.data is not None and self._master is not None

    # --- oluşturma / açma ---------------------------------------------------------
    def create(self, pin: str) -> str:
        """Yeni depo oluşturur, kurtarma kodunu döndürür (kullanıcıya bir kez gösterilir)."""
        if not CRYPTO_OK:
            raise RuntimeError("cryptography paketi kurulu değil")
        self._master = Fernet.generate_key()
        recovery = generate_recovery_code()
        self._wraps = {
            "pin": self._wrap(pin, self._master),
            "recovery": self._wrap(normalize_recovery(recovery), self._master),
        }
        self.data = self.factory()
        self.save()
        return recovery

    def unlock(self, secret: str) -> bool:
        """PIN ya da kurtarma koduyla açar. Yanlışsa False döner (dosya değişmez)."""
        self.error = ""
        if not CRYPTO_OK:
            self.error = "cryptography paketi kurulu değil"
            return False
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                blob = json.load(f)
            wraps = blob["wraps"]
            token = blob["data"].encode("ascii")
        except Exception:
            self.error = "Veri dosyası okunamadı"
            return False

        candidates = (("pin", secret), ("recovery", normalize_recovery(secret)))
        for kind, value in candidates:
            wrap = wraps.get(kind)
            if not wrap or not value:
                continue
            try:
                master = self._unwrap(value, wrap)
                data = json.loads(Fernet(master).decrypt(token).decode("utf-8"))
            except (InvalidToken, ValueError):
                continue
            self._master, self._wraps, self.data = master, wraps, data
            for key, value_default in self.factory().items():   # yeni eklenen alanlar için
                self.data.setdefault(key, value_default)
            return True
        return False

    def save(self):
        if not self.unlocked:
            return
        token = Fernet(self._master).encrypt(json.dumps(self.data, ensure_ascii=False).encode("utf-8"))
        blob = {"v": self.VERSION, "wraps": self._wraps, "data": token.decode("ascii")}
        _atomic_write(self.path, json.dumps(blob).encode("utf-8"))

    def lock(self):
        self.data = None
        self._master = None

    def change_pin(self, new_pin: str):
        if self.unlocked:
            self._wraps["pin"] = self._wrap(new_pin, self._master)
            self.save()

    # --- anahtar sarma ------------------------------------------------------------
    @staticmethod
    def _wrap(secret: str, master: bytes) -> dict:
        salt = os.urandom(16)
        token = Fernet(_derive_key(secret, salt)).encrypt(master)
        return {"salt": base64.b64encode(salt).decode("ascii"), "token": token.decode("ascii")}

    @staticmethod
    def _unwrap(secret: str, wrap: dict) -> bytes:
        salt = base64.b64decode(wrap["salt"])
        return Fernet(_derive_key(secret, salt)).decrypt(wrap["token"].encode("ascii"))


class SharedStore:
    """Departmanlar arası paylaşılan asgari bilgi (uygulama anahtarıyla şifreli; PIN gerektirmez)."""

    def default(self) -> dict:
        return {"availability": {}, "training": [], "announcements": [], "travel": [],
                "wellness": {}, "appointments": {}, "feedback": {}}

    def _fernet(self):
        if not CRYPTO_OK:
            return None
        try:
            if os.path.isfile(APP_KEY_PATH):
                with open(APP_KEY_PATH, "rb") as f:
                    key = f.read().strip()
            else:
                key = Fernet.generate_key()
                _atomic_write(APP_KEY_PATH, key)
            return Fernet(key)
        except Exception:
            return None

    def load(self) -> dict:
        data = self.default()
        try:
            with open(SHARED_PATH, "rb") as f:
                raw = f.read()
            fernet = self._fernet()
            text = fernet.decrypt(raw) if fernet else raw
            loaded = json.loads(text.decode("utf-8"))
            if isinstance(loaded, dict):
                data.update({k: v for k, v in loaded.items() if k in data})
        except Exception:
            pass
        return data

    def save(self, data: dict):
        raw = json.dumps(data, ensure_ascii=False).encode("utf-8")
        fernet = self._fernet()
        _atomic_write(SHARED_PATH, fernet.encrypt(raw) if fernet else raw)

    def update(self, mutate) -> dict:
        data = self.load()
        mutate(data)
        self.save(data)
        return data


class PlayerPins:
    """Futbolcuların kişisel PIN'leri (yalnızca özet/hash saklanır, PIN'in kendisi değil)."""

    def __init__(self, path: str = None):
        self.path = path or PLAYER_PIN_PATH

    def _load(self) -> dict:
        data = read_json(self.path, {})
        return data if isinstance(data, dict) else {}

    @staticmethod
    def _hash(pin: str, salt: bytes) -> bytes:
        return hashlib.scrypt(pin.encode("utf-8"), salt=salt, n=2 ** 14, r=8, p=1,
                              maxmem=64 * 1024 * 1024, dklen=32)

    def has_pin(self, pid: str) -> bool:
        return pid in self._load()

    def set_pin(self, pid: str, pin: str):
        data = self._load()
        salt = os.urandom(16)
        data[pid] = {"salt": base64.b64encode(salt).decode("ascii"),
                     "hash": base64.b64encode(self._hash(pin, salt)).decode("ascii")}
        write_json(self.path, data, private=True)

    def verify(self, pid: str, pin: str) -> bool:
        entry = self._load().get(pid)
        if not entry:
            return False
        try:
            salt = base64.b64decode(entry["salt"])
            expected = base64.b64decode(entry["hash"])
        except Exception:
            return False
        return hmac.compare_digest(self._hash(pin, salt), expected)

    def reset(self, pid: str):
        data = self._load()
        if data.pop(pid, None) is not None:
            write_json(self.path, data, private=True)


