    # ------------------------------------------------------------------
    # Ana sayfadaki kulüp kartları
    # ------------------------------------------------------------------
    def _share_universe(self) -> list:
        names = sorted(load_reference_counts(self.ref_folder).keys(), key=turkish_lower)
        return names or [p["name"] for p in ROSTER]

    def _share_add(self):
        names = self._share_universe()
        pre = [n for n in getattr(self, "last_social_players", []) if n in names]
        if len(pre) > 12:
            pre = []
        dlg = ShareLogDialog(names, pre, self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            day, players = dlg.result_data()
            if players:
                add_share_entry(day, players)
            self._refresh_share_track()

    def _share_history(self):
        dlg = ShareHistoryDialog(self._share_universe(), self)
        dlg.exec()
        self._refresh_share_track()

    def _share_undo(self):
        log = load_share_log()
        if not log:
            return
        e = log[0]
        ans = QMessageBox.question(self, "Son kaydı sil",
                                   f"{e['date']} tarihli kayıt ({len(e['players'])} oyuncu) silinsin mi?")
        if ans == QMessageBox.StandardButton.Yes:
            remove_last_share_entry()
            self._refresh_share_track()

    def _write_widget_data(self, last, never: int = 0, waiting=(), day_text=None):
        """macOS widget'ının (widget/ShareWidget.swift) okuduğu anlık görüntüyü yazar. Hata olursa sessizce geçer."""
        try:
            import base64
            from PyQt6.QtCore import QBuffer, QIODevice
            players = []
            for n in (last["players"] if last else [])[:8]:
                face = ""
                pm = get_player_photo_pixmap(n, 96)
                if pm is not None:
                    buf = QBuffer()
                    buf.open(QIODevice.OpenModeFlag.WriteOnly)
                    pm.save(buf, "PNG")
                    face = base64.b64encode(bytes(buf.data())).decode("ascii")
                players.append({"name": n, "first": (n.split() or [n])[0], "face": face})
            data = {
                "updated": datetime.now().isoformat(timespec="seconds"),
                "last": ({"date": day_text(last["date"]) if day_text else last["date"],
                          "count": len(last["players"]), "players": players} if last else None),
                "never": int(never),
                "waiting": [{"name": n, "days": days} for n, days in list(waiting)[:8]],
            }
            folder = os.path.join(str(ks_data.user_data_dir()), "widget")
            os.makedirs(folder, exist_ok=True)
            tmp = os.path.join(folder, "share.json.tmp")
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False)
            os.replace(tmp, os.path.join(folder, "share.json"))
            self._ios_sync()
            self._reload_mac_widgets()
        except Exception:  # noqa: BLE001
            pass

    def _refresh_share_track(self):
        clear_layout(self.track_faces)
        clear_layout(self.track_side)
        log = load_share_log()
        if not log:
            hint = QLabel("Henüz kayıt yok. Bir antrenman paylaşımını \"+ Paylaşım kaydet\" ile işaretleyince burada "
                          "son paylaşılan oyuncular ve sırası gelenler görünür.")
            hint.setObjectName("emptyHint")
            hint.setWordWrap(True)
            self.track_faces.addWidget(hint)
            self.track_faces.addStretch(1)
            self._write_widget_data(None)
            return
        universe = self._share_universe()
        ov = share_overview(log, universe, date.today())
        last = log[0]

        def day_text(iso: str, with_wd: bool = False) -> str:
            try:
                d = date.fromisoformat(iso)
                return f"{d.day} {TURKISH_MONTHS[d.month]}" + (f" {DAYS_TR[d.weekday()][:3]}" if with_wd else "")
            except ValueError:
                return iso

        # ---- Sol: son paylaşılan oyuncu yüzleri
        cap = QLabel(f"Son paylaşım · {day_text(last['date'])} · {len(last['players'])} oyuncu")
        cap.setObjectName("rowTitle")
        self.track_faces.addWidget(cap)
        grid = QGridLayout()
        grid.setSpacing(10)
        for i, n in enumerate(last["players"]):
            cell = QVBoxLayout()
            cell.setSpacing(3)
            cell.addWidget(make_avatar_label(n, 44, "avatar"), 0, Qt.AlignmentFlag.AlignHCenter)
            first = QLabel(n.split()[0] if n.split() else n)
            first.setObjectName("dateSub")
            first.setAlignment(Qt.AlignmentFlag.AlignCenter)
            cell.addWidget(first)
            holder = QWidget()
            holder.setLayout(cell)
            holder.setFixedWidth(70)
            grid.addWidget(holder, i // 4, i % 4)
        self.track_faces.addLayout(grid)
        self.track_faces.addStretch(1)

        # ---- Sağ: sırası gelenler (istatistik/geçmiş yalnız "Geçmiş ve istatistik ›" ile açılır)
        week = share_stats(log, universe, date.today(), days=7)
        if week["never"]:
            warn = make_chip(f"Son 7 günde paylaşılmayan: {week['never']} oyuncu", K_AMBER, K_AMBER_BG)
        else:
            warn = make_chip("Son 7 günde herkes paylaşıldı", K_GREEN_HI, K_GREEN_BG)
        self.track_side.addWidget(warn, 0, Qt.AlignmentFlag.AlignLeft)
        self.track_side.addStretch(1)
        self._write_widget_data(last, week["never"], ov["waiting"], day_text)

    def _write_widget_extra(self):
        """macOS widget'larının (widget/*.swift) okuduğu program / maç / doğum günü anlık görüntüsü (extra.json)."""
        try:
            import base64
            from PyQt6.QtCore import QBuffer, QIODevice

            def b64(pm) -> str:
                if pm is None:
                    return ""
                buf = QBuffer()
                buf.open(QIODevice.OpenModeFlag.WriteOnly)
                pm.save(buf, "PNG")
                return base64.b64encode(bytes(buf.data())).decode("ascii")

            today = date.today()
            days = []
            for pr in PROGRAMS:
                by_day = {}
                for it in pr["items"]:
                    by_day.setdefault(it["date"], []).append(
                        {"time": it.get("time", ""), "title": it.get("title", ""), "kind": it.get("kind", "meal")})
                for iso, items in by_day.items():
                    if iso >= (today - timedelta(days=1)).isoformat():
                        items.sort(key=lambda i: i["time"] or "99:99")
                        days.append({"date": iso, "subtitle": pr.get("subtitle", ""), "items": items})
            days.sort(key=lambda d: d["date"])
            fixtures = []
            for fx in get_upcoming_fixtures()[:3]:
                fixtures.append({"date": fx["date"].isoformat(), "time": fx.get("time", ""), "opponent": fx["opponent"],
                                 "home": bool(fx["home"]), "stadium": fx.get("stadium", ""),
                                 "oppLogo": b64(get_team_logo_pixmap(fx["opponent"], 96))})
            birthdays = []
            for b in get_birthday_list()[:6]:
                nxt = today + timedelta(days=b["days_left"])
                birthdays.append({"name": b["name"], "first": (b["name"].split() or [b["name"]])[0],
                                  "next": nxt.isoformat(), "turning": nxt.year - b["date"].year,
                                  "face": b64(get_player_photo_pixmap(b["name"], 96))})
            data = {"updated": datetime.now().isoformat(timespec="seconds"), "program": days,
                    "clubLogo": b64(get_club_logo_pixmap(96)), "fixtures": fixtures, "birthdays": birthdays}
            folder = os.path.join(str(ks_data.user_data_dir()), "widget")
            os.makedirs(folder, exist_ok=True)
            tmp = os.path.join(folder, "extra.json.tmp")
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False)
            os.replace(tmp, os.path.join(folder, "extra.json"))
            self._ios_sync()
            self._reload_mac_widgets()
        except Exception:  # noqa: BLE001
            pass

    def _reload_mac_widgets(self):
        """Mac widget'larını hemen yeniletir (widget uygulamasını "--reload" ile arka planda çalıştırır).
        Eski kurulumda (reload desteği yok) uygulama ana uygulamayı açmaya çalışır; bu yüzden yalnızca
        widget sürümü 2 ve üstüyse çağrılır. En fazla 20 sn'de bir."""
        try:
            now = time.time()
            if now - getattr(self, "_widget_reload_ts", 0) < 20:
                return
            marker = os.path.join(str(ks_data.user_data_dir()), "widget", "reload_ok")
            host = "/Applications/MediaStaffKS-Widget.app"
            if not (os.path.isdir(host) and os.path.exists(marker)):
                return
            self._widget_reload_ts = now
            subprocess.Popen(["/usr/bin/open", "-g", "-j", host, "--args", "--reload"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:  # noqa: BLE001
            pass

    def _ios_status_text(self) -> str:
        st = getattr(self, "_ios_state", None)
        if not st:
            return "iPhone widget'ları: henüz eşitlenmedi."
        kind, detail = st
        if kind == "ok":
            return f"iPhone widget'ları: iCloud'a yazıldı ({datetime.now().strftime('%H:%M')} · {detail}). Betik sürümü {APP_VERSION}."
        if kind == "no_icloud":
            return ("iPhone widget'ları: Scriptable'ın iCloud klasörü Mac'te bulunamadı. iPhone'da Scriptable'ı açıp "
                    "iCloud Drive'ı etkinleştir, Mac'te Finder → iCloud Drive → Scriptable klasörünün göründüğünü kontrol et.")
        return f"iPhone widget'ları: eşitleme hatası — {detail}"

    def _ios_sync_now(self):
        self._write_widget_data_from_log()
        self._write_widget_extra()
        if hasattr(self, "ios_status"):
            self.ios_status.setText(self._ios_status_text())

    def _write_widget_data_from_log(self):
        try:
            self._refresh_share_track()
        except Exception:  # noqa: BLE001
            pass

    def _ios_sync(self):
        """Widget verisini (ve iPhone betiğini) Scriptable'ın iCloud klasörüne kopyalar; Scriptable yoksa sessizce geçer."""
        try:
            folder = os.path.join(str(ks_data.user_data_dir()), "widget")
            self._ios_state = ks_data.ios_sync(folder)
        except Exception as exc:  # noqa: BLE001
            self._ios_state = ("error", str(exc))
        try:
            if hasattr(self, "ios_status"):
                self.ios_status.setText(self._ios_status_text())
        except Exception:  # noqa: BLE001
            pass

