    def _build_matches_page(self) -> QWidget:
        page = QWidget()
        row = QHBoxLayout(page)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(20)

        # Sol: maç listesi
        list_card, l_layout = self._card(spacing=12)
        list_card.setFixedWidth(380)
        l_layout.addWidget(self._section_label("Yaklaşan maçlar"))
        list_inner = QWidget()
        self.match_list_layout = QVBoxLayout(list_inner)
        self.match_list_layout.setContentsMargins(0, 0, 0, 0)
        self.match_list_layout.setSpacing(8)
        self.match_list_layout.addStretch(1)
        l_layout.addWidget(self._scroll(list_inner), 1)
        row.addWidget(list_card)

        # Sağ: detay
        detail_inner = QWidget()
        detail = QVBoxLayout(detail_inner)
        detail.setContentsMargins(0, 0, 0, 0)
        detail.setSpacing(16)

        self.match_hero_card, self.match_hero_layout = self._card(margins=(24, 22, 24, 22), spacing=18)
        detail.addWidget(self.match_hero_card)
        self.match_prog_card, self.match_prog_layout = self._card(margins=(24, 20, 24, 20), spacing=10)
        detail.addWidget(self.match_prog_card)
        detail.addStretch(1)

        row.addWidget(self._scroll(detail_inner), 1)
        return page

    def _refresh_matches_page(self):
        upcoming = get_upcoming_fixtures()
        keys = [fixture_key(f) for f in upcoming]
        if not upcoming:
            self._selected_fx = None
        elif self._selected_fx is None or fixture_key(self._selected_fx) not in keys:
            self._selected_fx = upcoming[0]

        clear_layout(self.match_list_layout)
        selected_key = fixture_key(self._selected_fx) if self._selected_fx else ""
        if not upcoming:
            empty = QLabel("Yaklaşan maç bulunamadı.")
            empty.setObjectName("emptyHint")
            self.match_list_layout.addWidget(empty)
        for fx in upcoming:
            self.match_list_layout.addWidget(self._make_match_item(fx, fixture_key(fx) == selected_key))
        self.match_list_layout.addStretch(1)

        self._refresh_match_hero()

    def _make_match_item(self, fx: dict, selected: bool) -> QFrame:
        item = ClickableFrame()
        item.setObjectName("matchItem")
        item.setProperty("selected", selected)
        item.setCursor(Qt.CursorShape.PointingHandCursor)
        item.clicked.connect(lambda fx=fx: self._select_fixture(fx))
        row = QHBoxLayout(item)
        row.setContentsMargins(12, 10, 12, 10)
        row.setSpacing(14)

        d = fx["date"]
        date_col = QVBoxLayout()
        date_col.setSpacing(0)
        day = QLabel(f"{d.day:02d}")
        day.setObjectName("dayBig")
        day.setAlignment(Qt.AlignmentFlag.AlignCenter)
        month = QLabel(turkish_upper(TURKISH_MONTHS[d.month][:3]))
        month.setObjectName("monthSmall")
        month.setAlignment(Qt.AlignmentFlag.AlignCenter)
        date_col.addWidget(day)
        date_col.addWidget(month)
        date_wrap = QWidget()
        date_wrap.setFixedWidth(46)
        date_wrap.setLayout(date_col)
        row.addWidget(date_wrap)

        text_col = QVBoxLayout()
        text_col.setSpacing(2)
        opponent = ElidedLabel(fx["opponent"])
        opponent.setObjectName("fxOpp")
        sub = QLabel(f"{fx['time']} · {'İç saha' if fx['home'] else 'Deplasman'}")
        sub.setObjectName("dateSub")
        text_col.addWidget(opponent)
        text_col.addWidget(sub)
        row.addLayout(text_col, 1)

        days_left = (d - date.today()).days
        left = QLabel(countdown_text(days_left))
        left.setObjectName("dateSub")
        row.addWidget(left)
        return item

