    def _build_birthdays_page(self) -> QWidget:
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        card, c_layout = self._card(spacing=10)
        self.bd_count_label = self._section_label("Kadro")
        c_layout.addWidget(self.bd_count_label)
        inner = QWidget()
        self.bd_rows_layout = QVBoxLayout(inner)
        self.bd_rows_layout.setContentsMargins(0, 0, 0, 0)
        self.bd_rows_layout.setSpacing(0)
        c_layout.addWidget(self._scroll(inner), 1)
        layout.addWidget(card, 1)
        return page

    def _refresh_birthdays_page(self):
        clear_layout(self.bd_rows_layout)
        birthdays = get_birthday_list()
        self.bd_count_label.setText(turkish_upper(f"Kadro · {len(birthdays)} oyuncu"))
        if not birthdays:
            empty = QLabel("Doğum günü verisi eklenmedi.")
            empty.setObjectName("emptyHint")
            self.bd_rows_layout.addWidget(empty)
        today = date.today()
        soon = sum(1 for b in birthdays if b["days_left"] <= 7)
        if soon:
            self.bd_count_label.setText(turkish_upper(f"Kadro · {len(birthdays)} oyuncu · Bu hafta {soon} doğum günü"))
        last_month = None
        for b in birthdays:
            dob = b["date"]
            next_bday = today + timedelta(days=b["days_left"])
            turning = next_bday.year - dob.year
            month_key = (next_bday.year, next_bday.month)
            if month_key != last_month:                      # ay başlıkları: listeyi taramayı kolaylaştırır
                last_month = month_key
                if self.bd_rows_layout.count():
                    self.bd_rows_layout.addSpacing(10)
                self.bd_rows_layout.addWidget(self._section_label(f"{TURKISH_MONTHS[next_bday.month]} {next_bday.year}"))
                self.bd_rows_layout.addSpacing(4)

            row = QFrame()
            row.setObjectName("rowLine")
            row.setFixedHeight(62)
            row_layout = QHBoxLayout(row)
            row_layout.setContentsMargins(0, 0, 0, 0)
            row_layout.setSpacing(14)

            avatar = make_avatar_label(b["name"], 40, "avatar")
            row_layout.addWidget(avatar)

            text_col = QVBoxLayout()
            text_col.setSpacing(2)
            name = QLabel(b["name"])
            name.setObjectName("bdName")
            sub = QLabel(f"{dob.day} {TURKISH_MONTHS[dob.month]} · {turning}. yaşına giriyor")
            sub.setObjectName("dateSub")
            text_col.addWidget(name)
            text_col.addWidget(sub)
            row_layout.addLayout(text_col, 1)

            if b["days_left"] == 0:
                chip = make_chip("Bugün", "#04140D", K_GREEN)
            elif b["days_left"] <= 30:
                chip = make_chip(f"{b['days_left']} gün", K_GREEN_HI, K_GREEN_BG)
            else:
                chip = make_chip(f"{b['days_left']} gün", K_MUTED, "#1B2A22")
            row_layout.addWidget(chip, 0, Qt.AlignmentFlag.AlignVCenter)
            msg_btn = QPushButton("Mesajı kopyala")
            msg_btn.setObjectName("linkBtn")
            msg_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            msg_btn.setToolTip("Doğum günü paylaşım metnini panoya kopyalar")
            msg_btn.clicked.connect(lambda checked=False, n=b["name"], t=turning, btn=msg_btn: self._copy_birthday_text(n, t, btn))
            row_layout.addWidget(msg_btn, 0, Qt.AlignmentFlag.AlignVCenter)
            self.bd_rows_layout.addWidget(row)
        self.bd_rows_layout.addStretch(1)

    def _copy_birthday_text(self, full_name: str, turning: int, btn: QPushButton):
        first = (full_name.split() or [full_name])[0]
        text = (f"Doğum günün kutlu olsun {first}! 🎂\n"
                f"{turning}. yaşında sağlık, mutluluk ve başarı dolu bir yıl dileriz. 💚🖤\n\n#Kocaelispor")
        QApplication.clipboard().setText(text)
        try:
            btn.setText("Kopyalandı ✓")
            QTimer.singleShot(1600, lambda: btn.setText("Mesajı kopyala"))
        except RuntimeError:
            pass

    # ==================================================================
    # HAFTALIK PROGRAM (kulübün antrenman / yemek / kamp / maç günü programı)
    # ==================================================================
    PROGRAM_KIND_STYLE = {          # tür -> (yazı rengi, arka plan, kenarlık)
        "training": (K_RED_HI, K_RED_BG, "#5A2A2D"), "gym": (K_GREEN_HI, K_GREEN_BG, "#1E4A36"),
        "meal": (K_SOFT, "#1B2420", K_LINE), "match": (K_BLUE, K_BLUE_BG, "#2C4A7A"),
        "meeting": (K_AMBER, K_AMBER_BG, "#5A4720"), "camp": (K_AMBER, K_AMBER_BG, "#5A4720"),
        "off": (K_GREEN_HI, "#0E2A1F", "#1E4A36"),
    }

    def _build_program_page(self) -> QWidget:
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(12)
        head = QHBoxLayout()
        head.setSpacing(10)
        self.prog_title = QLabel("")
        self.prog_title.setObjectName("rowTitle")
        head.addWidget(self.prog_title, 1)
        self.prog_prev = QPushButton("‹ Önceki")
        self.prog_next = QPushButton("Sonraki ›")
        for b in (self.prog_prev, self.prog_next):
            b.setObjectName("ghostBtn")
            b.setFixedHeight(34)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            head.addWidget(b)
        mini_btn = QPushButton("Mini pencere")
        cal_btn = QPushButton("Takvim'e aktar")
        for b, fn in ((mini_btn, lambda: self.prog_mini.toggle()), (cal_btn, self._export_program_ics)):
            b.setObjectName("ghostBtn")
            b.setFixedHeight(34)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(fn)
            head.addWidget(b)
        self.prog_prev.clicked.connect(lambda: self._shift_program(-1))
        self.prog_next.clicked.connect(lambda: self._shift_program(1))
        layout.addLayout(head)
        inner = QWidget()
        self.prog_cols = QHBoxLayout(inner)
        self.prog_cols.setContentsMargins(0, 0, 0, 0)
        self.prog_cols.setSpacing(10)
        area = QScrollArea()
        area.setWidgetResizable(True)
        area.setFrameShape(QFrame.Shape.NoFrame)
        area.setWidget(inner)
        layout.addWidget(area, 1)
        self.prog_index = None
        return page

    def _program_default_index(self) -> int:
        today = date.today().isoformat()
        for i, pr in enumerate(PROGRAMS):
            if pr["start"] <= today <= pr.get("end", pr["start"]):
                return i
        later = [i for i, pr in enumerate(PROGRAMS) if pr["start"] > today]
        return later[0] if later else len(PROGRAMS) - 1

    def _shift_program(self, delta: int):
        if PROGRAMS and self.prog_index is not None:
            self.prog_index = max(0, min(len(PROGRAMS) - 1, self.prog_index + delta))
            self._refresh_program_page(keep_index=True)

    # ==================================================================
    # PROGRAM "WIDGET"I: menü çubuğu simgesi + mini pencere + Takvim'e aktarım
    # ==================================================================
    def _init_program_widgets(self):
        self.prog_mini = ProgramMiniWindow(self.PROGRAM_KIND_STYLE)
        self.prog_tray = None
        if QSystemTrayIcon.isSystemTrayAvailable():
            pix = get_club_logo_pixmap(44)
            self.prog_tray = QSystemTrayIcon(QIcon(pix) if pix is not None else QIcon(), self)
            self.prog_menu = QMenu()
            self.prog_menu.aboutToShow.connect(self._fill_tray_menu)
            self.prog_tray.setContextMenu(self.prog_menu)
            self.prog_tray.setToolTip("MediaStaffKS · Bugünün programı")
            self.prog_tray.show()
        if self.prog_mini.restore_position():
            QTimer.singleShot(1500, self.prog_mini.show_and_remember)
        self._tray_timer = QTimer(self)
        self._tray_timer.setInterval(60 * 1000)
        self._tray_timer.timeout.connect(self._update_tray_tooltip)
        self._tray_timer.start()
        self._update_tray_tooltip()

    def _update_tray_tooltip(self):
        try:   # gün değişimi / "son etkinlikten 30 dk sonra yarın" geçişinde ana sayfa kartını tazele
            vd = program_view_date()
            if getattr(self, "_prog_view_seen", vd) != vd:
                self._refresh_today_program()
                self._write_widget_extra()
            self._prog_view_seen = vd
        except Exception:  # noqa: BLE001
            pass
        if self.prog_tray is None:
            return
        items, _ = program_today_items()
        nxt = program_next_index(items)
        if nxt != -1:
            it = items[nxt]
            pre = "Yarın" if program_view_date() != date.today() else "Sıradaki"
            self.prog_tray.setToolTip(f"{pre}: {it.get('time') or ''} {it.get('title', '')}".strip())
        else:
            self.prog_tray.setToolTip("MediaStaffKS · Bugün için başka program yok")

    def _fill_tray_menu(self):
        menu = self.prog_menu
        menu.clear()
        items, subtitle = program_today_items()
        nxt = program_next_index(items)
        head = menu.addAction(f"{'Yarının' if program_view_date() != date.today() else 'Bugünün'} programı{' · ' + subtitle if subtitle else ''}")
        head.setEnabled(False)
        if not items:
            menu.addAction("Bugün için program yok").setEnabled(False)
        for idx, it in enumerate(items):
            mark = "▶ " if idx == nxt else "    "
            menu.addAction(f"{mark}{it.get('time') or 'Gün boyu'}   {it.get('title', '')}").setEnabled(False)
        menu.addSeparator()
        menu.addAction("Mini pencereyi göster / gizle", self.prog_mini.toggle)
        menu.addAction("Haftalık programı aç", self._show_program_page)
        menu.addAction("Takvim'e aktar (.ics)", self._export_program_ics)
        menu.addSeparator()
        menu.addAction("Ana pencereyi göster", self._show_main_window)

    def _show_main_window(self):
        self.showNormal()
        self.raise_()
        self.activateWindow()

    def _show_program_page(self):
        self._show_main_window()
        self._go_to(PAGE_PROGRAM)

    def _export_program_ics(self):
        text = ks_data.programs_to_ics(PROGRAMS)
        if not text:
            QMessageBox.information(self, "Takvim", "Bugünden itibaren aktarılacak program satırı yok.")
            return
        path = os.path.join(str(ks_data.user_data_dir()), "MediaStaffKS-Program.ics")
        try:
            with open(path, "w", encoding="utf-8", newline="") as fh:
                fh.write(text)
        except OSError as e:
            QMessageBox.warning(self, "Takvim", f"Dosya yazılamadı:\n{e}")
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(path))   # Takvim açılır ve hangi takvime ekleneceğini sorar

    def _refresh_today_program(self):
        """Ana sayfadaki kart: yalnızca BUGÜNÜN programı."""
        if not hasattr(self, "today_prog_rows"):
            return
        clear_layout(self.today_prog_rows)
        items, subtitle = program_today_items()
        tomorrow = program_view_date() != date.today()
        self.today_prog_label.setText(turkish_upper("Yarının programı" if tomorrow else "Bugünün programı"))
        self._prog_view_seen = program_view_date()
        self.today_prog_sub.setText(subtitle)
        self.today_prog_sub.setVisible(bool(subtitle))
        if not items:
            hint = QLabel("Bugün için program eklenmedi.")
            hint.setObjectName("emptyHint")
            self.today_prog_rows.addWidget(hint)
            return
        for it in items:
            fg, bg, bd = self.PROGRAM_KIND_STYLE.get(it.get("kind", "meal"), self.PROGRAM_KIND_STYLE["meal"])
            row = QFrame()
            row.setObjectName("progRow")
            row.setStyleSheet(f"QFrame#progRow {{ background: {bg}; border: 1px solid {bd}; border-radius: 10px; }}")
            rl = QHBoxLayout(row)
            rl.setContentsMargins(10, 6, 10, 6)
            rl.setSpacing(10)
            t = QLabel(it.get("time") or "Gün boyu")
            t.setFixedWidth(46)
            t.setStyleSheet(f"color: {fg}; font-weight: 700; background: transparent; border: none;")
            n = QLabel(it.get("title", ""))
            n.setWordWrap(True)
            n.setStyleSheet(f"color: {K_TEXT}; background: transparent; border: none;")
            rl.addWidget(t)
            rl.addWidget(n, 1)
            self.today_prog_rows.addWidget(row)

    def _refresh_program_page(self, keep_index: bool = False):
        clear_layout(self.prog_cols)
        if not PROGRAMS:
            self.prog_title.setText("")
            self.prog_prev.setEnabled(False)
            self.prog_next.setEnabled(False)
            empty = QLabel("Henüz haftalık program eklenmedi.")
            empty.setObjectName("emptyHint")
            self.prog_cols.addWidget(empty)
            return
        if not keep_index or self.prog_index is None:
            self.prog_index = self._program_default_index()
        pr = PROGRAMS[self.prog_index]
        self.prog_prev.setEnabled(self.prog_index > 0)
        self.prog_next.setEnabled(self.prog_index < len(PROGRAMS) - 1)

        def dm(iso):
            d = date.fromisoformat(iso)
            return f"{d.day:02d}.{d.month:02d}"
        end = pr.get("end", pr["start"])
        bits = [pr.get("title", "Program"), pr.get("subtitle", "")]
        if pr.get("coach"):
            bits.append(f"{pr['coach']} · Teknik Direktör")
        bits.append(f"{dm(pr['start'])} – {dm(end)}.{date.fromisoformat(end).year}")
        self.prog_title.setText("  ·  ".join(b for b in bits if b))

        by_day = {}
        for it in pr["items"]:
            by_day.setdefault(it["date"], []).append(it)
        today_iso = date.today().isoformat()
        day = date.fromisoformat(pr["start"])
        last = date.fromisoformat(end)
        while day <= last:
            iso = day.isoformat()
            items = sorted(by_day.get(iso, []), key=lambda i: i.get("time") or "99:99")
            is_off = any(i.get("kind") == "off" for i in items)
            col = QFrame()
            col.setObjectName("progCol")
            col.setMinimumWidth(150)
            col.setStyleSheet(f"QFrame#progCol {{ background: {K_CARD}; border-radius: 14px; "
                              f"border: 1px solid {K_GREEN if iso == today_iso else K_LINE}; }}")
            lay = QVBoxLayout(col)
            lay.setContentsMargins(10, 10, 10, 10)
            lay.setSpacing(8)
            title = QLabel(f"{DAYS_TR[day.weekday()]}\n{day.day:02d}.{day.month:02d}.{day.year}")
            title.setAlignment(Qt.AlignmentFlag.AlignCenter)
            title.setStyleSheet(f"color: {K_GREEN_HI if iso == today_iso else K_TEXT}; font-weight: 700; "
                                "background: transparent; border: none;")
            lay.addWidget(title)
            if is_off:
                fg, bg, bd = self.PROGRAM_KIND_STYLE["off"]
                off = QLabel("İZİN\nOFF")
                off.setAlignment(Qt.AlignmentFlag.AlignCenter)
                off.setStyleSheet(f"color: {fg}; background: {bg}; border: 1px solid {bd}; border-radius: 10px; "
                                  "font-weight: 700; padding: 18px 6px;")
                lay.addWidget(off, 1)
            else:
                for it in items:
                    fg, bg, bd = self.PROGRAM_KIND_STYLE.get(it.get("kind", "meal"), self.PROGRAM_KIND_STYLE["meal"])
                    cell = QFrame()
                    cell.setObjectName("progCell")
                    cell.setStyleSheet(f"QFrame#progCell {{ background: {bg}; border: 1px solid {bd}; border-radius: 10px; }}")
                    cl = QVBoxLayout(cell)
                    cl.setContentsMargins(8, 6, 8, 8)
                    cl.setSpacing(2)
                    t = QLabel(it.get("time") or "—")
                    t.setStyleSheet(f"color: {fg}; font-weight: 700; background: transparent; border: none;")
                    n = QLabel(it.get("title", ""))
                    n.setWordWrap(True)
                    n.setStyleSheet(f"color: {K_TEXT}; background: transparent; border: none;")
                    cl.addWidget(t)
                    cl.addWidget(n)
                    lay.addWidget(cell)
                lay.addStretch(1)
            self.prog_cols.addWidget(col, 1)
            day += timedelta(days=1)

    # ==================================================================
    # SAYFA 3b — BASIN GÜNLERİ (röportaj takvimi: kim hangi hafta röportaj aldı)
    # ==================================================================
    def _build_press_page(self) -> QWidget:
        page = QWidget()
        outer_layout = QVBoxLayout(page)
        outer_layout.setContentsMargins(0, 0, 0, 0)
        outer_layout.setSpacing(0)

        inner = QWidget()
        outer_v = QVBoxLayout(inner)
        outer_v.setContentsMargins(0, 0, 0, 0)
        outer_v.setSpacing(16)

        # --- İstatistik kartı: kim kaç kez Beinsports / Antrenman röportajı almış -----------
        stats_card, s_layout = self._card(spacing=10)
        s_layout.addWidget(self._section_label("Kim Kaç Kez Çıktı"))
        stats_hint = QLabel("Hafta kartlarındaki isimlerden otomatik hesaplanır — kadroya "
                             "dengeli dağıtmak için kullan.")
        stats_hint.setObjectName("noteText")
        stats_hint.setWordWrap(True)
        s_layout.addWidget(stats_hint)
        s_layout.addWidget(self._section_label("Sırası gelenler (en az çıkanlar)"))
        self.press_suggest_layout = QHBoxLayout()
        self.press_suggest_layout.setSpacing(8)
        s_layout.addLayout(self.press_suggest_layout)
        sug_hint = QLabel("Bir isme tıkla: en son tıkladığın Beinsports / Antrenman kutusuna eklenir.")
        sug_hint.setObjectName("noteText")
        s_layout.addWidget(sug_hint)
        self.press_stats_layout = QVBoxLayout()
        self.press_stats_layout.setSpacing(0)
        s_layout.addLayout(self.press_stats_layout)
        outer_v.addWidget(stats_card)

        # --- Düzenlenebilir hafta kartları ----------------------------------------------------
        weeks_card, c_layout = self._card(spacing=10)
        head = QHBoxLayout()
        self.press_count_label = self._section_label("Röportaj Takvimi")
        head.addWidget(self.press_count_label)
        head.addStretch(1)
        add_btn = QPushButton("+ Hafta ekle")
        add_btn.setObjectName("outlineSmall")
        add_btn.setFixedHeight(32)
        add_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        add_btn.clicked.connect(lambda checked=False: self._add_press_row())
        head.addWidget(add_btn)
        save_btn = QPushButton("Kaydet")
        save_btn.setObjectName("aiBtn")
        save_btn.setFixedHeight(32)
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.clicked.connect(lambda checked=False: self._save_press_page())
        head.addWidget(save_btn)
        c_layout.addLayout(head)

        note = QLabel("Her kart bir hafta/maç dönemi. İsim yazarken öneriler çıkar; birden fazla isim \" - \" ile ayrılır. "
                      "Değişiklikler otomatik kaydedilir.")
        note.setObjectName("noteText")
        note.setWordWrap(True)
        c_layout.addWidget(note)

        self.press_status = QLabel("")
        self.press_status.setObjectName("aiStatus")
        c_layout.addWidget(self.press_status)

        rows_inner = QWidget()
        self.press_rows_layout = QVBoxLayout(rows_inner)
        self.press_rows_layout.setContentsMargins(0, 0, 0, 0)
        self.press_rows_layout.setSpacing(10)
        c_layout.addWidget(rows_inner)
        outer_v.addWidget(weeks_card)

        outer_layout.addWidget(self._scroll(inner), 1)
        self._press_row_widgets = []
        self._press_focus_edit = None
        self._press_save_timer = QTimer(self)
        self._press_save_timer.setSingleShot(True)
        self._press_save_timer.setInterval(700)
        self._press_save_timer.timeout.connect(lambda: self._save_press_page(auto=True))
        QApplication.instance().focusChanged.connect(self._press_focus_changed)
        return page

    def _press_autosave_later(self, *_):
        self._press_save_timer.start()

    def _press_focus_changed(self, old, new):
        for entry in getattr(self, "_press_row_widgets", []):
            if new is entry["bein"] or new is entry["ant"]:
                self._press_focus_edit = new
                return

    def _press_insert_name(self, name: str):
        edit = self._press_focus_edit
        try:
            cur = edit.text().strip() if edit is not None else None
        except RuntimeError:       # satır silinmiş
            edit, cur = None, None
        if edit is None:
            QApplication.clipboard().setText(name)
            self.press_status.setText(f"Panoya kopyalandı: {name}. Önce bir Beinsports / Antrenman kutusuna tıklarsan oraya eklenir.")
            return
        if name.lower() in cur.lower():
            self.press_status.setText(f"{name} zaten yazılı.")
            return
        edit.setText(f"{cur} - {name}" if cur else name)
        edit.setFocus()
        self._press_autosave_later()

    def _refresh_press_suggestions(self):
        clear_layout(self.press_suggest_layout)
        for name, total in press_suggestions(6):
            b = QPushButton(f"{name}  ·  {total}×")
            b.setObjectName("outlineSmall")
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setToolTip("Eklemek için tıkla")
            b.clicked.connect(lambda checked=False, n=name: self._press_insert_name(n))
            self.press_suggest_layout.addWidget(b)
        self.press_suggest_layout.addStretch(1)

    def _refresh_press_page(self):
        clear_layout(self.press_rows_layout)
        self._press_row_widgets = []
        self._press_focus_edit = None
        self.press_status.setText("")
        weeks = PRESS_WEEKS
        self.press_count_label.setText(turkish_upper(f"Röportaj Takvimi · {len(weeks)} hafta"))
        for w in weeks:
            self._add_press_row(w.get("hafta", ""), w.get("beinsports", ""), w.get("antrenman", ""))
        if not weeks:
            self._add_press_row()
        self._refresh_press_stats()

    def _refresh_press_stats(self):
        clear_layout(self.press_stats_layout)
        self._refresh_press_suggestions()
        stats = press_stats()
        if not stats:
            empty = QLabel("Henüz istatistik yok — bir hafta kartına isim yazıp kaydet.")
            empty.setObjectName("emptyHint")
            self.press_stats_layout.addWidget(empty)
            return
        for s in stats:
            row = QFrame()
            row.setObjectName("rowLine")
            h = QHBoxLayout(row)
            h.setContentsMargins(0, 10, 0, 10)
            h.setSpacing(10)
            name_lab = QLabel(s["name"])
            name_lab.setObjectName("bdName")
            h.addWidget(name_lab, 1)
            h.addWidget(make_chip(f"Beinsports · {s['bein']}", K_GREEN_HI, K_GREEN_BG))
            h.addWidget(make_chip(f"Antrenman · {s['ant']}", K_AMBER, K_AMBER_BG))
            total_lab = QLabel(f"Toplam {s['total']}")
            total_lab.setObjectName("dateSub")
            total_lab.setFixedWidth(84)
            total_lab.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            h.addWidget(total_lab)
            self.press_stats_layout.addWidget(row)

    def _add_press_row(self, hafta: str = "", beinsports: str = "", antrenman: str = ""):
        row = QFrame()
        row.setObjectName("rowLine")
        v = QVBoxLayout(row)
        v.setContentsMargins(14, 12, 14, 12)
        v.setSpacing(10)

        top = QHBoxLayout()
        top.setSpacing(10)
        hafta_edit = QLineEdit(hafta)
        hafta_edit.setPlaceholderText("Hafta (ör. 5. Samsun Maç Haftası)")
        hafta_edit.setObjectName("bdName")
        top.addWidget(hafta_edit, 1)
        del_btn = QPushButton("Sil")
        del_btn.setObjectName("outlineSmall")
        del_btn.setFixedHeight(30)
        del_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        top.addWidget(del_btn)
        v.addLayout(top)

        cols = QHBoxLayout()
        cols.setSpacing(16)

        bein_col = QVBoxLayout()
        bein_col.setSpacing(4)
        bein_col.addWidget(self._section_label("Beinsports"))
        bein_edit = QLineEdit(beinsports)
        bein_edit.setPlaceholderText("ör. Berkan Kutlu - Show")
        bein_col.addWidget(bein_edit)
        cols.addLayout(bein_col, 1)

        ant_col = QVBoxLayout()
        ant_col.setSpacing(4)
        ant_col.addWidget(self._section_label("Antrenman"))
        ant_edit = QLineEdit(antrenman)
        ant_edit.setPlaceholderText("ör. Emir Ortakaya")
        ant_col.addWidget(ant_edit)
        cols.addLayout(ant_col, 1)

        v.addLayout(cols)

        entry = {"frame": row, "hafta": hafta_edit, "bein": bein_edit, "ant": ant_edit}
        for ed in (bein_edit, ant_edit):
            comp = MultiNameCompleter([p["name"] for p in ROSTER], ed)
            comp.setCaseSensitivity(Qt.CaseSensitivity.CaseInsensitive)
            comp.setFilterMode(Qt.MatchFlag.MatchContains)
            comp.setCompletionMode(QCompleter.CompletionMode.PopupCompletion)
            ed.setCompleter(comp)
        for ed in (hafta_edit, bein_edit, ant_edit):
            ed.textEdited.connect(self._press_autosave_later)
        del_btn.clicked.connect(lambda checked=False, e=entry: self._remove_press_row(e))
        self._press_row_widgets.append(entry)
        self.press_rows_layout.addWidget(row)

    def _remove_press_row(self, entry: dict):
        entry["frame"].setParent(None)
        entry["frame"].deleteLater()
        if entry in self._press_row_widgets:
            self._press_row_widgets.remove(entry)
        if self._press_focus_edit in (entry["bein"], entry["ant"]):
            self._press_focus_edit = None
        self._press_autosave_later()

    def _save_press_page(self, auto: bool = False):
        global PRESS_WEEKS
        weeks = []
        for entry in self._press_row_widgets:
            hafta = entry["hafta"].text().strip()
            bein = entry["bein"].text().strip()
            ant = entry["ant"].text().strip()
            if not hafta and not (bein or ant):
                continue                      # tamamen boş kart
            weeks.append({"hafta": hafta or "(Adsız hafta)", "beinsports": bein, "antrenman": ant})
        ks_data.save_press(weeks)
        PRESS_WEEKS = weeks
        self.press_count_label.setText(turkish_upper(f"Röportaj Takvimi · {len(weeks)} hafta"))
        stamp = datetime.now().strftime("%H:%M")
        self.press_status.setText(f"Otomatik kaydedildi · {stamp}" if auto else f"Kaydedildi · {stamp} — {len(weeks)} hafta.")
        self._refresh_press_stats()

