            empty = QLabel("Henüz tamamlanmış bir işlem yok. Yüz Ayıklama sayfasından bir işlem başlattığında burada listelenir.")
            empty.setObjectName("emptyHint")
            empty.setWordWrap(True)
            self.report_rows_layout.addWidget(empty)
