    def _toggle_key_visibility(self, visible: bool):
        self.api_key_edit.setEchoMode(QLineEdit.EchoMode.Normal if visible else QLineEdit.EchoMode.Password)
        self.show_key_btn.setText("Gizle" if visible else "Göster")

    def _load_settings_fields(self):
        cfg = load_config()
        self.api_key_edit.setText(cfg.get("anthropic_api_key", ""))
        model = cfg.get("ai_model") or DEFAULT_AI_MODEL
        button = self.model_buttons.get(model) or self.model_buttons[DEFAULT_AI_MODEL]
        button.setChecked(True)
        if not cfg.get("anthropic_api_key") and os.environ.get("ANTHROPIC_API_KEY"):
            self._set_settings_status("ANTHROPIC_API_KEY ortam değişkeni kullanılıyor.")
        else:
            self._set_settings_status("")

    def _set_settings_status(self, text: str, error: bool = False):
        self.settings_status.setText(text)
        self.settings_status.setProperty("error", error)
        repolish(self.settings_status)

    def _save_settings(self):
        cfg = load_config()
        cfg["anthropic_api_key"] = self.api_key_edit.text().strip()
        for model_id, button in self.model_buttons.items():
            if button.isChecked():
                cfg["ai_model"] = model_id
        save_config(cfg)
        self._set_settings_status("Kaydedildi.")

    def _clear_api_key(self):
        self.api_key_edit.clear()
        cfg = load_config()
        cfg["anthropic_api_key"] = ""
        save_config(cfg)
        self._set_settings_status("Anahtar silindi.")

    def _clear_ai_cache(self):
        self._ai_cache = {}
        write_json(AI_CACHE_PATH, self._ai_cache)
        self._set_settings_status("Kayıtlı yorumlar temizlendi.")

    # ==================================================================
    # SAAT / SÜRE
    # ==================================================================
    def _tick_clock(self):
        now = datetime.now()
        self.date_label.setText(f"{DAYS_TR[now.weekday()]}, {now.day} {TURKISH_MONTHS[now.month]} {now.year}")
        self.time_label.setText(now.strftime("%H:%M:%S"))
        if now.date() != self._shown_date:  # gün değişti: sayaçları yenile
            self._shown_date = now.date()
            self._refresh_club_cards()

    def _tick_elapsed(self):
        if self._start_time is None:
            return
        elapsed = int(time.time() - self._start_time)
        self.elapsed_label.setText(f"{elapsed // 60:02d}:{elapsed % 60:02d}")
        if self._last_processed > 0 and self._last_total > self._last_processed:
            per_photo = elapsed / self._last_processed
            remaining = int(per_photo * (self._last_total - self._last_processed))
            self.eta_label.setText(f"~{remaining // 60:02d}:{remaining % 60:02d}")
        elif self._last_total > 0 and self._last_processed >= self._last_total:
            self.eta_label.setText("00:00")

    # ==================================================================
    # KLASÖR SEÇİMİ
    # ==================================================================
    def _select_ref_folder(self):
        folder = QFileDialog.getExistingDirectory(self, "Referans Görüntülerini Seç")
        if folder:
            self._set_ref_folder(folder)

    def _select_media_folder(self):
        folder = QFileDialog.getExistingDirectory(self, "Antrenman Veya Maç Görüntülerini Seç")
        if folder:
            self._set_media_folder(folder)

    def _set_path_label(self, label: ElidedLabel, folder: str):
        label.set_full_text(folder)
        label.setProperty("filled", True)
        repolish(label)

    def _set_ref_folder(self, folder: str):
        self.ref_folder = folder
        self._set_path_label(self.ref_path_label, folder)
        if hasattr(self, "track_body"):
            self._refresh_share_track()

    def _set_media_folder(self, folder: str):
        self.media_folder = folder
        self._set_path_label(self.media_path_label, folder)

    # ==================================================================
    # GÜNLÜK
    # ==================================================================
    def _append_log(self, message: str, level: str = "info"):
        color = {"info": K_SOFT, "success": K_GREEN_HI, "warn": K_AMBER, "error": K_RED_HI}.get(level, K_SOFT)
        stamp = datetime.now().strftime("%H:%M:%S")
        safe = message.replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>")
        self._log_html.append(f'<span style="color:{K_DIM}">[{stamp}]</span> '
                              f'<span style="color:{color}">{safe}</span>')

        tag, kind, short = classify_log(message, level)
        if not short:
            return
        fg, bg = LOG_TAG_STYLES.get(kind, LOG_TAG_STYLES["info"])

        row = QWidget()
        row_layout = QHBoxLayout(row)
        row_layout.setContentsMargins(0, 0, 0, 0)
        row_layout.setSpacing(12)
        time_label = QLabel(stamp)
        time_label.setObjectName("logTime")
        chip = QLabel(tag)
        chip.setFixedWidth(84)
        chip.setAlignment(Qt.AlignmentFlag.AlignCenter)
        chip.setStyleSheet(f"color: {fg}; background-color: {bg}; border-radius: 6px; "
                           f"padding: 2px 6px; font-family: {FONT_MONO}; font-size: 10px; font-weight: 500;")
        msg = ElidedLabel(short)
        msg.setObjectName("logMsg")
        row_layout.addWidget(time_label)
        row_layout.addWidget(chip)
        row_layout.addWidget(msg, 1)

        self.log_empty.setVisible(False)
        self.log_scroll.setVisible(True)
        self.log_rows_layout.insertWidget(self.log_rows_layout.count() - 1, row)
        self._log_row_count += 1

        while self._log_row_count > self.MAX_LOG_ROWS:
            item = self.log_rows_layout.takeAt(0)
            if item.widget() is not None:
                item.widget().deleteLater()
            self._log_row_count -= 1

        bar = self.log_scroll.verticalScrollBar()
        QTimer.singleShot(0, lambda: bar.setValue(bar.maximum()))

    def _clear_log_rows(self):
        while self.log_rows_layout.count() > 1:
            item = self.log_rows_layout.takeAt(0)
            if item.widget() is not None:
                item.widget().deleteLater()
        self._log_row_count = 0
        self._log_html.clear()
        self.log_scroll.setVisible(False)
        self.log_empty.setVisible(True)

    def _open_log_dialog(self):
        html = "<br>".join(self._log_html) if self._log_html else "Henüz bir kayıt yok."
        LogDialog(html, self).exec()

    # ==================================================================
    # DURUM GÖSTERİMİ
    # ==================================================================
    def _set_start_button_running(self, running: bool):
        self.start_btn.setProperty("running", running)
        if running:
            self.start_btn.setText("Durdur")
            icon = make_icon("stop", "#FFFFFF", 16)
        else:
            self.start_btn.setText("Ayıklamayı başlat")
            icon = make_icon("play", "#04140D", 18)
        if not icon.isNull():
            self.start_btn.setIcon(icon)
            self.start_btn.setIconSize(QSize(18, 18))
        repolish(self.start_btn)

    def _show_idle_state(self):
        self.ring.set_progress(0, False)
        self.ring.set_state_text("Hazır")
        self._update_stats(0, 0, 0)
        self.elapsed_label.setText("00:00")
        self.eta_label.setText("—")

    def _update_stats(self, total: int, processed: int, success: int):
        remaining = max(total - processed, 0)
        self.stat_values["total"].setText(format_int(total))
        self.stat_values["processed"].setText(format_int(processed))
        self.stat_values["remaining"].setText(format_int(remaining))
        if processed > 0:
            pct = success / processed * 100
            self.stat_values["success"].setText(f"%{pct:.1f}".replace(".", ","))
        else:
            self.stat_values["success"].setText("—")

    # ==================================================================
    # İŞLEM KONTROLÜ
    # ==================================================================
    def _on_start_stop_clicked(self):
        if self._is_running:
            self._stop_extraction()
        else:
            self._start_extraction()

    def _start_extraction(self):
        if not self.ref_folder or not os.path.isdir(self.ref_folder):
            QMessageBox.warning(self, "Eksik Bilgi", "Lütfen geçerli bir Referans Görüntüleri klasörü seçin.")
            return
        if not self.media_folder or not os.path.isdir(self.media_folder):
            QMessageBox.warning(self, "Eksik Bilgi", "Lütfen geçerli bir Antrenman/Maç Görüntüleri klasörü seçin.")
            return

        self._clear_log_rows()
        self._show_idle_state()
        self.open_btn.setEnabled(False)
        self._output_folder = ""
        self._csv_path = ""
        self._stop_requested = False
        self._is_running = True
        self._set_start_button_running(True)
        self.ring.set_progress(0, True)
        self.ring.set_state_text("İşleniyor")

        self._start_time = time.time()
        self._last_processed = 0
        self._last_total = 0
        self._success_count = 0
        self.elapsed_timer.start()

        self.worker = ExtractionWorker(
            ref_folder=self.ref_folder,
            media_folder=self.media_folder,
            threshold=self.thr_slider.value() / 100.0,
            margin=self.mrg_slider.value() / 100.0,
            quality_filter=self.quality_toggle.isChecked(),
            force_rebuild_cache=self.rebuild_toggle.isChecked(),
        )
        self.worker.log_signal.connect(self._append_log)
        self.worker.progress_signal.connect(self._on_progress)
        self.worker.finished_signal.connect(self._on_finished)
        self.worker.start()
        self._append_log("İşlem başlatıldı...", "info")

    def _stop_extraction(self):
        if self.worker is not None:
            self._stop_requested = True
            self.worker.cancel()
            self._append_log("Durdurma sinyali gönderildi, mevcut dosya işlendikten sonra duracak...", "warn")
            self.start_btn.setEnabled(False)
            self.ring.set_state_text("Durduruluyor")

    def _on_progress(self, processed: int, total: int, success: int, fail: int):
        self._last_processed = processed
        self._last_total = total
        self._success_count = success
        self._update_stats(total, processed, success)
        pct = (processed / total * 100) if total > 0 else 0
        self.ring.set_progress(pct, True)

    def _on_finished(self, stats: dict):
        self.elapsed_timer.stop()
        self._is_running = False
        self.start_btn.setEnabled(True)
        self._set_start_button_running(False)

        total = stats.get("toplam", 0)
        processed = stats.get("islenen", 0)
        success = stats.get("basarili", 0)
        self._update_stats(total, processed, success)

        pct = (processed / total * 100) if total > 0 else 0
        self.ring.set_progress(pct, total > 0)
        self.ring.set_state_text("Durduruldu" if self._stop_requested else "Tamamlandı")

        output_folder = stats.get("output_folder", "")
        self._output_folder = output_folder
        self._csv_path = stats.get("csv_path", "")
        self.open_btn.setEnabled(bool(output_folder) and os.path.isdir(output_folder))

        self._append_log(
            f"İşlem bitti. Toplam {total}, başarılı {success}, kaleci {stats.get('kaleci', 0)}, "
            f"karışık {stats.get('karisik', 0)}.", "success")
        if self._csv_path:
            self._append_log(f"Denetim raporu: {self._csv_path}", "info")

        if total > 0:
            append_history({
                "ts": datetime.now().isoformat(timespec="seconds"),
                "toplam": total, "islenen": processed, "basarili": success,
                "kaleci": stats.get("kaleci", 0), "karisik": stats.get("karisik", 0),
                "klasor": output_folder, "csv": self._csv_path,
                "stopped": self._stop_requested, "per_player": stats.get("per_player", {}),
            })

        QApplication.beep()
        if output_folder and os.path.isdir(output_folder):
            self.set_work_folder(output_folder)
        title = "İşlem Tamamlandı" if not self._stop_requested else "İşlem Durduruldu"
        msg = f"Çıktı klasörü:\n{output_folder or '-'}"
        box = QMessageBox(self)
        box.setWindowTitle(title)
        box.setIcon(QMessageBox.Icon.Information)
        box.setText(msg)
        review_btn = None
        if stats.get("karisik", 0) > 0 and output_folder:
            review_btn = box.addButton(f"Karışık {stats['karisik']} fotoğrafı incele", QMessageBox.ButtonRole.AcceptRole)
        share_btn = box.addButton("Sosyal medyaya geç", QMessageBox.ButtonRole.ActionRole) if output_folder else None
        box.addButton("Tamam", QMessageBox.ButtonRole.RejectRole)
        box.exec()
        clicked = box.clickedButton()
        if review_btn is not None and clicked is review_btn:
            self._go_to(PAGE_REVIEW)
        elif share_btn is not None and clicked is share_btn:
            self._go_to(PAGE_SHARE)

    def _open_output_folder(self):
        if self._output_folder and os.path.isdir(self._output_folder):
            QDesktopServices.openUrl(QUrl.fromLocalFile(self._output_folder))
        else:
            QMessageBox.warning(self, "Klasör Bulunamadı", "Henüz oluşturulmuş bir çıktı klasörü yok.")

    def _request_switch(self):
        if self._is_running:
            QMessageBox.information(self, "İşlem sürüyor",
                                    "Ayıklama sürerken departman değiştirilemez. Önce işlemi durdur.")
            return
        self.switch_requested.emit()

    def closeEvent(self, event):
        if self.worker is not None and self.worker.isRunning():
            self.worker.cancel()
            self.worker.wait(3000)
        for w in list(self._ai_workers):
            w.wait(1500)
        try:                                    # mini pencere ve menü çubuğu simgesi ana pencereyle birlikte kapanır
            was_open = self.prog_mini.isVisible()
            self.prog_mini.timer.stop()
            self.prog_mini.hide()
            if was_open:
                self.prog_mini._save(True)      # bir sonraki açılışta yine açık gelsin
            if self.prog_tray is not None:
                self.prog_tray.hide()
        except Exception:  # noqa: BLE001
            pass
        event.accept()




