class DocumentDialog(BaseDialog):
    def __init__(self, parent=None):
        super().__init__("Belge ekle", parent, width=500,
                         hint="Belgenin kendisi kopyalanmaz; dosyanın bu bilgisayardaki yolu kaydedilir.")
        self.title_edit = QLineEdit()
        self.add_field("Başlık", self.title_edit)
        path_row = QWidget()
        pr = QHBoxLayout(path_row)
        pr.setContentsMargins(0, 0, 0, 0)
        pr.setSpacing(8)
        self.path_edit = QLineEdit()
        pr.addWidget(self.path_edit, 1)
        browse = QPushButton("Gözat…")
        browse.setObjectName("outlineSmall")
        browse.setFixedHeight(38)
        browse.clicked.connect(self._browse)
        pr.addWidget(browse)
        self.add_field("Dosya", path_row)
        self.category = QComboBox()
        self.category.addItems(DOC_CATEGORIES)
        self.add_field("Kategori", self.category)
        self.expires = OptionalDate("", "Geçerlilik bitiş tarihi var")
        self.add_field("Geçerlilik", self.expires)
        self.note = QLineEdit()
        self.add_field("Not", self.note)

    def _browse(self):
        path, _ = QFileDialog.getOpenFileName(self, "Belge seç")
        if path:
            self.path_edit.setText(path)
            if not self.title_edit.text().strip():
                self.title_edit.setText(Path(path).stem)

    def validate(self) -> bool:
        if not self.title_edit.text().strip():
            self.show_error("Başlık boş olamaz.")
            return False
        return True

    def values(self) -> dict:
        return {"id": new_id(), "title": self.title_edit.text().strip(), "path": self.path_edit.text().strip(),
                "note": self.note.text().strip(), "category": self.category.currentText(),
                "expires": self.expires.value()}


