class AttendanceDialog(BaseDialog):
    def __init__(self, title: str, absent, parent=None):
        super().__init__(f"Yoklama — {title}", parent, width=480,
                         hint="İşaretli oyuncular antrenmandaydı. Katılmayanların işaretini kaldır.")
        inner = QWidget()
        col = QVBoxLayout(inner)
        col.setContentsMargins(4, 4, 4, 4)
        col.setSpacing(6)
        self.checks = {}
        for p in ROSTER:
            cb = QCheckBox(f"{p['name']}  ·  {p['pos']}")
            cb.setChecked(p["id"] not in set(absent))
            self.checks[p["id"]] = cb
            col.addWidget(cb)
        area = QScrollArea()
        area.setWidgetResizable(True)
        area.setFixedHeight(340)
        area.setWidget(inner)
        self.form.addWidget(area)
        quick = QHBoxLayout()
        all_btn = QPushButton("Hepsi geldi")
        all_btn.setObjectName("outlineSmall")
        all_btn.clicked.connect(lambda: [cb.setChecked(True) for cb in self.checks.values()])
        none_btn = QPushButton("Hepsini temizle")
        none_btn.setObjectName("outlineSmall")
        none_btn.clicked.connect(lambda: [cb.setChecked(False) for cb in self.checks.values()])
        quick.addWidget(all_btn)
        quick.addWidget(none_btn)
        quick.addStretch(1)
        self.form.addLayout(quick)

    def absent(self) -> list:
        return [pid for pid, cb in self.checks.items() if not cb.isChecked()]


