def score_chip(value) -> QLabel:
    """1–5 (ya da ortalama) değerini renkli hap olarak gösterir."""
    if value is None:
        return make_chip("—", K_MUTED, "#1B2A22")
    fg, bg = ("#2FD69A", "#12291F") if value >= 4 else (("#F2B24A", "#2A2113") if value >= 3 else ("#FF7B7F", "#2E1719"))
    return make_chip(f"{value:.1f}".rstrip("0").rstrip(".") if isinstance(value, float) else str(value), fg, bg)


def wellness_avg(rec: dict):
    vals = [rec.get(k) for k in ("sleep", "energy", "muscle", "mood") if rec.get(k)]
    return sum(vals) / len(vals) if vals else None


