class DeptWindow(UiKit, QMainWindow):
    """Sol menü + başlık + sayfa yığını iskeleti. Alt sınıflar build_pages() ve on_page() yazar."""

    switch_requested = pyqtSignal()
    lock_requested = pyqtSignal()

    KEY = ""
    TITLE = ""
    LABEL = ""
    NAV: list = []
    META: list = []
    NAV_OF_PAGE: dict = {}
    CHIP_TEXT = "Şifreli · yalnızca bu cihazda"
    IDLE_LOCK_SECONDS = 600

    def __init__(self, store=None, shared=None, player=None, pins=None):
        super().__init__()
        self.store = store
        self.shared = shared
        self.player = player
        self.pins = pins
        self.acc = ACCENTS[self.KEY]
        self._last_activity = time.time()
        self.setWindowTitle(f"MediaStaffKS — {self.TITLE}")
        screen = QApplication.primaryScreen()
        if screen is not None:
            avail = screen.availableGeometry()
            self.resize(min(1360, avail.width() - 40), min(860, avail.height() - 40))
        else:
            self.resize(1360, 860)
        self.setMinimumSize(1100, 640)

        self.init_state()
        self._build_shell()
        self.setStyleSheet(themed_stylesheet(self.KEY))

        self.clock_timer = QTimer(self)
        self.clock_timer.setInterval(250)  # saniye değişimini gecikmesiz yakalamak için
        self.clock_timer.timeout.connect(self._tick_clock)
        self.clock_timer.start()
        self._tick_clock()

        app = QApplication.instance()
        if app is not None:
            app.installEventFilter(self)   # boşta kalma süresini izlemek için
        self.idle_timer = QTimer(self)
        self.idle_timer.setInterval(15000)
        self.idle_timer.timeout.connect(self._check_idle)
        self.idle_timer.start()

        self.go_to(0)

    # --- alt sınıfların doldurduğu yerler ---------------------------------------------
    def init_state(self):
        pass

    def build_pages(self) -> list:
        return []

    def on_page(self, index: int):
        pass

    # --- iskelet ------------------------------------------------------------------------
    def _build_shell(self):
        root = QWidget()
        root.setObjectName("root")
        self.setCentralWidget(root)
        outer = QHBoxLayout(root)
        outer.setContentsMargins(24, 24, 24, 24)
        outer.setSpacing(20)
        outer.addWidget(self._build_rail())

        content = QVBoxLayout()
        content.setSpacing(20)
        content.addWidget(self._build_header())
        self.stack = QStackedWidget()
        for page in self.build_pages():
            self.stack.addWidget(page)
        content.addWidget(self.stack, 1)
        outer.addLayout(content, 1)

    def _build_rail(self) -> QFrame:
        rail = QFrame()
        rail.setObjectName("rail")
        rail.setFixedWidth(84)
        layout = QVBoxLayout(rail)
        layout.setContentsMargins(9, 16, 9, 16)
        layout.setSpacing(6)

        layout.addWidget(BrandMark(self.acc["acc"]), 0, Qt.AlignmentFlag.AlignHCenter)
        tag = QLabel(self.LABEL)
        tag.setAlignment(Qt.AlignmentFlag.AlignCenter)
        tag.setStyleSheet(f"color: {self.acc['hi']}; font-size: 9px; font-weight: 700; margin: 6px 0 8px 0;")
        layout.addWidget(tag)

        self.nav_group = QButtonGroup(self)
        self.nav_group.setExclusive(True)
        self.nav_buttons = []
        for index, (icon_name, label) in enumerate(self.NAV):
            btn = QToolButton()
            btn.setObjectName("navBtn")
            btn.setCheckable(True)
            btn.setText(label)
            btn.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextUnderIcon)
            icon = make_state_icon(icon_name, K_MUTED, self.acc["hi"], 22)
            if not icon.isNull():
                btn.setIcon(icon)
                btn.setIconSize(QSize(22, 22))
            btn.setFixedSize(66, 52)
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            self.nav_group.addButton(btn, index)
            self.nav_buttons.append(btn)
            layout.addWidget(btn, 0, Qt.AlignmentFlag.AlignHCenter)
        self.nav_group.idClicked.connect(self.go_to)

        layout.addStretch(1)
        return rail

    def _build_header(self) -> QWidget:
        header = QWidget()
        header.setFixedHeight(64)
        row = QHBoxLayout(header)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(10)

        title_col = QVBoxLayout()
        title_col.setSpacing(4)
        title_col.setContentsMargins(0, 0, 0, 0)
        self.page_title = QLabel("")
        self.page_title.setObjectName("pageTitle")
        self.page_sub = QLabel("")
        self.page_sub.setObjectName("pageSub")
        title_col.addStretch(1)
        title_col.addWidget(self.page_title)
        title_col.addWidget(self.page_sub)
        title_col.addStretch(1)
        row.addLayout(title_col)
        row.addStretch(1)

        if self.CHIP_TEXT:
            row.addWidget(make_chip(self.CHIP_TEXT, self.acc["hi"], self.acc["bg"]), 0, Qt.AlignmentFlag.AlignVCenter)

        pill = QFrame()
        pill.setObjectName("pill")
        pill.setFixedHeight(44)
        pill_row = QHBoxLayout(pill)
        pill_row.setContentsMargins(18, 0, 18, 0)
        pill_row.setSpacing(10)
        pill_row.addWidget(self._icon_label("calendar", self.acc["hi"], 18))
        self.date_label = QLabel("—")
        self.date_label.setObjectName("pillText")
        dot = QLabel("·")
        dot.setObjectName("pillDot")
        self.time_label = QLabel("--:--:--")
        self.time_label.setObjectName("pillTime")
        self.time_label.setStyleSheet(f"font-family: {FONT_MONO};")
        self.time_label.setMinimumWidth(80)
        pill_row.addWidget(self.date_label)
        pill_row.addWidget(dot)
        pill_row.addWidget(self.time_label)
        row.addWidget(pill)

        actions = [("lock", "Kilitle", self._do_lock), ("grid", "Departman değiştir", self._do_switch)]
        if self.store is not None:
            actions.insert(0, ("key", "PIN'i değiştir", self._change_pin))
        for icon_name, tip, handler in actions:
            btn = QPushButton()
            btn.setObjectName("iconBtn")
            btn.setFixedSize(44, 44)
            btn.setToolTip(tip)
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            icon = make_icon(icon_name, "#B9C8BF", 18)
            if icon.isNull():
                btn.setText(tip[:1])
            else:
                btn.setIcon(icon)
                btn.setIconSize(QSize(18, 18))
            btn.clicked.connect(handler)
            row.addWidget(btn, 0, Qt.AlignmentFlag.AlignVCenter)
        return header

    def go_to(self, index: int):
        self.stack.setCurrentIndex(index)
        nav_index = self.NAV_OF_PAGE.get(index, index)
        if 0 <= nav_index < len(self.nav_buttons):
            self.nav_buttons[nav_index].setChecked(True)
        if 0 <= index < len(self.META):
            self.page_title.setText(self.META[index][0])
            self.page_sub.setText(self.META[index][1])
        self.on_page(index)

    def _refreshable_page(self):
        inner = QWidget()
        box = QVBoxLayout(inner)
        box.setContentsMargins(0, 0, 0, 0)
        box.setSpacing(16)
        return self._scroll(inner), box

    def _tick_clock(self):
        now = datetime.now()
        self.date_label.setText(f"{DAYS_TR[now.weekday()]}, {now.day} {TURKISH_MONTHS[now.month]} {now.year}")
        self.time_label.setText(now.strftime("%H:%M:%S"))

    def _confirm(self, text: str, title: str = "Onay") -> bool:
        answer = QMessageBox.question(self, title, text,
                                      QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                                      QMessageBox.StandardButton.No)
        return answer == QMessageBox.StandardButton.Yes

    # --- kilit / çıkış --------------------------------------------------------------------
    def _do_lock(self):
        self.lock_requested.emit()

    def _do_switch(self):
        self.switch_requested.emit()

    def _change_pin(self):
        dlg = PinSetupDialog(f"{self.TITLE} — yeni PIN", self)
        if dlg.exec():
            self.store.change_pin(dlg.pin())
            QMessageBox.information(self, "PIN değişti", "Yeni PIN kaydedildi. Kurtarma kodun aynı kalır.")

    def eventFilter(self, obj, event):
        if event.type() in (QEvent.Type.MouseButtonPress, QEvent.Type.KeyPress, QEvent.Type.MouseMove):
            self._last_activity = time.time()
        return False

    def _check_idle(self):
        if QApplication.activeModalWidget() is not None:
            return
        if time.time() - self._last_activity > self.IDLE_LOCK_SECONDS:
            self._do_lock()

    def closeEvent(self, event):
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        self.idle_timer.stop()
        self.clock_timer.stop()
        if self.store is not None:
            self.store.lock()
        event.accept()


