class MenuDialog(BaseDialog):
    def __init__(self, day_iso: str, rec: dict = None, parent=None):
        d = parse_iso(day_iso) or date.today()
        super().__init__(f"{d.day} {TURKISH_MONTHS[d.month]} — günlük menü", parent, width=580)
        rec = rec or {}
        self.kind = SegmentedChoice(MEAL_KINDS, rec.get("kind", "Antrenman günü"))
        self.add_field("Gün türü", self.kind)
        self.edits = {}
        slots = rec.get("slots") or {}
        for key, label in MEAL_SLOTS:
            edit = QLineEdit(slots.get(key, ""))
            self.edits[key] = edit
            self.add_field(label, edit)
        fill = QPushButton("Şablonu doldur")
        fill.setObjectName("outlineSmall")
        fill.setFixedHeight(32)
        fill.setToolTip("Seçili gün türünün örnek menüsünü boş alanlara yazar")
        fill.clicked.connect(self._fill_template)
        self.form.addWidget(fill, 0, Qt.AlignmentFlag.AlignLeft)
        self.note = QLineEdit(rec.get("note", ""))
        self.note.setPlaceholderText("İsteğe bağlı (ör. maçtan 3 saat önce yemek)")
        self.add_field("Not", self.note)

    def _fill_template(self):
        tmpl = MEAL_TEMPLATES.get(self.kind.value(), {})
        for key, edit in self.edits.items():
            if not edit.text().strip():
                edit.setText(tmpl.get(key, ""))

    def values(self) -> dict:
        return {"kind": self.kind.value(), "slots": {k: e.text().strip() for k, e in self.edits.items()},
                "note": self.note.text().strip()}


class DietWindow(DeptWindow):
    KEY = "diyetisyen"
    TITLE = "Diyetisyen"
    LABEL = "DİYET"
    NAV = [("panel", "Panel"), ("activity", "Ölçümler"), ("board", "Planlar"),
           ("calendar", "Menü"), ("heart", "Alerji")]
    META = [
        ("Diyetisyen Paneli", "Takip, uyarılar ve bugünün menüsü"),
        ("Vücut ölçümleri", "Kilo, yağ oranı ve kas kütlesi trendi"),
        ("Beslenme planları", "Oyuncu bazında hedef, kalori ve makrolar"),
        ("Haftalık menü", "Antrenman, maç ve dinlenme günü menüleri"),
        ("Alerji ve takviyeler", "Kısıtlar, intoleranslar ve kullanılan takviyeler"),
    ]

    def init_state(self):
        self.d = self.store.data
        for key, default in (("body", {}), ("plans", {}), ("allergies", {}), ("supplements", {}), ("menus", {})):
            self.d.setdefault(key, default)
        self.sel_pid = ROSTER[0]["id"] if ROSTER else ""
        self.week_offset = 0

    def commit(self):
        self.store.save()
        self.on_page(self.stack.currentIndex())

    def build_pages(self) -> list:
        pages = []
        for name in ("panel_box", "body_box", "plan_box", "menu_box", "allergy_box"):
            page, box = self._refreshable_page()
            setattr(self, name, box)
            pages.append(page)
        return pages

    def on_page(self, index: int):
        (self._refresh_panel, self._refresh_body, self._refresh_plans, self._refresh_menu,
         self._refresh_allergy)[index]()

    # --- yardımcılar -----------------------------------------------------------------------
    def _records(self, pid: str) -> list:
        return sorted(self.d["body"].get(pid, []), key=lambda r: r.get("date", ""))

    def _last_record(self, pid: str):
        recs = self._records(pid)
        return recs[-1] if recs else None

    def _availability(self) -> dict:
        try:
            return self.shared.load()["availability"] if self.shared is not None else {}
        except Exception:
            return {}

    def _player_combo(self, on_change):
        combo = make_player_combo(self.sel_pid)
        combo.setMinimumWidth(280)
        combo.currentIndexChanged.connect(lambda _=0, c=combo: on_change(c.currentData()))
        return combo

    # --- Panel -----------------------------------------------------------------------------
    def _refresh_panel(self):
        clear_layout(self.panel_box)
        total = len(ROSTER)
        planned = sum(1 for p in ROSTER if self.d["plans"].get(p["id"]))
        today = date.today()
        week_ago = (today - timedelta(days=7)).isoformat()
        measured = sum(1 for p in ROSTER if (self._last_record(p["id"]) or {}).get("date", "") >= week_ago)
        flagged = sum(1 for p in ROSTER if any(self.d["allergies"].get(p["id"], {}).get(k) for k in ("allergy", "intol")))
        stale = [p for p in ROSTER if self._last_record(p["id"]) is None
                 or (parse_iso(self._last_record(p["id"])["date"]) or today) < today - timedelta(days=14)]

        kp = QHBoxLayout()
        kp.setSpacing(16)
        kp.addWidget(self._stat_card("Planı olan", str(planned), self.acc["hi"], f"/ {total}"))
        kp.addWidget(self._stat_card("Bu hafta ölçülen", str(measured), "#7FB2FF", f"/ {total}"))
        kp.addWidget(self._stat_card("Alerji / intolerans", str(flagged), "#F2B24A", "oyuncu"))
        kp.addWidget(self._stat_card("Ölçüm bekleyen", str(len(stale)), "#FF7B7F", "14+ gün"))
        self.panel_box.addLayout(kp)

        main = QHBoxLayout()
        main.setSpacing(20)

        mcard, ml = self._card()
        head = QHBoxLayout()
        head.addWidget(self._section_label("Bugünün menüsü"))
        head.addStretch(1)
        edit = self._button("Düzenle", "outlineSmall", 32, "plus")
        edit.clicked.connect(lambda: self._edit_menu(today.isoformat()))
        head.addWidget(edit)
        ml.addLayout(head)
        menu = self.d["menus"].get(today.isoformat())
        if not menu:
            ml.addWidget(self._text("Bugün için menü girilmemiş. Düzenle'ye basıp şablondan başlayabilirsin."))
        else:
            fg, bg = MEAL_KIND_COLORS.get(menu.get("kind"), (K_MUTED, "#1B2A22"))
            chips = QHBoxLayout()
            chips.addWidget(make_chip(menu.get("kind", ""), fg, bg))
            chips.addStretch(1)
            ml.addLayout(chips)
            for key, label in MEAL_SLOTS:
                text = (menu.get("slots") or {}).get(key, "")
                if not text:
                    continue
                row = QFrame()
                row.setObjectName("rowLine")
                h = QHBoxLayout(row)
                h.setContentsMargins(0, 10, 0, 10)
                h.setSpacing(14)
                lab = QLabel(label)
                lab.setObjectName("dateSub")
                lab.setFixedWidth(130)
                h.addWidget(lab)
                val = QLabel(text)
                val.setObjectName("cellText")
                val.setWordWrap(True)
                h.addWidget(val, 1)
                ml.addWidget(row)
            if menu.get("note"):
                ml.addWidget(self._text(menu["note"], "dateSub"))
        ml.addStretch(1)
        main.addWidget(mcard, 1)

        side_w = QWidget()
        side_w.setFixedWidth(360)
        side = QVBoxLayout(side_w)
        side.setContentsMargins(0, 0, 0, 0)
        side.setSpacing(16)

        acard, al = self._card(spacing=10)
        al.addWidget(self._section_label("Sağlık biriminden gelen durum"))
        avail = self._availability()
        attention = [(p, avail.get(p["id"], {})) for p in ROSTER
                     if avail.get(p["id"], {}).get("status", "Hazır") != "Hazır"]
        if not attention:
            al.addWidget(self._text("Şu an sakat, kısıtlı ya da rehabilitasyondaki oyuncu yok."))
        for p, a in attention[:6]:
            row = QHBoxLayout()
            row.addWidget(two_line(p["name"], "Kalori ve protein planını gözden geçir"), 1)
            row.addWidget(status_chip(a.get("status", "")))
            al.addLayout(row)
        side.addWidget(acard)

        scard, sl = self._card(spacing=10)
        sl.addWidget(self._section_label("Ölçüm bekleyenler"))
        if not stale:
            sl.addWidget(self._text("Herkesin son 14 günde ölçümü var."))
        for p in stale[:6]:
            last = self._last_record(p["id"])
            row = QHBoxLayout()
            row.addWidget(two_line(p["name"], f"Son ölçüm: {short_date(last['date'])}" if last else "Hiç ölçüm yok"), 1)
            btn = self._button("Ölç", "outlineSmall", 30)
            btn.clicked.connect(lambda _=False, pid=p["id"]: self._add_body(pid))
            row.addWidget(btn)
            sl.addLayout(row)
        side.addWidget(scard)
        side.addStretch(1)
        main.addWidget(side_w)
        self.panel_box.addLayout(main, 1)

    # --- Ölçümler --------------------------------------------------------------------------
    def _set_pid(self, pid):
        if pid:
            self.sel_pid = pid
            self._refresh_body()

    def _refresh_body(self):
        clear_layout(self.body_box)
        top = QHBoxLayout()
        top.setSpacing(12)
        top.addWidget(self._player_combo(self._set_pid))
        top.addStretch(1)
        add = self._button("Ölçüm ekle", "aiBtn", 38, "plus", self.acc["on"])
        add.clicked.connect(lambda: self._add_body(self.sel_pid))
        top.addWidget(add)
        self.body_box.addLayout(top)

        recs = self._records(self.sel_pid)
        last = recs[-1] if recs else None
        first = recs[0] if recs else None
        kp = QHBoxLayout()
        kp.setSpacing(16)
        delta = (last["weight"] - first["weight"]) if last and first and last is not first else None
        kp.addWidget(self._stat_card("Son kilo", _fmt_num(last["weight"]) if last else "—", self.acc["hi"], "kg"))
        kp.addWidget(self._stat_card("Başlangıca göre", ("%+.1f" % delta) if delta is not None else "—", "#F2B24A", "kg"))
        kp.addWidget(self._stat_card("Yağ oranı", _fmt_num(last.get("fat")) if last else "—", "#FF7B7F", "%"))
        kp.addWidget(self._stat_card("Kas kütlesi", _fmt_num(last.get("muscle")) if last else "—", "#7FB2FF", "kg"))
        self.body_box.addLayout(kp)

        card, lay = self._card()
        head = QHBoxLayout()
        head.addWidget(self._section_label("Kilo trendi"))
        head.addStretch(1)
        self._metric = getattr(self, "_metric", "weight")
        seg = SegmentedChoice(["Kilo", "Yağ %", "Kas kg"],
                              {"weight": "Kilo", "fat": "Yağ %", "muscle": "Kas kg"}[self._metric])
        for label, btn in seg.buttons.items():
            btn.clicked.connect(lambda _=False, l=label: self._set_metric(l))
        head.addWidget(seg)
        lay.addLayout(head)
        key, unit = {"weight": ("weight", " kg"), "fat": ("fat", " %"), "muscle": ("muscle", " kg")}[self._metric]
        chart = TrendChart(self.acc["hi"])
        chart.set_data([(short_date(r["date"]), r[key]) for r in recs if r.get(key)], unit)
        lay.addWidget(chart)
        self.body_box.addWidget(card)

        tcard, tl = self._card()
        tl.addWidget(self._section_label("Ölçüm geçmişi"))
        rows = []
        prev = None
        for r in recs:
            change = "" if prev is None else "%+.1f kg" % (r["weight"] - prev["weight"])
            rows.append(([long_date(r["date"]), f"{_fmt_num(r['weight'])} kg", change or "—",
                          f"%{_fmt_num(r.get('fat'))}" if r.get("fat") else "—",
                          f"{_fmt_num(r.get('muscle'))} kg" if r.get("muscle") else "—", r.get("note", "")], r["id"]))
            prev = r
        rows.reverse()
        tl.addWidget(build_table([("Tarih", 150), ("Kilo", 90), ("Değişim", 90), ("Yağ", 80), ("Kas", 90), ("Not", 0)],
                                 rows, self._edit_body, 46,
                                 "Bu oyuncu için henüz ölçüm yok. Sağ üstten ölçüm ekle."))
        self.body_box.addWidget(tcard)
        self.body_box.addStretch(1)

    def _set_metric(self, label: str):
        self._metric = {"Kilo": "weight", "Yağ %": "fat", "Kas kg": "muscle"}[label]
        self._refresh_body()

    def _add_body(self, pid):
        if not pid:
            return
        self.sel_pid = pid
        dlg = BodyDialog(player_label(pid), None, self._last_record(pid), self)
        if dlg.exec():
            self.d["body"].setdefault(pid, []).append(dlg.values())
            self.commit()

    def _edit_body(self, rec_id: str):
        recs = self.d["body"].get(self.sel_pid, [])
        rec = next((r for r in recs if r["id"] == rec_id), None)
        if rec is None:
            return
        dlg = BodyDialog(player_label(self.sel_pid), rec, None, self)
        dlg.cancel_btn.setText("Vazgeç")
        delete = QPushButton("Sil")
        delete.setObjectName("dangerBtn")
        delete.setFixedHeight(38)

        def do_delete():
            if self._confirm("Bu ölçüm silinsin mi?", "Ölçümü sil"):
                recs.remove(rec)
                dlg.reject()
                self.commit()
        delete.clicked.connect(do_delete)
        dlg.root.itemAt(dlg.root.count() - 1).layout().insertWidget(0, delete)
        if dlg.exec():
            rec.update(dlg.values())
            self.commit()

    # --- Planlar ---------------------------------------------------------------------------
    def _refresh_plans(self):
        clear_layout(self.plan_box)
        self.plan_box.addWidget(self._text(
            "Satıra tıklayıp oyuncunun hedefini, kalori ve makrolarını düzenle. Çubuk protein (mavi), "
            "karbonhidrat (sarı) ve yağ (kırmızı) dağılımını gösterir.", "noteText"))
        card, lay = self._card()
        rows = []
        for p in ROSTER:
            plan = self.d["plans"].get(p["id"])
            sub = p["pos"] + (f" · {p['no']}" if p["no"] else "")
            if plan:
                bar = MacroBar(plan.get("protein", 0), plan.get("carb", 0), plan.get("fat", 0))
                macros = f"P {plan.get('protein', 0)} · K {plan.get('carb', 0)} · Y {plan.get('fat', 0)} g"
                cells = [two_line(p["name"], sub), goal_chip(plan.get("goal", "")),
                         f"{plan.get('kcal', 0)} kcal", macros, bar,
                         f"{_fmt_num(plan.get('water'))} L"]
            else:
                cells = [two_line(p["name"], sub), make_chip("Plan yok", K_MUTED, "#1B2A22"), "—", "—", QLabel(""), "—"]
            rows.append((cells, p["id"]))
        lay.addWidget(build_table([("Oyuncu", 0), ("Hedef", 130), ("Kalori", 100), ("Makrolar", 210),
                                   ("Dağılım", 150), ("Su", 70)], rows, self._edit_plan, 58))
        self.plan_box.addWidget(card)
        self.plan_box.addStretch(1)

    def _edit_plan(self, pid: str):
        plan = self.d["plans"].get(pid)
        dlg = DietPlanDialog(player_label(pid), plan, self)
        if plan:
            remove = QPushButton("Planı sil")
            remove.setObjectName("dangerBtn")
            remove.setFixedHeight(38)

            def do_remove():
                if self._confirm("Bu oyuncunun planı silinsin mi?", "Planı sil"):
                    self.d["plans"].pop(pid, None)
                    dlg.reject()
                    self.commit()
            remove.clicked.connect(do_remove)
            dlg.root.itemAt(dlg.root.count() - 1).layout().insertWidget(0, remove)
        if dlg.exec():
            self.d["plans"][pid] = dlg.values()
            self.commit()

    # --- Menü ------------------------------------------------------------------------------
    def _week_start(self) -> date:
        today = date.today()
        return today - timedelta(days=today.weekday()) + timedelta(weeks=self.week_offset)

    def _refresh_menu(self):
        clear_layout(self.menu_box)
        start = self._week_start()
        end = start + timedelta(days=6)
        nav = QHBoxLayout()
        nav.setSpacing(10)
        prev_btn = self._button("‹ Önceki hafta", "outlineSmall", 34)
        prev_btn.clicked.connect(lambda: self._shift_week(-1))
        next_btn = self._button("Sonraki hafta ›", "outlineSmall", 34)
        next_btn.clicked.connect(lambda: self._shift_week(1))
        today_btn = self._button("Bu hafta", "outlineSmall", 34)
        today_btn.clicked.connect(lambda: self._shift_week(0, reset=True))
        title = QLabel(f"{start.day} {TURKISH_MONTHS[start.month]} – {end.day} {TURKISH_MONTHS[end.month]} {end.year}")
        title.setObjectName("bigName")
        nav.addWidget(prev_btn)
        nav.addWidget(today_btn)
        nav.addWidget(next_btn)
        nav.addSpacing(10)
        nav.addWidget(title)
        nav.addStretch(1)
        self.menu_box.addLayout(nav)

        grid = QGridLayout()
        grid.setHorizontalSpacing(14)
        grid.setVerticalSpacing(14)
        today = date.today()
        for i in range(7):
            day = start + timedelta(days=i)
            iso = day.isoformat()
            menu = self.d["menus"].get(iso)
            card, lay = self._card(clickable=True, spacing=8)
            card.clicked.connect(lambda iso=iso: self._edit_menu(iso))
            head = QHBoxLayout()
            name = QLabel(f"{DAYS_TR[day.weekday()]} · {day.day}")
            name.setObjectName("fxOpp")
            if day == today:
                name.setStyleSheet(f"color: {self.acc['hi']};")
            head.addWidget(name)
            head.addStretch(1)
            if menu:
                fg, bg = MEAL_KIND_COLORS.get(menu.get("kind"), (K_MUTED, "#1B2A22"))
                head.addWidget(make_chip(menu.get("kind", "").replace(" günü", ""), fg, bg))
            lay.addLayout(head)
            if not menu:
                lay.addWidget(self._text("Menü yok. Eklemek için tıkla.", "dateSub"))
            else:
                for key, label in MEAL_SLOTS:
                    text = (menu.get("slots") or {}).get(key, "")
                    if text:
                        lay.addWidget(self._meal_line(label, text))
            lay.addStretch(1)
            grid.addWidget(card, i // 4, i % 4)
        for c in range(4):
            grid.setColumnStretch(c, 1)
        self.menu_box.addLayout(grid)
        self.menu_box.addStretch(1)

    def _meal_line(self, label: str, text: str) -> QWidget:
        box = QWidget()
        col = QVBoxLayout(box)
        col.setContentsMargins(0, 0, 0, 0)
        col.setSpacing(0)
        lab = QLabel(label)
        lab.setObjectName("dateSub")
        val = QLabel(text)
        val.setObjectName("cellText")
        val.setWordWrap(True)
        col.addWidget(lab)
        col.addWidget(val)
        return box

    def _shift_week(self, step: int, reset: bool = False):
        self.week_offset = 0 if reset else self.week_offset + step
        self._refresh_menu()

    def _edit_menu(self, iso: str):
        existing = self.d["menus"].get(iso)
        dlg = MenuDialog(iso, existing, self)
        if existing:
            remove = QPushButton("Menüyü sil")
            remove.setObjectName("dangerBtn")
            remove.setFixedHeight(38)

            def do_remove():
                if self._confirm("Bu günün menüsü silinsin mi?", "Menüyü sil"):
                    self.d["menus"].pop(iso, None)
                    dlg.reject()
                    self.commit()
            remove.clicked.connect(do_remove)
            dlg.root.itemAt(dlg.root.count() - 1).layout().insertWidget(0, remove)
        if dlg.exec():
            self.d["menus"][iso] = dlg.values()
            self.commit()

    # --- Alerji ve takviyeler --------------------------------------------------------------
    def _refresh_allergy(self):
        clear_layout(self.allergy_box)
        self.allergy_box.addWidget(self._text(
            "Alerji ve intolerans bilgisi yemek hazırlayan ekiple paylaşılmaz; yalnızca bu ekranda görünür. "
            "Satıra tıklayıp düzenle.", "noteText"))
        cols = QHBoxLayout()
        cols.setSpacing(20)

        acard, al = self._card()
        al.addWidget(self._section_label("Alerji ve kısıtlar"))
        rows = []
        for p in ROSTER:
            rec = self.d["allergies"].get(p["id"], {})
            sub = p["pos"] + (f" · {p['no']}" if p["no"] else "")
            allergy = rec.get("allergy", "")
            chip = make_chip(allergy, "#FF7B7F", "#2E1719") if allergy else QLabel("—")
            rows.append(([two_line(p["name"], sub), chip, rec.get("intol", "") or "—"], p["id"]))
        al.addWidget(build_table([("Oyuncu", 0), ("Alerji", 170), ("İntolerans", 130)], rows, self._edit_allergy, 54))
        cols.addWidget(acard, 1)

        scard, sl = self._card()
        head = QHBoxLayout()
        head.addWidget(self._section_label("Takviyeler"))
        head.addStretch(1)
        add = self._button("Takviye ekle", "outlineSmall", 32, "plus")
        add.clicked.connect(self._add_supplement)
        head.addWidget(add)
        sl.addLayout(head)
        sl.addWidget(self._player_combo(self._set_pid_supp))
        items = self.d["supplements"].get(self.sel_pid, [])
        if not items:
            sl.addWidget(self._text("Bu oyuncu için takviye kaydı yok."))
        for it in items:
            row = ClickableFrame()
            row.setObjectName("rowLine")
            row.setProperty("clickable", True)
            row.setCursor(Qt.CursorShape.PointingHandCursor)
            row.clicked.connect(lambda iid=it["id"]: self._edit_supplement(iid))
            h = QHBoxLayout(row)
            h.setContentsMargins(0, 10, 0, 10)
            h.addWidget(two_line(it["name"], " · ".join(x for x in (it.get("dose"), it.get("timing")) if x)), 1)
            sl.addWidget(row)
        sl.addStretch(1)
        cols.addWidget(scard, 1)
        self.allergy_box.addLayout(cols, 1)

    def _set_pid_supp(self, pid):
        if pid:
            self.sel_pid = pid
            self._refresh_allergy()

    def _edit_allergy(self, pid: str):
        dlg = AllergyDialog(player_label(pid), self.d["allergies"].get(pid), self)
        if dlg.exec():
            vals = dlg.values()
            if any(vals.values()):
                self.d["allergies"][pid] = vals
            else:
                self.d["allergies"].pop(pid, None)
            self.commit()

    def _add_supplement(self):
        if not self.sel_pid:
            return
        dlg = SupplementDialog(player_label(self.sel_pid), None, self)
        if dlg.exec():
            self.d["supplements"].setdefault(self.sel_pid, []).append(dlg.values())
            self.commit()

    def _edit_supplement(self, item_id: str):
        items = self.d["supplements"].get(self.sel_pid, [])
        item = next((i for i in items if i["id"] == item_id), None)
        if item is None:
            return
        dlg = SupplementDialog(player_label(self.sel_pid), item, self)
        remove = QPushButton("Sil")
        remove.setObjectName("dangerBtn")
        remove.setFixedHeight(38)

        def do_remove():
            if self._confirm("Bu takviye silinsin mi?", "Takviyeyi sil"):
                items.remove(item)
                dlg.reject()
                self.commit()
        remove.clicked.connect(do_remove)
        dlg.root.itemAt(dlg.root.count() - 1).layout().insertWidget(0, remove)
        if dlg.exec():
            item.update(dlg.values())
            self.commit()


# ==========================================================================================
# FUTBOLCU (kişisel görünüm — yalnızca paylaşılan asgari bilgiyi okur)
# ==========================================================================================

class PlayerWindow(DeptWindow):
    KEY = "futbolcu"
    TITLE = "Futbolcu"
    LABEL = "FUTBOLCU"
    NAV = [("home", "Bugün"), ("calendar", "Program"), ("trophy", "Takvim"), ("heart", "Günlük"),
           ("cross", "Sağlık"), ("board", "Geri bildirim"), ("megaphone", "Duyuru")]
    CHIP_TEXT = "Kişisel görünüm"
    META = [
        ("Bugün", ""),
        ("Programım", "Antrenmanlar, maçlar ve seyahat"),
        ("Takvim", "Maçlar ve doğum günleri"),
        ("Günlük kontrol", "Bugün nasıl hissediyorsun?"),
        ("Sağlık özetim", "Yalnızca sana ait özet bilgi"),
        ("Geri bildirim", "Teknik kadronun seninle paylaştığı notlar"),
        ("Duyurular", "Kulüpten gelen duyurular"),
    ]

    def init_state(self):
        self.data = {}
        self.pw_choices = {}

    def build_pages(self) -> list:
        pages = []
        for name in ("today_box", "plan_box", "cal_box", "well_box", "health_box", "feedback_box", "news_box"):
            page, box = self._refreshable_page()
            setattr(self, name, box)
            pages.append(page)
        return pages

    def on_page(self, index: int):
        self.data = self.shared.load() if self.shared is not None else {}
        if index == 0:
            self.page_title.setText(f"Merhaba, {self.player['name'].split()[0]}")
            self.page_sub.setText(f"{self.player['pos']}" + (f" · {self.player['no']}" if self.player['no'] else ""))
        (self._refresh_today, self._refresh_plan, self._refresh_calendar, self._refresh_wellness,
         self._refresh_health, self._refresh_feedback, self._refresh_news)[index]()

    def my_status(self) -> dict:
        return self.data.get("availability", {}).get(self.player["id"], {"status": "Hazır", "return": "", "player_note": ""})

    def _status_card(self) -> QFrame:
        st = self.my_status()
        card, lay = self._card(margins=(22, 22, 22, 22), spacing=12)
        lay.addWidget(self._section_label("Sağlık durumum"))
        row = QHBoxLayout()
        row.addWidget(status_chip(st.get("status", "Hazır")))
        row.addStretch(1)
        lay.addLayout(row)
        if st.get("return"):
            d = days_until(st["return"])
            lay.addWidget(two_line("Tahmini dönüş", f"{long_date(st['return'])}" +
                                   (f" · {d} gün" if d is not None and d > 0 else ""), "fxOpp"))
        if st.get("player_note"):
            lay.addWidget(self._text(st["player_note"], "cellText"))
        elif st.get("status", "Hazır") == "Hazır":
            lay.addWidget(self._text("Sahaya hazırsın.", "dateSub"))
        return card

    def _training_rows(self, limit: int):
        today_iso = date.today().isoformat()
        items = sorted([t for t in self.data.get("training", []) if t.get("date", "") >= today_iso],
                       key=lambda t: (t["date"], t.get("time", "")))
        return items[:limit]

    def _my_wellness_today(self) -> dict:
        return self.data.get("wellness", {}).get(date.today().isoformat(), {}).get(self.player["id"], {})

    def _refresh_today(self):
        clear_layout(self.today_box)
        main = QHBoxLayout()
        main.setSpacing(20)
        left = QVBoxLayout()
        left.setSpacing(16)
        left.addWidget(self._status_card())

        if not self._my_wellness_today():
            wcard, wl = self._card(spacing=10)
            wl.addWidget(self._section_label("Günlük kontrol"))
            wl.addWidget(self._text("Bugünkü formunu henüz paylaşmadın. Birkaç saniye sürer.", "cellText"))
            go = self._button("Şimdi doldur", "aiBtn", 38, "", self.acc["on"])
            go.clicked.connect(lambda: self.go_to(3))
            wl.addWidget(go, 0, Qt.AlignmentFlag.AlignLeft)
            left.addWidget(wcard)

        tcard, tl = self._card(spacing=8)
        tl.addWidget(self._section_label("Bugünün antrenmanı"))
        today_iso = date.today().isoformat()
        todays = [t for t in self.data.get("training", []) if t.get("date") == today_iso]
        if not todays:
            tl.addWidget(self._text("Bugün için paylaşılmış antrenman yok."))
        for t in sorted(todays, key=lambda t: t.get("time", "")):
            row = QFrame()
            row.setObjectName("rowLine")
            h = QHBoxLayout(row)
            h.setContentsMargins(0, 10, 0, 10)
            h.setSpacing(14)
            tm = QLabel(t.get("time", ""))
            tm.setObjectName("mono")
            tm.setFixedWidth(44)
            h.addWidget(tm)
            h.addWidget(two_line(t["title"], t.get("note", "").splitlines()[0] if t.get("note") else "", "fxOpp"), 1)
            tl.addWidget(row)
        left.addWidget(tcard)
        left.addStretch(1)
        main.addLayout(left, 1)

        right_w = QWidget()
        right_w.setFixedWidth(360)
        right = QVBoxLayout(right_w)
        right.setContentsMargins(0, 0, 0, 0)
        right.setSpacing(16)
        ncard, nl = self._card(spacing=10)
        nl.addWidget(self._section_label("Sıradaki maç"))
        nm = get_next_fixture()
        if nm is None:
            nl.addWidget(self._text("Yaklaşan maç bulunamadı."))
        else:
            nl.addWidget(two_line(nm["opponent"], f"{nm['date'].day} {TURKISH_MONTHS[nm['date'].month]} · {nm['time']} · "
                                  f"{'İç saha' if nm['home'] else 'Deplasman'}", "bigName"))
            cd = QLabel(countdown_text((nm["date"] - date.today()).days))
            cd.setObjectName("countdown")
            nl.addWidget(cd)
        right.addWidget(ncard)

        acard, al = self._card(spacing=8)
        al.addWidget(self._section_label("Son duyuru"))
        news = sorted(self.data.get("announcements", []), key=lambda a: a.get("ts", ""), reverse=True)
        if not news:
            al.addWidget(self._text("Duyuru yok."))
        else:
            al.addWidget(two_line(news[0].get("title", ""), format_dt(news[0].get("ts", "")), "fxOpp"))
            if news[0].get("text"):
                al.addWidget(self._text(news[0]["text"], "cellText"))
        right.addWidget(acard)
        right.addStretch(1)
        main.addWidget(right_w)
        self.today_box.addLayout(main, 1)

    def _refresh_plan(self):
        clear_layout(self.plan_box)
        cols = QHBoxLayout()
        cols.setSpacing(20)
        tcard, tl = self._card()
        tl.addWidget(self._section_label("Antrenmanlar"))
        rows = [([short_date(t["date"]), t.get("time", ""), two_line(t["title"], (t.get("note", "").splitlines() or [""])[0])], t["id"])
                for t in self._training_rows(12)]
        tl.addWidget(build_table([("Tarih", 80), ("Saat", 60), ("Antrenman", 0)], rows, None, 54,
                                 "Paylaşılmış antrenman yok."))
        cols.addWidget(tcard, 1)

        side_w = QWidget()
        side_w.setFixedWidth(380)
        side = QVBoxLayout(side_w)
        side.setContentsMargins(0, 0, 0, 0)
        side.setSpacing(16)
        mcard, ml = self._card()
        ml.addWidget(self._section_label("Maçlar"))
        mrows = [([short_date(fx["date"].isoformat()), fx["opponent"],
                   make_chip("İç saha", K_GREEN_HI, K_GREEN_BG) if fx["home"] else make_chip("Deplasman", K_AMBER, K_AMBER_BG)],
                  fixture_key(fx)) for fx in get_upcoming_fixtures()[:5]]
        ml.addWidget(build_table([("Tarih", 70), ("Rakip", 0), ("", 110)], mrows, None, 48, "Yaklaşan maç yok."))
        side.addWidget(mcard)

        vcard, vl = self._card()
        vl.addWidget(self._section_label("Seyahat"))
        trips = sorted([t for t in self.data.get("travel", []) if (days_until(t.get("date", "")) or -1) >= 0],
                       key=lambda t: t["date"])[:4]
        vrows = [([short_date(t["date"]), two_line(t["dest"], (t.get("note", "").splitlines() or [""])[0])], t["id"]) for t in trips]
        vl.addWidget(build_table([("Tarih", 70), ("Yer", 0)], vrows, None, 54, "Paylaşılmış seyahat planı yok."))
        side.addWidget(vcard)
        side.addStretch(1)
        cols.addWidget(side_w)
        self.plan_box.addLayout(cols, 1)

    def _refresh_calendar(self):
        clear_layout(self.cal_box)
        cols = QHBoxLayout()
        cols.setSpacing(20)
        fcard, fl = self._card()
        fl.addWidget(self._section_label("Yaklaşan maçlar"))
        frows = [([short_date(fx["date"].isoformat()), two_line(fx["opponent"], fx["time"]),
                   make_chip("İç saha", K_GREEN_HI, K_GREEN_BG) if fx["home"] else make_chip("Deplasman", K_AMBER, K_AMBER_BG)],
                  fixture_key(fx)) for fx in get_upcoming_fixtures()[:10]]
        fl.addWidget(build_table([("Tarih", 80), ("Rakip", 0), ("", 110)], frows, None, 54, "Yaklaşan maç yok."))
        cols.addWidget(fcard, 1)

        bcard, bl = self._card()
        bl.addWidget(self._section_label("Yaklaşan doğum günleri"))
        brows = []
        for b in get_birthday_list()[:8]:
            when = "Bugün" if b["days_left"] == 0 else f"{b['days_left']} gün"
            brows.append(([b["name"], f"{b['date'].day} {TURKISH_MONTHS[b['date'].month]}",
                           make_chip(when, self.acc["hi"], self.acc["bg"])], b["name"]))
        bl.addWidget(build_table([("Oyuncu", 0), ("Tarih", 110), ("", 100)], brows, None, 48, "Kayıt yok."))
        cols.addWidget(bcard, 1)
        self.cal_box.addLayout(cols, 1)

    def _refresh_wellness(self):
        clear_layout(self.well_box)
        mine = self._my_wellness_today()
        card, lay = self._card(margins=(26, 24, 26, 24), spacing=16)
        lay.addWidget(self._section_label("Bugün nasıl hissediyorsun?"))
        lay.addWidget(self._text("1 = çok kötü, 5 = çok iyi. Yanıtların yalnızca sağlık birimine iletilir; "
                                 "istediğin zaman güncelleyebilirsin.", "dateSub"))
        self.pw_choices = {}
        for key, label in WellnessDialog.FIELDS:
            row = QHBoxLayout()
            row.setSpacing(16)
            lab = QLabel(label)
            lab.setObjectName("rowTitle")
            lab.setFixedWidth(130)
            row.addWidget(lab)
            choice = SegmentedChoice([1, 2, 3, 4, 5], mine.get(key, 3))
            self.pw_choices[key] = choice
            row.addWidget(choice, 1)
            lay.addLayout(row)
        self.pw_note = QLineEdit(mine.get("note", ""))
        self.pw_note.setPlaceholderText("Eklemek istediğin bir şey var mı? (ör. dizde hafif ağrı)")
        lay.addWidget(self.pw_note)
        send = self._button("Güncelle" if mine else "Gönder", "aiBtn", 40, "", self.acc["on"])
        send.clicked.connect(self._submit_wellness)
        lay.addWidget(send, 0, Qt.AlignmentFlag.AlignLeft)
        self.well_box.addWidget(card)

        hist, hl = self._card(spacing=6)
        hl.addWidget(self._section_label("Son günler"))
        pid = self.player["id"]
        days = sorted(self.data.get("wellness", {}).items(), reverse=True)
        rows = []
        for day_iso, entries in days:
            if pid in entries:
                rows.append(([long_date(day_iso), score_chip(wellness_avg(entries[pid])),
                              entries[pid].get("note", "") or "—"], day_iso))
        hl.addWidget(build_table([("Tarih", 150), ("Ortalama", 90), ("Not", 0)], rows[:7], None, 46, "Henüz bildirim yok."))
        self.well_box.addWidget(hist)
        self.well_box.addStretch(1)

    def _submit_wellness(self):
        rec = {key: choice.value() for key, choice in self.pw_choices.items()}
        rec["note"] = self.pw_note.text().strip()
        rec["ts"] = datetime.now().isoformat(timespec="seconds")
        pid = self.player["id"]
        today_iso = date.today().isoformat()
        cutoff = (date.today() - timedelta(days=60)).isoformat()

        def apply(s):
            s["wellness"].setdefault(today_iso, {})[pid] = rec
            for day in [k for k in s["wellness"] if k < cutoff]:
                del s["wellness"][day]

        if self.shared is not None:
            self.shared.update(apply)
        QMessageBox.information(self, "Teşekkürler", "Bugünkü günlük kontrolün sağlık birimine iletildi.")
        self.on_page(3)

    def _refresh_health(self):
        clear_layout(self.health_box)
        self.health_box.addWidget(self._status_card())
        acard, al = self._card()
        al.addWidget(self._section_label("Randevularım"))
        appts = sorted(self.data.get("appointments", {}).get(self.player["id"], []),
                       key=lambda a: (a.get("date", ""), a.get("time", "")))
        rows = [([short_date(a.get("date", "")), a.get("time", ""), a.get("kind", "")], i) for i, a in enumerate(appts)]
        al.addWidget(build_table([("Tarih", 90), ("Saat", 64), ("Tür", 0)], rows, None, 48, "Yaklaşan randevun yok."))
        self.health_box.addWidget(acard)
        self.health_box.addWidget(self._text(
            "Bu ekranda yalnızca sağlık biriminin seninle paylaştığı özet görünür. Tanı, tedavi ve test ayrıntıları "
            "yalnızca sağlık birimindedir; sorularını doktor ya da fizyoterapistinle konuşabilirsin.", "noteText"))
        self.health_box.addStretch(1)

    def _refresh_feedback(self):
        clear_layout(self.feedback_box)
        card, lay = self._card()
        items = sorted(self.data.get("feedback", {}).get(self.player["id"], []), key=lambda f: f.get("ts", ""), reverse=True)
        if not items:
            lay.addWidget(self._text("Teknik kadro henüz seninle bir not paylaşmadı."))
        for f in items:
            row = QFrame()
            row.setObjectName("rowLine")
            v = QVBoxLayout(row)
            v.setContentsMargins(0, 12, 0, 10)
            v.setSpacing(4)
            stars = "★" * int(f.get("rating", 0)) + "☆" * (5 - int(f.get("rating", 0)))
            v.addWidget(self._text(f"{format_dt(f.get('ts', ''))}   {stars}", "dateSub", False))
            v.addWidget(self._text(f.get("text", ""), "cellText"))
            lay.addWidget(row)
        self.feedback_box.addWidget(card)
        self.feedback_box.addStretch(1)

    def _refresh_news(self):
        clear_layout(self.news_box)
        card, lay = self._card()
        news = sorted(self.data.get("announcements", []), key=lambda a: a.get("ts", ""), reverse=True)
        rows = [([format_dt(a.get("ts", "")), two_line(a.get("title", ""), a.get("text", "")), a.get("by", "")], a.get("id", ""))
                for a in news]
        lay.addWidget(build_table([("Tarih", 170), ("Duyuru", 0), ("Yayınlayan", 130)], rows, None, 60, "Duyuru yok."))
        self.news_box.addWidget(card)
        self.news_box.addStretch(1)


# ==========================================================================================
# GİRİŞ EKRANI (departman seçimi) + UYGULAMA DENETLEYİCİSİ
