DEPT_TITLES = {"medya": "Medya", "saglik": "Sağlık", "idari": "İdari", "teknik": "Teknik kadro",
               "diyetisyen": "Diyetisyen", "futbolcu": "Futbolcu"}

DEPT_CARDS = [
    ("medya", "image", "Foto ayıklama, maç takvimi, doğum günleri ve içerik fikirleri.", ""),
    ("saglik", "heart", "Sakatlık ve rehabilitasyon takibi, testler ve randevular.", "PIN ile korunur"),
    ("idari", "briefcase", "Sözleşme ve lisans tarihleri, seyahat planı, belgeler.", "PIN ile korunur"),
    ("teknik", "board", "Antrenman planı, maç hazırlığı ve oyuncu değerlendirme.", "PIN ile korunur"),
    ("diyetisyen", "leaf", "Beslenme planı, vücut ölçümleri, menü, alerji ve takviyeler.", "PIN ile korunur"),
    ("futbolcu", "person", "Kişisel program, kendi sağlık özeti ve duyurular.", "Kişisel PIN"),
]


def hex_to_rgba(color: str, alpha: float) -> str:
    color = color.lstrip("#")
    r, g, b = int(color[0:2], 16), int(color[2:4], 16), int(color[4:6], 16)
    return f"rgba({r}, {g}, {b}, {alpha})"


class LauncherWindow(UiKit, QMainWindow):
    department_chosen = pyqtSignal(str)
    theme_requested = pyqtSignal(str)

    def __init__(self):
        super().__init__()
        self.setWindowTitle("MediaStaffKS — Departman seçimi")
        screen = QApplication.primaryScreen()
        if screen is not None:
            avail = screen.availableGeometry()
            self.resize(min(1360, avail.width() - 40), min(860, avail.height() - 40))
        else:
            self.resize(1360, 860)
        self.setMinimumSize(1100, 640)
        self._build()
        self.setStyleSheet(themed_stylesheet("medya"))
        self.clock_timer = QTimer(self)
        self.clock_timer.setInterval(250)  # saniye değişimini gecikmesiz yakalamak için
        self.clock_timer.timeout.connect(self._tick_clock)
        self.clock_timer.start()
        self._tick_clock()

    def _build(self):
        root = QWidget()
        root.setObjectName("root")
        self.setCentralWidget(root)
        outer = QVBoxLayout(root)
        outer.setContentsMargins(48, 36, 48, 32)
        outer.setSpacing(0)

        header = QHBoxLayout()
        header.addWidget(BrandMark(size=72))
        header.addSpacing(16)
        brand = QVBoxLayout()
        brand.setSpacing(4)
        title = QLabel("MediaStaffKS")
        title.setObjectName("pageTitle")
        sub = QLabel("Kocaelispor Kulüp Yönetim Sistemi")
        sub.setObjectName("pageSub")
        brand.addWidget(title)
        brand.addWidget(sub)
        header.addLayout(brand)
        header.addStretch(1)
        pill = QFrame()
        pill.setObjectName("pill")
        pill.setFixedHeight(44)
        pl = QHBoxLayout(pill)
        pl.setContentsMargins(18, 0, 18, 0)
        pl.setSpacing(10)
        pl.addWidget(self._icon_label("calendar", K_GREEN_HI, 18))
        self.date_label = QLabel("—")
        self.date_label.setObjectName("pillText")
        dot = QLabel("·")
        dot.setObjectName("pillDot")
        self.time_label = QLabel("--:--:--")
        self.time_label.setObjectName("pillTime")
        self.time_label.setStyleSheet(f"font-family: {FONT_MONO};")
        self.time_label.setMinimumWidth(80)
        pl.addWidget(self.date_label)
        pl.addWidget(dot)
        pl.addWidget(self.time_label)
        header.addWidget(self._build_theme_switch())
        header.addSpacing(10)
        header.addWidget(pill)
        outer.addLayout(header)

        body = QVBoxLayout()
        body.setSpacing(36)
        body.addStretch(1)
        heading = QVBoxLayout()
        heading.setSpacing(12)
        self.greet_label = QLabel(self._greeting())
        self.greet_label.setStyleSheet(f"color: {K_GREEN_HI}; font-size: 15px; font-weight: 600;")
        heading.addWidget(self.greet_label)
        h1 = QLabel("Hangi departmanla devam ediyorsun?")
        h1.setStyleSheet(f"font-family: {FONT_DISPLAY}; font-size: 40px; font-weight: 700;")
        h2 = QLabel("Her departmanın kendi ekranı ve yetkisi var. Sağlık ve idari veriler yalnızca o departmanın "
                    "kullanıcılarına açılır.")
        h2.setObjectName("rowSub")
        h2.setWordWrap(True)
        heading.addWidget(h1)
        heading.addWidget(h2)
        body.addLayout(heading)

        grid = QHBoxLayout()
        grid.setSpacing(16)
        self._tiles = {}
        self._last_slots = {}
        prev = None
        for n, (key, icon, desc, lock) in enumerate(
                [c for c in DEPT_CARDS if c[0] in VISIBLE_DEPARTMENTS], start=1):
            tile = self._tile(key, icon, desc, lock, n)
            self._tiles[key] = tile
            grid.addWidget(tile)
            # 1–4 tuşlarıyla hızlı giriş
            sc = QShortcut(QKeySequence(str(n)), self)
            sc.activated.connect(lambda k=key: self.department_chosen.emit(k))
            if prev is not None:
                QWidget.setTabOrder(prev, tile)
            prev = tile
        body.addLayout(grid)
        body.addStretch(1)
        outer.addWidget(self._scroll_wrap(body), 1)

        footer = QHBoxLayout()
        self.remember_toggle = ToggleSwitch(False)
        footer.addWidget(self.remember_toggle)
        footer.addSpacing(10)
        footer.addWidget(self._text("Sonraki açılışta bu seçimi hatırla", "cellText", False))
        footer.addStretch(1)
        footer.addWidget(self._text(f"1–{len(VISIBLE_DEPARTMENTS)} tuşlarıyla hızlı giriş  ·  Tab / Enter ile de seçebilirsin", "dateSub", False))
        footer.addSpacing(24)
        footer.addWidget(self._icon_label("shield", K_DIM, 16))
        footer.addWidget(self._text("Departman verileri bu bilgisayarda saklanır, diğer departmanlar göremez.",
                                    "dateSub", False))
        outer.addLayout(footer)

    def _scroll_wrap(self, layout) -> QWidget:
        inner = QWidget()
        inner.setLayout(layout)
        return self._scroll(inner)

    def _build_theme_switch(self) -> QWidget:
        """Başlıkta Gece / Orman / Gün Işığı seçici; seçim anında uygulanır ve kaydedilir."""
        box = QFrame()
        box.setObjectName("pill")
        box.setFixedHeight(44)
        lay = QHBoxLayout(box)
        lay.setContentsMargins(6, 0, 6, 0)
        lay.setSpacing(4)
        group = QButtonGroup(self)
        group.setExclusive(True)
        for tkey, tname in THEME_NAMES.items():
            btn = QPushButton(tname)
            btn.setObjectName("segBtn")
            btn.setCheckable(True)
            btn.setChecked(tkey == ACTIVE_THEME)
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            btn.setToolTip(THEME_HINTS[tkey])
            btn.clicked.connect(lambda checked=False, k=tkey: self.theme_requested.emit(k))
            group.addButton(btn)
            lay.addWidget(btn)
        return box

    @staticmethod
    def _greeting() -> str:
        hour = datetime.now().hour
        if hour < 5:
            return "İyi geceler"
        if hour < 12:
            return "Günaydın"
        if hour < 18:
            return "İyi günler"
        return "İyi akşamlar"

    def set_last(self, key: str):
        """Son kullanılan departmanın kartına 'Son kullanılan' etiketi koyar."""
        for k, slot in self._last_slots.items():
            while slot.count():
                item = slot.takeAt(0)
                w = item.widget()
                if w is not None:
                    w.deleteLater()
            if k == key:
                slot.addWidget(make_chip("Son kullanılan", K_GREEN_HI, "#16201B"))

    def _tile(self, key: str, icon: str, desc: str, lock: str, number: int = 0) -> QFrame:
        accent = ACCENTS[key]
        tile = ClickableFrame()
        tile.setObjectName("tile")
        tile.setMinimumHeight(330)
        tile.setCursor(Qt.CursorShape.PointingHandCursor)
        tile.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        tile.clicked.connect(lambda k=key: self.department_chosen.emit(k))
        lay = QVBoxLayout(tile)
        lay.setContentsMargins(24, 24, 24, 24)
        lay.setSpacing(0)

        top = QHBoxLayout()
        box = QLabel()
        box.setFixedSize(56, 56)
        box.setAlignment(Qt.AlignmentFlag.AlignCenter)
        box.setStyleSheet(f"background-color: {hex_to_rgba(accent['acc'], 0.16)}; border-radius: 16px;")
        pix = make_pixmap(icon, accent["hi"], 28)
        if pix is not None:
            box.setPixmap(pix)
        top.addWidget(box)
        top.addSpacing(10)
        last_slot = QHBoxLayout()
        last_slot.setContentsMargins(0, 0, 0, 0)
        self._last_slots[key] = last_slot
        top.addLayout(last_slot)
        top.addStretch(1)
        if number:
            badge = QLabel(str(number))
            badge.setFixedSize(28, 28)
            badge.setAlignment(Qt.AlignmentFlag.AlignCenter)
            badge.setStyleSheet(f"color: {K_MUTED}; border: 1px solid {K_LINE}; border-radius: 8px; "
                                f"font-size: 13px; font-weight: 600;")
            badge.setToolTip(f"{number} tuşuna basarak da açabilirsin")
            top.addWidget(badge, 0, Qt.AlignmentFlag.AlignTop)
        lay.addLayout(top)
        lay.addSpacing(22)

        name = QLabel(DEPT_TITLES[key])
        name.setStyleSheet(f"font-family: {FONT_DISPLAY}; font-size: 24px; font-weight: 700;")
        lay.addWidget(name)
        lay.addSpacing(10)
        d = QLabel(desc)
        d.setObjectName("rowSub")
        d.setWordWrap(True)
        lay.addWidget(d)
        lay.addStretch(1)

        bottom = QHBoxLayout()
        if lock:
            chip = make_chip(lock, "#B9C8BF", "#16201B")
        else:
            chip = make_chip("Serbest giriş", K_MUTED, "#16201B")
        bottom.addWidget(chip, 0, Qt.AlignmentFlag.AlignVCenter)
        bottom.addStretch(1)
        bottom.addWidget(self._icon_label("arrow", "#B9C8BF", 16))
        lay.addLayout(bottom)
        return tile

    def set_remember(self, remember: bool):
        self.remember_toggle.setChecked(remember)

    def _tick_clock(self):
        now = datetime.now()
        self.date_label.setText(f"{DAYS_TR[now.weekday()]}, {now.day} {TURKISH_MONTHS[now.month]} {now.year}")
        self.time_label.setText(now.strftime("%H:%M:%S"))


class AppController(QObject):
    """Giriş ekranı ↔ departman pencereleri arasındaki geçişi ve PIN akışını yönetir."""

    def __init__(self):
        super().__init__()
        self.launcher = LauncherWindow()
        self.launcher.department_chosen.connect(self._on_chosen)
        self.launcher.theme_requested.connect(self._on_theme)
        self.window = None
        self.shared = SharedStore()
        self.pins = PlayerPins()

    def start(self):
        daily_backup()
        cfg = load_config()
        key = cfg.get("last_dept", "")
        self.launcher.set_remember(bool(cfg.get("remember_dept")))
        if key in VISIBLE_DEPARTMENTS:
            self.launcher.set_last(key)
        QTimer.singleShot(1500, lambda: start_update_check(self.launcher))
        if cfg.get("remember_dept") and key in VISIBLE_DEPARTMENTS and self.open_department(key):
            return
        self.show_launcher()

    def show_launcher(self):
        self.launcher.show()
        self.launcher.raise_()
        self.launcher.activateWindow()
        self._close_window()

    def _close_window(self):
        window, self.window = self.window, None
        if window is not None:
            window.close()
            window.deleteLater()

    def _on_theme(self, key: str):
        """Temayı kaydeder, uygular ve giriş ekranını yeni renklerle yeniden kurar (yeniden başlatma yok)."""
        cfg = load_config()
        cfg["theme"] = key
        save_config(cfg)
        apply_theme(key)
        app = QApplication.instance()
        if app is not None:
            app.setPalette(build_app_palette())
        old = self.launcher
        remember = old.remember_toggle.isChecked()
        geometry = old.geometry()
        new = LauncherWindow()
        new.department_chosen.connect(self._on_chosen)
        new.theme_requested.connect(self._on_theme)
        new.set_remember(remember)
        last = cfg.get("last_dept", "")
        if last in VISIBLE_DEPARTMENTS:
            new.set_last(last)
        new.setGeometry(geometry)
        self.launcher = new
        new.show()
        old.close()
        old.deleteLater()

    def _on_chosen(self, key: str):
        cfg = load_config()
        cfg["remember_dept"] = self.launcher.remember_toggle.isChecked()
        cfg["last_dept"] = key
        save_config(cfg)
        self.open_department(key)

    def _unlock_store(self, key: str):
        parent = self.launcher
        if not CRYPTO_OK:
            QMessageBox.warning(parent, "Paket eksik",
                                "Bu departman şifreli saklama kullanır ve 'cryptography' paketi gerekir.\n\n"
                                "Terminalde şunu çalıştır:\n    pip install cryptography\n\nSonra uygulamayı yeniden aç.")
            return None
        title = DEPT_TITLES[key]
        style = themed_stylesheet(key)
        store = SecureStore(os.path.join(APP_DIR, STORE_FILES[key]), DEFAULT_FACTORIES[key])
        if not store.exists():
            setup = PinSetupDialog(title, parent)
            setup.setStyleSheet(style)
            if not setup.exec():
                return None
            code = store.create(setup.pin())
            shown = RecoveryCodeDialog(code, parent)
            shown.setStyleSheet(style)
            shown.exec()
            return store
        dlg = UnlockDialog(title, store, parent)
        dlg.setStyleSheet(style)
        return store if dlg.exec() else None

    def open_department(self, key: str) -> bool:
        window = None
        try:
            if key == "medya":
                window = MainWindow()
            elif key in STORE_FILES:
                store = self._unlock_store(key)
                if store is None:
                    return False
                cls = {"saglik": HealthWindow, "idari": AdminWindow, "teknik": StaffWindow, "diyetisyen": DietWindow}[key]
                window = cls(store, self.shared, None, self.pins)
                if key == "saglik":
                    window.publish_availability()
                elif key == "idari":
                    window.publish_travel()
                elif key == "teknik":
                    window.publish_training()
            elif key == "futbolcu":
                dlg = PlayerLoginDialog(self.pins, self.launcher)
                dlg.setStyleSheet(themed_stylesheet("futbolcu"))
                if not dlg.exec():
                    return False
                window = PlayerWindow(None, self.shared, dlg.player, self.pins)
        except Exception:
            import traceback
            details = traceback.format_exc()
            print(details, file=sys.stderr)
            try:
                log_path = os.path.join(APP_DIR, "crash_log.txt")
                with open(log_path, "a", encoding="utf-8") as fh:
                    fh.write(f"\n--- {datetime.now().isoformat()} ({key}) ---\n{details}\n")
            except Exception:
                log_path = None
            box = QMessageBox(self.launcher)
            box.setIcon(QMessageBox.Icon.Critical)
            box.setWindowTitle("Beklenmeyen hata")
            msg = f"'{DEPT_TITLES.get(key, key)}' açılırken bir hata oluştu:\n\n{details}"
            if log_path:
                msg += f"\n(Ayrıca kaydedildi: {log_path})"
            box.setText(msg)
            box.exec()
            return False
        if window is None:
            return False

        window.switch_requested.connect(self.show_launcher)
        if hasattr(window, "lock_requested"):
            window.lock_requested.connect(lambda k=key: self._relock(k))
        window.show()
        self._close_window()
        self.window = window
        self.launcher.hide()
        return True

    def _relock(self, key: str):
        # Son görünür pencere kapanınca uygulama çıkmasın diye önce giriş ekranını göster.
        self.launcher.show()
        self._close_window()
        self.open_department(key)


# ==========================================================================================
# UYGULAMA GİRİŞ NOKTASI
# ==========================================================================================

def run_selftest() -> int:
    """Paketlenmiş uygulamanın gerekli parçalarının hepsini içerip içermediğini ekran açmadan denetler
    (CI'da yayından önce çalıştırılır: MediaStaffKS --selftest)."""
    problems = []

    def check(label, fn):
        try:
            fn()
            print(f"OK    {label}")
        except Exception as e:  # noqa: BLE001
            problems.append(label)
            print(f"HATA  {label}: {e!r}")

    def _imp(name):
        return lambda: __import__(name)

    for mod in ("cv2", "numpy", "onnxruntime", "insightface.app", "insightface.model_zoo",
                "cryptography.fernet", "certifi"):
        check(f"import {mod}", _imp(mod))

    def _web():
        if not HAS_WEBENGINE:
            raise RuntimeError("PyQt6-WebEngine pakette yok")
    check("QtWebEngine", _web)

    def _web_helper():
        if is_frozen():
            # Qt yardımcıyı tam bu yolda arar; yoksa WebEngine açılırken uygulama çöker
            helper = (Path(sys.executable).resolve().parent.parent / "Frameworks" / "PyQt6" / "Qt6" / "lib" /
                      "QtWebEngineCore.framework" / "Helpers" / "QtWebEngineProcess.app" /
                      "Contents" / "MacOS" / "QtWebEngineProcess")
            if not helper.is_file():
                raise RuntimeError(f"QtWebEngineProcess Qt'nin baktığı yolda yok: {helper}")
    check("QtWebEngineProcess", _web_helper)

    def _logo():
        app = QApplication.instance() or QApplication(sys.argv[:1])
        p = club_logo_source_path()
        if p is None or QPixmap(str(p)).isNull():
            raise RuntimeError("kulüp logosu bulunamadı/yüklenemedi")
    check("Qt + kulüp logosu", _logo)
    def _ksmedya():
        # Dosya yoksa uygulama gömülü yedeği (KSMEDYA_LOGO_BASE64) kullanır; yedek de yoksa hata
        if ks_data.find_asset(*KSMEDYA_LOGO_FILENAMES) is None and not KSMEDYA_LOGO_BASE64.strip():
            raise RuntimeError("ksmedya_logo.png ve gömülü yedeği yok")
    check("ksmedya logosu", _ksmedya)
    check("veri katmanı", lambda: ks_data.load_data())
    print(f"Sürüm {APP_VERSION} · frozen={is_frozen()} · veri klasörü={ks_data.user_data_dir()}")
    print("SELFTEST " + ("BAŞARISIZ: " + ", ".join(problems) if problems else "BAŞARILI"))
    return 1 if problems else 0


_ERR_NOTICE = {"sig": "", "t": 0.0, "open": False}


def _show_error_notice():
    if _ERR_NOTICE["open"]:
        return
    try:
        _ERR_NOTICE["open"] = True
        box = QMessageBox(QApplication.activeWindow())
        box.setIcon(QMessageBox.Icon.Warning)
        box.setWindowTitle("Beklenmeyen hata")
        box.setText("Bir şey ters gitti ama uygulama açık kalıyor.")
        box.setInformativeText("Ayrıntı hata kaydına yazıldı (~/.kocaelispor_foto_ayiklama/hata.log). "
                               "Sorun tekrar ederse bu dosyayı bana gönder.")
        box.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        box.destroyed.connect(lambda *_: _ERR_NOTICE.update(open=False))
        box.open()
    except Exception:  # noqa: BLE001
        _ERR_NOTICE["open"] = False


def _global_excepthook(exc_type, exc, tb):
    """Yakalanmamış hata: PyQt6 normalde uygulamayı çökertir. Kaydet, kullanıcıya tek sakin uyarı göster, çalışmaya devam et."""
    import traceback
    text = "".join(traceback.format_exception(exc_type, exc, tb))
    print(text, file=sys.stderr)
    if issubclass(exc_type, KeyboardInterrupt):
        return
    log_error(text)
    try:
        sig = f"{exc_type.__name__}:{exc}"[:200]
        now = time.time()
        if sig == _ERR_NOTICE["sig"] and now - _ERR_NOTICE["t"] < 600:
            return   # aynı hata için 10 dk içinde ikinci uyarı gösterme
        _ERR_NOTICE.update(sig=sig, t=now)
        QTimer.singleShot(0, _show_error_notice)
    except Exception:  # noqa: BLE001
        pass


def _install_error_hooks():
    sys.excepthook = _global_excepthook
    try:
        import threading
        threading.excepthook = lambda args: log_error(
            "Arka plan iş parçacığı hatası:\n" + "".join(__import__("traceback").format_exception(
                args.exc_type, args.exc_value, args.exc_traceback)))
    except Exception:  # noqa: BLE001
        pass


def main():
    if "--selftest" in sys.argv:
        sys.exit(run_selftest())
    _install_error_hooks()
    app = QApplication(sys.argv)
    app.setStyle("Fusion")
    load_local_fonts()
    logo_path = club_logo_source_path()
    if logo_path is not None:
        app.setWindowIcon(QIcon(str(logo_path)))  # görev çubuğu / pencere başlığı simgesi

    apply_theme(load_config().get("theme", "gece"))   # pencereler kurulmadan önce

    palette = build_app_palette()
    app.setPalette(palette)

    controller = AppController()
    QTimer.singleShot(0, controller.start)   # olay döngüsü çalışırken başlat
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
